def _worker_ledger_root(output_root: Path) -> Path:
    root = _absolute(output_root)
    canonical_output = _absolute(contract.V1_3_5_OUTPUT_ROOT)
    if root == canonical_output:
        canonical_worker_root = _absolute(contract.V1_3_5_WORKER_LEDGER_ROOT)
        _require(
            canonical_worker_root.parent == root.parent,
            "Canonical v1.3.5 worker-ledger root drifted.",
        )
        return canonical_worker_root
    suffix = contract.V1_3_5_WORKER_LEDGER_ROOT.name.removeprefix(
        f".{contract.V1_3_5_OUTPUT_ROOT.name}."
    )
    _require(bool(suffix), "V1.3.5 worker-ledger suffix is empty.")
    return root.parent / f".{root.name}.{suffix}"

def _worker_ledger_path(output_root: Path, *, worker_index: int, worker_count: int) -> Path:
    return _worker_ledger_root(output_root) / (
        f"worker-{worker_index:05d}-of-{worker_count:05d}.summary.json"
    )


