def _process_start_ticks(pid: int) -> int:
    try:
        raw = Path(f"/proc/{pid}/stat").read_text(encoding="utf-8")
        closing = raw.rfind(")")
        fields = raw[closing + 2 :].split()
        value = int(fields[19])
    except (OSError, ValueError, IndexError) as error:
        raise ValueError(f"Cannot bind controller claim to process {pid}.") from error
    _require(value > 0, "Controller claim process start time is invalid.")
    return value


def coordinates() -> tuple[ShardCoordinate, ...]:
    result: list[ShardCoordinate] = []
    for payload in contract.quality_coordinates():
        result.append(
            ShardCoordinate(
                scale=cast(str, payload["scale"]),
                training_seed=cast(int, payload["training_seed"]),
                calibration_seed=cast(int, payload["calibration_seed"]),
                evaluation_seed=cast(int, payload["evaluation_seed"]),
                budget=cast(str, payload["budget"]),
                family=cast(str, payload["family"]),
                context=cast(int, payload["context"]),
                replicate=cast(int, payload["replicate"]),
                generation_seed=cast(int, payload["generation_seed"]),
            )
        )
    _require(len(result) == EXPECTED_SHARDS == 9_000, "Direct grid is not exactly 9,000 shards.")
    _require(len({item.key for item in result}) == len(result), "Direct grid repeats a shard.")
    _require(
        tuple(item.payload for item in result) == contract.quality_coordinates(),
        "Runner coordinate representation differs from the v1.3 contract.",
    )
    return tuple(result)

def coordinate_digest() -> str:
    digest = contract.quality_coordinate_digest()
    _require(
        digest == contract.json_digest([item.payload for item in coordinates()]),
        "Runner coordinate digest differs from the v1.3 contract.",
    )
    return digest

def expected_decode_token_rows(coordinate: ShardCoordinate) -> int:
    return (
        contract.DECODE_TOKENS_PER_EXAMPLE_BY_FAMILY_CONTEXT[coordinate.family][coordinate.context]
        * EXAMPLES_PER_SHARD
        * len(ARM_NAMES)
    )


def projected_decode_token_rows(items: Sequence[ShardCoordinate]) -> int:
    total = sum(expected_decode_token_rows(item) for item in items)
    _require(total > 0, "Projected remaining coordinate token weight is empty.")
    return total


def _absolute(path: Path) -> Path:
    return Path(os.path.abspath(path))


def _exact_resolved_path(path: Path, *, label: str) -> Path:
    absolute = _absolute(path)
    _require(not absolute.is_symlink(), f"{label} may not be a symbolic link.")
    try:
        resolved = absolute.resolve(strict=False)
    except OSError as error:
        raise ValueError(f"{label} cannot be resolved safely.") from error
    _require(resolved == absolute, f"{label} must use its exact resolved path.")
    return absolute


def _paths_overlap(left: Path, right: Path) -> bool:
    return left == right or left.is_relative_to(right) or right.is_relative_to(left)


def _matrix_lock_path(output_root: Path) -> Path:
    root = _absolute(output_root)
    _require(
        root == _absolute(contract.V1_3_5_OUTPUT_ROOT),
        "V1.3.5 matrix lock is defined only for the canonical quality output root.",
    )
    return _absolute(contract.V1_3_5_ACTIVATION_MATRIX_LOCK_PATH)

def _canonical_shard_filename(coordinate: ShardCoordinate) -> str:
    return (
        f"direct-{coordinate.scale}-train-{coordinate.training_seed}-{coordinate.budget}-"
        f"{coordinate.family}-context-{coordinate.context}-replicate-{coordinate.replicate}.json"
    )


def shard_output_dir(output_root: Path, coordinate: ShardCoordinate) -> Path:
    return (
        output_root
        / coordinate.scale
        / f"seed-{coordinate.training_seed}"
        / coordinate.budget
        / coordinate.family
        / f"context-{coordinate.context}"
        / f"replicate-{coordinate.replicate}"
    )


def shard_envelope_path(output_root: Path, coordinate: ShardCoordinate) -> Path:
    return shard_output_dir(output_root, coordinate) / _canonical_shard_filename(coordinate)


def canonical_bundle_paths(output_root: Path, coordinate: ShardCoordinate) -> dict[str, Path]:
    envelope = shard_envelope_path(output_root, coordinate)
    return {
        "envelope": envelope,
        **{kind: envelope.with_name(f"{envelope.stem}.{kind}.jsonl.gz") for kind in BUNDLE_KINDS},
    }


def _validate_matrix_layout(
    *,
    output_root: Path,
    matrix_summary: Path,
    training_output_root: Path,
    calibration_output_root: Path,
    reuse_admission_path: Path,
    preheldout_genesis_path: Path,
    attestation_key_path: Path | None,
) -> MatrixLayout:
    root = _exact_resolved_path(output_root, label="Controller v1.3.5 output root")
    summary = _exact_resolved_path(matrix_summary, label="Controller v1.3.5 matrix summary")
    _require(
        root == _exact_resolved_path(
            contract.V1_3_5_OUTPUT_ROOT, label="Canonical controller v1.3.5 output root"
        )
        and summary == root / MATRIX_SUMMARY_NAME,
        "Controller v1.3.5 output and matrix summary must be canonical.",
    )
    training_root = _exact_resolved_path(training_output_root, label="Training input root")
    calibration_root = _exact_resolved_path(calibration_output_root, label="Calibration input root")
    admission_path = _exact_resolved_path(reuse_admission_path, label="Reuse admission")
    genesis_path = _exact_resolved_path(
        preheldout_genesis_path, label="Pre-heldout genesis"
    )
    _require(
        admission_path
        == _exact_resolved_path(
            contract.V1_3_5_REUSE_ADMISSION_PATH,
            label="Canonical v1.3.5 reuse admission",
        )
        and genesis_path
        == _exact_resolved_path(
            contract.V1_3_5_PREHELDOUT_GENESIS_PATH,
            label="Canonical v1.3.5 pre-heldout genesis",
        ),
        "Controller v1.3.5 admission/genesis paths must be canonical.",
    )
    activation_root = _exact_resolved_path(
        contract.V1_3_5_ACTIVATION_ROOT, label="Quality-start activation root"
    )
    activation_path = _exact_resolved_path(
        contract.V1_3_5_QUALITY_START_ACTIVATION_PATH,
        label="Quality-start activation receipt",
    )
    lock_path = _exact_resolved_path(
        contract.V1_3_5_ACTIVATION_MATRIX_LOCK_PATH,
        label="Quality-start activation matrix lock",
    )
    _require(
        activation_path.parent == activation_root
        and lock_path.parent == activation_root
        and activation_path.name != lock_path.name,
        "Quality-start activation exact2 layout drifted.",
    )
    prerequisite_paths = (training_root, calibration_root, admission_path, genesis_path)
    session_ledger_root = _exact_resolved_path(
        persistent_session.session_ledger_root(root),
        label="Persistent session ledger root",
    )
    session_ledger_lock = _exact_resolved_path(
        persistent_session.session_ledger_lock_path(root),
        label="Persistent session ledger lock",
    )
    worker_ledger_root = _exact_resolved_path(
        _worker_ledger_root(root), label="Controller worker-ledger root"
    )
    superseded_calibration_root = _absolute(
        calibration_matrix.SUPERSEDED_OUTPUT_ROOT
    ).resolve(strict=False)
    _require(
        all(
            not _paths_overlap(item, superseded_calibration_root)
            for item in (
                root,
                *prerequisite_paths,
                worker_ledger_root,
                session_ledger_root,
                session_ledger_lock,
            )
        ),
        "Controller paths may not overlap the immutable revision 1.1 calibration quarantine.",
    )
    _require(
        all(
            not _paths_overlap(left, right)
            for index, left in enumerate(prerequisite_paths)
            for right in prerequisite_paths[index + 1 :]
        ),
        "Controller prerequisites must be pairwise disjoint.",
    )
    _require(
        all(not _paths_overlap(root, item) for item in prerequisite_paths),
        "Controller output root must be disjoint from every prerequisite.",
    )
    sibling_paths = (
        activation_root,
        worker_ledger_root,
        session_ledger_root,
        session_ledger_lock,
    )
    _require(
        all(
            not _paths_overlap(left, right)
            for index, left in enumerate(sibling_paths)
            for right in sibling_paths[index + 1 :]
        )
        and all(not _paths_overlap(root, item) for item in sibling_paths),
        "Controller output and sibling ledger/lock paths must be pairwise disjoint.",
    )
    _require(
        all(
            not _paths_overlap(sibling, item)
            for sibling in sibling_paths
            for item in prerequisite_paths
        ),
        "Controller sibling ledgers/locks may not overlap prerequisites.",
    )
    if attestation_key_path is not None:
        key = _exact_resolved_path(attestation_key_path, label="Attestation key")
        _require(
            not key.is_relative_to(REPOSITORY_ROOT.resolve(strict=True)),
            "Attestation key must be outside the repository.",
        )
        _require(
            not _paths_overlap(key, root)
            and not _paths_overlap(key, activation_root)
            and not _paths_overlap(
                key,
                _exact_resolved_path(
                    admission.V1_3_5_ACTIVATION_BOOTSTRAP_LOCK_PATH,
                    label="Activation bootstrap lock",
                ),
            )
            and not _paths_overlap(
                key,
                _exact_resolved_path(
                    contract.DIRECT_GPU_SCHEDULER_LOCK_PATH,
                    label="Canonical GPU scheduler lock",
                ),
            )
            and all(not _paths_overlap(key, item) for item in sibling_paths)
            and all(not _paths_overlap(key, item) for item in prerequisite_paths),
            "Attestation key must be disjoint from all controller paths.",
        )
    all_paths: set[Path] = set()
    for coordinate in coordinates():
        bundle = canonical_bundle_paths(root, coordinate)
        _require(
            not any(path in all_paths for path in bundle.values()),
            "Canonical evaluator bundle paths collide.",
        )
        all_paths.update(bundle.values())
        _require(summary not in bundle.values(), "Matrix summary collides with a shard bundle.")
    return MatrixLayout(
        output_root=root,
        matrix_summary=summary,
        activation_root=activation_root,
        activation_path=activation_path,
        lock_path=lock_path,
        training_output_root=training_root,
        calibration_output_root=calibration_root,
        reuse_admission_path=admission_path,
        preheldout_genesis_path=genesis_path,
    )

def _write_fd_json(file_descriptor: int, payload: Mapping[str, Any]) -> None:
    encoded = (json.dumps(payload, sort_keys=True, allow_nan=False) + "\n").encode()
    os.lseek(file_descriptor, 0, os.SEEK_SET)
    os.ftruncate(file_descriptor, 0)
    offset = 0
    while offset < len(encoded):
        written = os.write(file_descriptor, encoded[offset:])
        _require(written > 0, "Lock metadata write stalled.")
        offset += written
    os.fsync(file_descriptor)


def _opened_matrix_lock_binding(
    path: Path, *, create: bool, retain_process_guardian: bool = False
) -> dict[str, Any]:
    _require(
        create is False and retain_process_guardian is False,
        "V1.3.5 matrix locks can only be adopted from typed activation authority.",
    )
    no_follow = getattr(os, "O_NOFOLLOW", None)
    _require(no_follow is not None, "Controller locking requires O_NOFOLLOW.")
    try:
        descriptor = os.open(
            path,
            os.O_RDWR | getattr(os, "O_CLOEXEC", 0) | cast(int, no_follow),
        )
    except FileNotFoundError as error:
        raise ValueError("Activated controller matrix lock is missing.") from error
    try:
        opened = os.fstat(descriptor)
        current = os.stat(path, follow_symlinks=False)
        _require(
            stat.S_ISREG(opened.st_mode)
            and (opened.st_dev, opened.st_ino) == (current.st_dev, current.st_ino)
            and opened.st_uid == current.st_uid == os.getuid()
            and opened.st_nlink == current.st_nlink == 1
            and stat.S_IMODE(opened.st_mode) == stat.S_IMODE(current.st_mode) == 0o600,
            "Activated controller lock identity or metadata is unsafe.",
        )
        return {
            "path": str(path),
            "semantics": MATRIX_LOCK_SEMANTICS,
            "persistent_inode": True,
            "device": opened.st_dev,
            "inode": opened.st_ino,
            "uid": opened.st_uid,
            "mode": 0o600,
            "nlink": opened.st_nlink,
            "unlink_on_release": False,
        }
    finally:
        os.close(descriptor)

def _initialize_matrix_lock_binding(path: Path) -> dict[str, Any]:
    del path
    raise RuntimeError(
        "V1.3.5 matrix lock creation is private to publish_quality_start_activation."
    )

def _matrix_lock_binding(path: Path) -> dict[str, Any]:
    return _opened_matrix_lock_binding(path, create=False)


def _assert_lock_path_identity(lock_path: Path, descriptor: int, opened: os.stat_result) -> None:
    try:
        current = os.stat(lock_path, follow_symlinks=False)
    except FileNotFoundError as error:
        raise ValueError("Controller lock path was unlinked while held.") from error
    held = os.fstat(descriptor)
    _require(
        (held.st_dev, held.st_ino)
        == (opened.st_dev, opened.st_ino)
        == (current.st_dev, current.st_ino)
        and held.st_nlink == 1,
        "Controller lock path was replaced or unlinked while held.",
    )


@contextmanager
def _exclusive_matrix_lock(
    lock_path: Path,
    *,
    matrix_summary: Path,
    expected_binding: Mapping[str, Any] | None = None,
) -> Iterator[None]:
    key = str(lock_path)
    thread_id = threading.get_ident()
    with _ACTIVE_MATRIX_LOCKS_GUARD:
        _require(
            _ACTIVE_MATRIX_LOCK_OWNERS.get(key) != thread_id,
            "Controller matrix lock reentry is forbidden.",
        )
        thread_mutex = _MATRIX_THREAD_MUTEXES.setdefault(key, threading.Lock())
    thread_mutex.acquire()
    registered = False
    try:
        with _ACTIVE_MATRIX_LOCKS_GUARD:
            _require(
                key not in _ACTIVE_MATRIX_LOCKS and key not in _ACTIVE_MATRIX_LOCK_OWNERS,
                "Controller matrix thread mutex ownership drifted.",
            )
            _ACTIVE_MATRIX_LOCK_OWNERS[key] = thread_id
            registered = True
            _ACTIVE_MATRIX_LOCKS.add(key)
    except BaseException:
        thread_mutex.release()
        raise
    descriptor: int | None = None
    acquired = False
    owner = {
        "schema_version": 1,
        "semantics": MATRIX_LOCK_SEMANTICS,
        "state": "held",
        "owner_nonce": secrets.token_hex(32),
        "pid": os.getpid(),
        "thread_id": threading.get_ident(),
        "acquired_time_ns": time.time_ns(),
        "matrix_summary": str(matrix_summary),
    }
    try:
        _require(
            lock_path.parent.is_dir() and not lock_path.parent.is_symlink(),
            "Activated matrix-lock parent is missing or unsafe.",
        )
        no_follow = getattr(os, "O_NOFOLLOW", None)
        _require(no_follow is not None, "Controller locking requires O_NOFOLLOW.")
        descriptor = os.open(
            lock_path,
            os.O_RDWR | getattr(os, "O_CLOEXEC", 0) | cast(int, no_follow),
        )
        opened = os.fstat(descriptor)
        current = os.stat(lock_path, follow_symlinks=False)
        _require(stat.S_ISREG(opened.st_mode), "Controller lock is not regular.")
        _require(
            (opened.st_dev, opened.st_ino) == (current.st_dev, current.st_ino),
            "Controller lock path changed while opening.",
        )
        _require(
            opened.st_uid == os.getuid()
            and opened.st_nlink == 1
            and stat.S_IMODE(opened.st_mode) == 0o600,
            "Controller lock ownership, links, or mode are unsafe.",
        )
        if expected_binding is not None:
            _require(
                expected_binding.get("path") == str(lock_path)
                and expected_binding.get("semantics") == MATRIX_LOCK_SEMANTICS
                and expected_binding.get("device") == opened.st_dev
                and expected_binding.get("inode") == opened.st_ino,
                "Controller lock inode differs from its persistent binding.",
            )
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        acquired = True
        current = os.stat(lock_path, follow_symlinks=False)
        _require(
            (opened.st_dev, opened.st_ino) == (current.st_dev, current.st_ino),
            "Controller lock path was replaced before ownership.",
        )
        _write_fd_json(descriptor, owner)
        yield
        _assert_lock_path_identity(lock_path, descriptor, opened)
        _write_fd_json(
            descriptor,
            {**owner, "state": "released", "released_time_ns": time.time_ns()},
        )
        fcntl.flock(descriptor, fcntl.LOCK_UN)
        acquired = False
    finally:
        if descriptor is not None:
            if acquired:
                try:
                    _write_fd_json(
                        descriptor,
                        {
                            **owner,
                            "state": "released-after-error",
                            "released_time_ns": time.time_ns(),
                        },
                    )
                finally:
                    fcntl.flock(descriptor, fcntl.LOCK_UN)
            os.close(descriptor)
        with _ACTIVE_MATRIX_LOCKS_GUARD:
            _ACTIVE_MATRIX_LOCKS.discard(key)
            if registered:
                _require(
                    _ACTIVE_MATRIX_LOCK_OWNERS.pop(key, None) == thread_id,
                    "Controller matrix thread-mutex owner changed while held.",
                )
        thread_mutex.release()


def _assert_cell_claim_binding(binding: Mapping[str, Any]) -> None:
    path = Path(cast(str, binding.get("path")))
    try:
        current = os.stat(path, follow_symlinks=False)
    except FileNotFoundError as error:
        raise ValueError("Controller cell claim path was unlinked while held.") from error
    _require(
        binding.get("semantics") == CELL_CLAIM_SEMANTICS
        and binding.get("device") == current.st_dev
        and binding.get("inode") == current.st_ino
        and stat.S_ISREG(current.st_mode)
        and current.st_uid == os.getuid()
        and current.st_nlink == 1
        and stat.S_IMODE(current.st_mode) == 0o600,
        "Controller cell claim path was replaced or became unsafe.",
    )


@contextmanager
def _exclusive_cell_claim(
    output_dir: Path,
    *,
    coordinate: ShardCoordinate,
    launch_nonce: str,
    worker_index: int | None = None,
    worker_count: int | None = None,
) -> Iterator[dict[str, Any]]:
    output_dir.mkdir(parents=True, exist_ok=True)
    claim_path = output_dir / CELL_CLAIM_NAME
    no_follow = getattr(os, "O_NOFOLLOW", None)
    _require(no_follow is not None, "Cell claims require O_NOFOLLOW.")
    flags = (
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0) | cast(int, no_follow)
    )
    try:
        descriptor = os.open(claim_path, flags, 0o600)
    except FileExistsError as error:
        raise ValueError(
            f"Controller cell already has an orphan or active claim: {coordinate.key}"
        ) from error
    payload = {
        "schema_version": 1,
        "semantics": CELL_CLAIM_SEMANTICS,
        "coordinate": coordinate.payload,
        "launch_nonce": launch_nonce,
        "pid": os.getpid(),
        "process_start_ticks": _process_start_ticks(os.getpid()),
        "worker_index": worker_index,
        "worker_count": worker_count,
        "created_time_ns": time.time_ns(),
    }
    metadata = os.fstat(descriptor)
    binding = {
        "path": str(claim_path),
        "semantics": CELL_CLAIM_SEMANTICS,
        "device": metadata.st_dev,
        "inode": metadata.st_ino,
    }
    release_claim = False
    try:
        _require(
            stat.S_ISREG(metadata.st_mode)
            and metadata.st_uid == os.getuid()
            and stat.S_IMODE(metadata.st_mode) == 0o600
            and metadata.st_nlink == 1,
            "Controller cell claim metadata is unsafe.",
        )
        _write_fd_json(descriptor, payload)
        _assert_cell_claim_binding(binding)
        yield binding
        release_claim = True
    finally:
        try:
            _assert_cell_claim_binding(binding)
            held = os.fstat(descriptor)
            _require(
                (held.st_dev, held.st_ino) == (metadata.st_dev, metadata.st_ino)
                and held.st_nlink == 1,
                "Controller cell claim descriptor drifted while held.",
            )
            if release_claim:
                claim_path.unlink()
                _require(
                    os.fstat(descriptor).st_nlink == 0 and not os.path.lexists(claim_path),
                    "Controller cell claim release did not remove the held path.",
                )
        finally:
            os.close(descriptor)


def _sha256_fd(file_descriptor: int) -> str:
    return attestation.checksum_fd(file_descriptor)


def _file_binding(path: Path, *, payload: Mapping[str, Any] | None = None) -> dict[str, Any]:
    opened = attestation.open_regular_nofollow(path)
    try:
        binding: dict[str, Any] = {
            "path": str(opened.path),
            "sha256": opened.sha256,
            "bytes": opened.bytes,
        }
        if payload is not None:
            binding["payload_sha256"] = payload.get("payload_sha256")
            envelope = payload.get("attestation")
            _require(isinstance(envelope, Mapping), f"Attestation missing from {path}.")
            binding["attestation_mac"] = cast(Mapping[str, Any], envelope).get("mac")
        opened.assert_unchanged()
        return binding
    finally:
        opened.close()


def _worker_ledger_root_binding(output_root: Path, *, worker_count: int) -> dict[str, Any] | None:
    if worker_count == 1:
        return None
    _validate_worker_identity(worker_index=0, worker_count=worker_count)
    root = _exact_resolved_path(
        _worker_ledger_root(output_root), label="Controller worker-ledger root"
    )
    return {
        "path": str(root),
        "semantics": WORKER_LEDGER_ROOT_SEMANTICS,
        "path_semantics": WORKER_LEDGER_PATH_SEMANTICS,
        "worker_count": worker_count,
    }


def _worker_ledger_registry(
    output_root: Path,
    *,
    worker_count: int,
    completed_by_worker: Mapping[int, int],
) -> list[dict[str, Any]]:
    root = _worker_ledger_root(output_root)
    if worker_count == 1:
        _require(
            not completed_by_worker and not root.exists(),
            "Single-worker matrix requires an exact empty worker-ledger registry.",
        )
        return []
    _validate_worker_identity(worker_index=0, worker_count=worker_count)
    _require(
        all(
            type(index) is int and 0 <= index < worker_count and type(count) is int and count >= 0
            for index, count in completed_by_worker.items()
        ),
        "Worker-ledger registry input is invalid.",
    )
    expected = {
        _worker_ledger_path(output_root, worker_index=index, worker_count=worker_count): index
        for index in completed_by_worker
    }
    if not expected:
        if root.exists():
            _require(
                root.is_dir() and not root.is_symlink() and not any(root.iterdir()),
                "Empty worker-ledger registry has a non-empty or unsafe root.",
            )
        return []
    _require(root.is_dir() and not root.is_symlink(), "Worker-ledger root is missing or unsafe.")
    observed = set(root.iterdir())
    _require(
        all(not item.is_symlink() and item.is_file() for item in observed)
        and {_absolute(item) for item in observed} == set(expected),
        "Worker-ledger root inventory differs from the public registry.",
    )
    root_binding = _worker_ledger_root_binding(output_root, worker_count=worker_count)
    _require(root_binding is not None, "Distributed worker-ledger root binding is missing.")
    result: list[dict[str, Any]] = []
    for path, index in sorted(expected.items(), key=lambda item: item[1]):
        payload = _load_json_nofollow(path, label="controller worker ledger registry member")
        envelope = payload.get("attestation")
        _require(isinstance(envelope, Mapping), "Worker-ledger attestation identity is missing.")
        completed = completed_by_worker[index]
        assigned_count = len(_assigned_coordinates(worker_index=index, worker_count=worker_count))
        expected_status = "terminal" if completed == assigned_count else "in_progress"
        _require(
            payload.get("worker_index") == index
            and payload.get("worker_count") == worker_count
            and payload.get("assignment_rule") == WORKER_ASSIGNMENT_RULE
            and payload.get("completed_shards") == completed
            and payload.get("assigned_coordinate_count") == assigned_count
            and payload.get("status") == expected_status,
            "Worker-ledger registry member identity or progress drifted.",
        )
        file_binding = _file_binding(path, payload=payload)
        result.append(
            {
                "worker_index": index,
                "worker_count": worker_count,
                "assignment_rule": WORKER_ASSIGNMENT_RULE,
                "root": dict(cast(Mapping[str, Any], root_binding)),
                "path_semantics": WORKER_LEDGER_PATH_SEMANTICS,
                "relative_path": path.name,
                **file_binding,
                "payload_sha256": payload.get("payload_sha256"),
                "attestation": dict(cast(Mapping[str, Any], envelope)),
                "status": expected_status,
                "completed_shards": completed,
                "assigned_coordinate_count": assigned_count,
            }
        )
    return result


def _load_json_nofollow(path: Path, *, label: str) -> dict[str, Any]:
    opened = attestation.open_regular_nofollow(path)
    try:
        try:
            payload = json.loads(opened.read_bytes().decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise ValueError(f"Invalid {label}: {path}") from error
        _require(isinstance(payload, dict), f"{label} must be a JSON object: {path}")
        opened.assert_unchanged()
        return cast(dict[str, Any], payload)
    finally:
        opened.close()


def _atomic_write_json(path: Path, payload: Mapping[str, Any]) -> None:
    parent = path.parent
    parent_created = False
    try:
        parent.mkdir(mode=0o700, parents=False, exist_ok=False)
        parent_created = True
    except FileExistsError:
        pass
    no_follow = getattr(os, "O_NOFOLLOW", None)
    _require(no_follow is not None, "Atomic JSON publication requires O_NOFOLLOW.")
    parent_descriptor = os.open(
        parent,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
        | cast(int, no_follow),
    )
    try:
        if parent_created:
            os.fchmod(parent_descriptor, 0o700)
        opened_parent = os.fstat(parent_descriptor)
        current_parent = os.stat(parent, follow_symlinks=False)
        _require(
            stat.S_ISDIR(opened_parent.st_mode)
            and (opened_parent.st_dev, opened_parent.st_ino)
            == (current_parent.st_dev, current_parent.st_ino)
            and opened_parent.st_uid == current_parent.st_uid == os.getuid()
            and stat.S_IMODE(opened_parent.st_mode)
            == stat.S_IMODE(current_parent.st_mode)
            == 0o700,
            "Atomic JSON parent ownership, identity, or mode is unsafe.",
        )
        os.fsync(parent_descriptor)
    finally:
        os.close(parent_descriptor)
    ancestor_descriptor = os.open(
        parent.parent,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
        | cast(int, no_follow),
    )
    try:
        os.fsync(ancestor_descriptor)
    finally:
        os.close(ancestor_descriptor)
    encoded = (
        json.dumps(payload, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode()
    temporary: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="wb",
            dir=parent,
            prefix=f".{path.name}.",
            suffix=".tmp",
            delete=False,
        ) as handle:
            temporary = Path(handle.name)
            os.fchmod(handle.fileno(), 0o600)
            temporary_metadata = os.fstat(handle.fileno())
            _require(
                stat.S_ISREG(temporary_metadata.st_mode)
                and temporary_metadata.st_uid == os.getuid()
                and temporary_metadata.st_nlink == 1
                and stat.S_IMODE(temporary_metadata.st_mode) == 0o600,
                "Atomic JSON temporary metadata is unsafe.",
            )
            handle.write(encoded)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        temporary = None
        directory_descriptor = os.open(
            parent,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            os.fsync(directory_descriptor)
        finally:
            os.close(directory_descriptor)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)

def _digest_bound_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
    result = dict(payload)
    result.pop("attestation", None)
    result.pop("payload_sha256", None)
    result["payload_sha256"] = contract.json_digest(result)
    return result


def _attested_payload(
    payload: Mapping[str, Any], *, trust_root: attestation.TrustRoot
) -> dict[str, Any]:
    result = _digest_bound_payload(payload)
    result["attestation"] = attestation.attest_payload(
        result, trust_root=trust_root, purpose=MATRIX_ATTESTATION_PURPOSE
    )
    return result


def _verify_attested_payload(
    payload: Mapping[str, Any], *, trust_root: attestation.TrustRoot
) -> None:
    digest = payload.get("payload_sha256")
    source = dict(payload)
    source.pop("attestation", None)
    source.pop("payload_sha256", None)
    _require(
        contract.is_sha256(digest) and digest == contract.json_digest(source),
        "Controller matrix payload digest drifted.",
    )
    envelope = payload.get("attestation")
    _require(isinstance(envelope, Mapping), "Controller matrix attestation is missing.")
    semantic = dict(payload)
    semantic.pop("attestation")
    attestation.verify_attestation(
        semantic,
        cast(Mapping[str, Any], envelope),
        trust_root=trust_root,
        purpose=MATRIX_ATTESTATION_PURPOSE,
    )


def _attested_worker_payload(
    payload: Mapping[str, Any], *, trust_root: attestation.TrustRoot
) -> dict[str, Any]:
    result = _digest_bound_payload(payload)
    result["attestation"] = attestation.attest_payload(
        result,
        trust_root=trust_root,
        purpose=WORKER_ATTESTATION_PURPOSE,
    )
    return result


def _verify_worker_payload(
    payload: Mapping[str, Any], *, trust_root: attestation.TrustRoot
) -> None:
    digest = payload.get("payload_sha256")
    source = dict(payload)
    envelope = source.pop("attestation", None)
    source.pop("payload_sha256", None)
    _require(
        contract.is_sha256(digest) and digest == contract.json_digest(source),
        "Controller worker-ledger payload digest drifted.",
    )
    _require(isinstance(envelope, Mapping), "Controller worker-ledger attestation is missing.")
    semantic = dict(payload)
    semantic.pop("attestation")
    attestation.verify_attestation(
        semantic,
        cast(Mapping[str, Any], envelope),
        trust_root=trust_root,
        purpose=WORKER_ATTESTATION_PURPOSE,
    )


def _canonical_evaluator(candidate: Path) -> Path:
    _require(not candidate.is_symlink(), "Evaluator script may not be a symbolic link.")
    try:
        resolved = candidate.resolve(strict=True)
        canonical = EVALUATOR_SCRIPT.resolve(strict=True)
    except OSError as error:
        raise ValueError("Canonical direct evaluator is missing or inaccessible.") from error
    _require(resolved == canonical, "Evaluator must be the manifest-bound canonical script.")
    return canonical


def _open_evaluator(
    canonical: Path, *, expected: CanonicalEvaluatorSnapshot | None = None
) -> tuple[int, CanonicalEvaluatorSnapshot]:
    no_follow = getattr(os, "O_NOFOLLOW", None)
    _require(no_follow is not None, "Stable evaluator execution requires O_NOFOLLOW.")
    descriptor = os.open(
        canonical,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | cast(int, no_follow),
    )
    try:
        opened = os.fstat(descriptor)
        current = os.stat(canonical, follow_symlinks=False)
        _require(stat.S_ISREG(opened.st_mode), "Canonical evaluator is not regular.")
        _require(
            (opened.st_dev, opened.st_ino) == (current.st_dev, current.st_ino),
            "Canonical evaluator changed while opening.",
        )
        snapshot = CanonicalEvaluatorSnapshot(
            path=str(canonical),
            sha256=_sha256_fd(descriptor),
            bytes=opened.st_size,
            device=opened.st_dev,
            inode=opened.st_ino,
            mode=opened.st_mode,
            mtime_ns=opened.st_mtime_ns,
            ctime_ns=opened.st_ctime_ns,
        )
        if expected is not None:
            _require(snapshot == expected, "Canonical evaluator changed after preflight.")
        return descriptor, snapshot
    except BaseException:
        os.close(descriptor)
        raise


def _sealed_evaluator_copy(descriptor: int, *, expected: CanonicalEvaluatorSnapshot) -> int:
    create = getattr(os, "memfd_create", None)
    allow_sealing = getattr(os, "MFD_ALLOW_SEALING", None)
    _require(
        create is not None and allow_sealing is not None,
        "Stable evaluator execution requires sealed memfd support.",
    )
    sealed = cast(Callable[[str, int], int], create)(
        "adaptive-v4-canonical-direct-evaluator",
        cast(int, getattr(os, "MFD_CLOEXEC", 0)) | cast(int, allow_sealing),
    )
    try:
        offset = 0
        while offset < expected.bytes:
            chunk = os.pread(descriptor, min(1024 * 1024, expected.bytes - offset), offset)
            _require(bool(chunk), "Canonical evaluator truncated during snapshotting.")
            written = 0
            while written < len(chunk):
                count = os.write(sealed, chunk[written:])
                _require(count > 0, "Sealed evaluator write stalled.")
                written += count
            offset += len(chunk)
        _require(_sha256_fd(sealed) == expected.sha256, "Sealed evaluator digest drifted.")
        seals = fcntl.F_SEAL_SEAL | fcntl.F_SEAL_SHRINK | fcntl.F_SEAL_GROW | fcntl.F_SEAL_WRITE
        fcntl.fcntl(sealed, fcntl.F_ADD_SEALS, seals)
        _require(
            fcntl.fcntl(sealed, fcntl.F_GET_SEALS) & seals == seals,
            "Evaluator memfd was not sealed.",
        )
        os.lseek(sealed, 0, os.SEEK_SET)
        return sealed
    except BaseException:
        os.close(sealed)
        raise


def _assert_open_evaluator(descriptor: int, *, expected: CanonicalEvaluatorSnapshot) -> None:
    opened = os.fstat(descriptor)
    current = os.stat(expected.path, follow_symlinks=False)
    _require(
        (
            opened.st_dev,
            opened.st_ino,
            opened.st_size,
            opened.st_mode,
            opened.st_mtime_ns,
            opened.st_ctime_ns,
            _sha256_fd(descriptor),
        )
        == (
            expected.device,
            expected.inode,
            expected.bytes,
            expected.mode,
            expected.mtime_ns,
            expected.ctime_ns,
            expected.sha256,
        ),
        "Open canonical evaluator changed during execution.",
    )
    _require(
        (current.st_dev, current.st_ino) == (expected.device, expected.inode),
        "Canonical evaluator path changed during execution.",
    )


def _run_evaluator_from_snapshot(
    command: Sequence[str],
    *,
    canonical: Path,
    expected: CanonicalEvaluatorSnapshot,
    trust_root: attestation.TrustRoot,
    quality_context: admission.QualityContext,
    gpu_lease: GPULockLease,
    device_guard_lease: GPULockLease,
    projected_shards: int,
    projected_token_rows: int,
) -> subprocess.CompletedProcess[Any]:
    _require(
        type(projected_shards) is int and 1 <= projected_shards <= EXPECTED_SHARDS,
        "Projected remaining shards are outside the frozen matrix.",
    )
    _require(
        type(projected_token_rows) is int
        and 1 <= projected_token_rows <= contract.EXPECTED_RAW_TOKEN_ROWS_WITHOUT_FAILURES,
        "Projected remaining decode-token weight is outside the frozen matrix.",
    )
    gpu_lease.assert_held()
    device_guard_lease.assert_held()
    gpu_descriptor = gpu_lease.fileno()
    device_guard_descriptor = device_guard_lease.fileno()
    inherited_gpu_descriptors = tuple(sorted({gpu_descriptor, device_guard_descriptor}))
    _require(
        all(descriptor >= 0 for descriptor in inherited_gpu_descriptors),
        "Evaluator launch lacks valid inherited GPU lease FDs.",
    )
    descriptor, snapshot = _open_evaluator(canonical, expected=expected)
    sealed: int | None = None
    import_inventory_descriptor: int | None = None
    key_descriptor: int | None = None
    try:
        sealed = _sealed_evaluator_copy(descriptor, expected=snapshot)
        import_inventory_descriptor = _sealed_import_inventory_fd(quality_context)
        key_descriptor = attestation.create_sealed_key_fd(trust_root)
        environment = os.environ.copy()
        environment.pop(attestation.KEY_PATH_ENV, None)
        environment.pop(IMPORT_INVENTORY_FD_ENV, None)
        environment[EVALUATOR_FD_ENV] = str(sealed)
        environment[IMPORT_INVENTORY_FD_ENV] = str(import_inventory_descriptor)
        environment[attestation.KEY_FD_ENV] = str(key_descriptor)
        environment[STORAGE_PROJECTED_SHARDS_ENV] = str(projected_shards)
        environment[STORAGE_PROJECTED_TOKEN_ROWS_ENV] = str(projected_token_rows)
        with _fresh_evaluator_pycache(command):
            result = subprocess.run(
                list(command),
                check=False,
                pass_fds=(
                    sealed,
                    import_inventory_descriptor,
                    key_descriptor,
                    *inherited_gpu_descriptors,
                ),
                env=environment,
            )
        gpu_lease.assert_held()
        device_guard_lease.assert_held()
        _assert_open_evaluator(descriptor, expected=snapshot)
        return result
    finally:
        if key_descriptor is not None:
            os.close(key_descriptor)
        if import_inventory_descriptor is not None:
            os.close(import_inventory_descriptor)
        if sealed is not None:
            os.close(sealed)
        os.close(descriptor)


def _artifact_input_binding(path: Path, payload: Mapping[str, Any]) -> dict[str, Any]:
    binding = _file_binding(path, payload=payload)
    binding["experiment_id"] = payload.get("experiment_id")
    return binding


def _establish_prerequisite_context(
    *,
    manifest_path: Path,
    training_output_root: Path,
    calibration_output_root: Path,
    output_root: Path,
    attestation_key_path: Path | None,
) -> tuple[admission.QualityContext, attestation.TrustRoot, dict[str, Any]]:
    sealed_source_provenance = _validate_live_manifest_against_sealed_source(
        manifest_path
    )
    context = admission.establish_v1_3_5_quality_context(
        manifest_path,
        implementation_paths=contract.V1_3_5_IMPLEMENTATION_PATHS,
        repository_root=REPOSITORY_ROOT,
    )
    raw_attestation = context.manifest_binding.get("attestation")
    _require(isinstance(raw_attestation, Mapping), "Manifest attestation binding is missing.")
    expected_key_id = cast(Mapping[str, Any], raw_attestation).get("key_id")
    _require(contract.is_sha256(expected_key_id), "Manifest attestation key ID is invalid.")
    roots = (
        training_output_root,
        calibration_output_root,
        output_root,
        _absolute(contract.V1_3_5_ADMISSION_ROOT),
        _absolute(contract.V1_3_5_ACTIVATION_ROOT),
    )
    if attestation_key_path is None:
        trust_root = attestation.trust_root_from_environment(
            repository_root=REPOSITORY_ROOT,
            artifact_roots=roots,
            expected_key_id=cast(str, expected_key_id),
        )
    else:
        trust_root = attestation.load_trust_root(
            attestation_key_path,
            repository_root=REPOSITORY_ROOT,
            artifact_roots=roots,
            expected_key_id=cast(str, expected_key_id),
        )
    return context, trust_root, sealed_source_provenance


def _build_base_prerequisites(
    *,
    context: admission.QualityContext,
    trust_root: attestation.TrustRoot,
    sealed_source_provenance: Mapping[str, Any],
    reuse_admission: admission.ValidatedReuseAdmission,
    preheldout_genesis: admission.ValidatedPreheldoutGenesis,
    training_output_root: Path,
    calibration_output_root: Path,
    reuse_admission_path: Path,
    preheldout_genesis_path: Path,
    worker_count: int,
) -> ValidatedBasePrerequisites:
    _require(
        type(worker_count) is int and 1 <= worker_count <= 4,
        "Controller v1.3.5 quality execution requires one to four same-GPU workers.",
    )
    _require(
        Path(cast(str, reuse_admission.public_binding["path"])).resolve(strict=True)
        == reuse_admission_path.resolve(strict=True)
        and Path(cast(str, preheldout_genesis.public_binding["path"])).resolve(strict=True)
        == preheldout_genesis_path.resolve(strict=True),
        "Activated admission/genesis paths differ from the canonical runner layout.",
    )
    projection = contract.v1_3_5_execution_environment_projection(
        reuse_admission.execution_environment_projection
    )
    _require(
        isinstance(projection, Mapping)
        and isinstance(cast(Mapping[str, Any], projection).get("selected_device_class"), Mapping),
        "Reuse admission lacks the frozen execution-environment projection.",
    )
    bundles: dict[tuple[str, int, str], BaseInputBundle] = {}
    validated_calibrations = 0
    for scale in FROZEN_SCALES:
        for training_seed in FROZEN_TRAINING_SEEDS:
            admitted_calibration = reuse_admission.calibrations[(scale, training_seed)]
            calibration_path = admitted_calibration.path
            _require(
                calibration_path.resolve(strict=True).is_relative_to(
                    calibration_output_root.resolve(strict=True)
                ),
                "Admitted calibration is outside the declared calibration root.",
            )
            calibration_payload = _load_json_nofollow(
                calibration_path, label="admitted direct calibration artifact"
            )
            calibration_payload = admission.validate_admitted_calibration(
                calibration_payload,
                artifact_path=calibration_path,
                admission=reuse_admission,
                trust_root=trust_root,
                expected_scale=scale,
                expected_training_seed=training_seed,
            )
            _require(
                _artifact_input_binding(calibration_path, calibration_payload)
                == {
                    field: admitted_calibration.public_binding[field]
                    for field in (
                        "path",
                        "sha256",
                        "bytes",
                        "payload_sha256",
                        "attestation_mac",
                        "experiment_id",
                    )
                },
                "Admitted calibration binding changed during runner validation.",
            )
            validated_calibrations += 1
            checkpoint = calibration_payload.get("checkpoint")
            training_summary = calibration_payload.get("training_summary")
            _require(isinstance(checkpoint, Mapping), "Calibration checkpoint binding is missing.")
            _require(
                isinstance(training_summary, Mapping),
                "Calibration training-summary binding is missing.",
            )
            checkpoint_map = cast(Mapping[str, Any], checkpoint)
            training_summary_map = cast(Mapping[str, Any], training_summary)
            training_matrix_binding = training_summary_map.get("terminal_matrix_ledger")
            _require(
                isinstance(training_matrix_binding, Mapping),
                "Calibration terminal-training-ledger binding is missing.",
            )
            for budget in FROZEN_BUDGETS:
                arms, _metadata = contract.build_direct_controller_arms(
                    calibration_payload,
                    budget,
                    reuse_admission=reuse_admission,
                    trust_root=trust_root,
                    expected_scale=scale,
                    expected_training_seed=training_seed,
                    expected_global_block_budget=contract.DIRECT_GLOBAL_BLOCK_BUDGETS[scale][budget],
                    expected_csa_layers=contract.DIRECT_CSA_LAYERS_BY_SCALE[scale],
                )
                _require(tuple(arms) == ARM_NAMES, "Validated quality arm inventory drifted.")
                input_source = {
                    "source": context.source,
                    "manifest": context.manifest_binding,
                    "checkpoint": dict(checkpoint_map),
                    "training_summary": dict(training_summary_map),
                    "calibration_artifact": _artifact_input_binding(
                        calibration_path, calibration_payload
                    ),
                    "reuse_admission": dict(reuse_admission.public_binding),
                    "preheldout_genesis": dict(preheldout_genesis.public_binding),
                }
                bundles[(scale, training_seed, budget)] = BaseInputBundle(
                    coordinate=(scale, training_seed, budget),
                    checkpoint_path=Path(cast(str, checkpoint_map["path"])),
                    training_summary_path=Path(cast(str, training_summary_map["path"])),
                    training_matrix_summary_path=Path(
                        cast(str, cast(Mapping[str, Any], training_matrix_binding)["path"])
                    ),
                    calibration_path=calibration_path,
                    reuse_admission_path=reuse_admission_path,
                    preheldout_genesis_path=preheldout_genesis_path,
                    calibration_payload=calibration_payload,
                    binding={
                        **input_source,
                        "input_binding_digest": contract.json_digest(input_source),
                    },
                )
    _require(validated_calibrations == 10, "Admitted calibration inventory is incomplete.")
    _require(len(bundles) == 20, "Direct prerequisite bundle inventory is incomplete.")
    public_binding = {
        "sealed_source_provenance": dict(sealed_source_provenance),
        "manifest": context.manifest_binding,
        "reuse_admission": dict(reuse_admission.public_binding),
        "preheldout_genesis": dict(preheldout_genesis.public_binding),
        "execution_environment_projection": dict(cast(Mapping[str, Any], projection)),
        "validated_admitted_calibrations": validated_calibrations,
        "validated_scale_seed_budget_bundles": len(bundles),
        "quality_execution_topology": {
            "worker_count": worker_count,
            "assignment_rule": WORKER_ASSIGNMENT_RULE,
            "shared_local_filesystem_only": True,
        },
    }
    admission.assert_quality_context_unchanged(context)
    return ValidatedBasePrerequisites(
        context=context,
        trust_root=trust_root,
        bundles=bundles,
        public_binding=public_binding,
    )


def load_and_validate_prestart_prerequisites(
    *,
    manifest_path: Path,
    training_output_root: Path,
    calibration_output_root: Path,
    reuse_admission_path: Path,
    preheldout_genesis_path: Path,
    output_root: Path,
    attestation_key_path: Path | None,
    worker_count: int,
) -> tuple[ValidatedBasePrerequisites, admission.PrestartQualityAuthorityV1_3_5]:
    context, trust_root, sealed_source = _establish_prerequisite_context(
        manifest_path=manifest_path,
        training_output_root=training_output_root,
        calibration_output_root=calibration_output_root,
        output_root=output_root,
        attestation_key_path=attestation_key_path,
    )
    prestart = admission.load_prestart_quality_authority(
        quality_context=context,
        trust_root=trust_root,
        expected_shards=EXPECTED_SHARDS,
        coordinate_digest=coordinate_digest(),
        exact_fill_arm_names=ARM_NAMES,
    )
    base = _build_base_prerequisites(
        context=context,
        trust_root=trust_root,
        sealed_source_provenance=sealed_source,
        reuse_admission=prestart.reuse_admission,
        preheldout_genesis=prestart.preheldout_genesis,
        training_output_root=training_output_root,
        calibration_output_root=calibration_output_root,
        reuse_admission_path=reuse_admission_path,
        preheldout_genesis_path=preheldout_genesis_path,
        worker_count=worker_count,
    )
    return base, prestart


def _promote_activated_prerequisites(
    base: ValidatedBasePrerequisites,
    activation: admission.ValidatedQualityStartActivationV1_3_5,
) -> FrozenPrerequisites:
    _require(
        type(base) is ValidatedBasePrerequisites
        and type(activation) is admission.ValidatedQualityStartActivationV1_3_5
        and activation.consumer_coordinate is None
        and activation.payload.get("base_prerequisites_binding")
        == dict(base.public_binding),
        "Activated full-owner prerequisites do not match the frozen prestart base.",
    )
    activation_binding = dict(activation.public_binding)
    activation_path = Path(cast(str, activation_binding["path"]))
    bundles: dict[tuple[str, int, str], InputBundle] = {}
    for coordinate, source_bundle in base.bundles.items():
        input_source = {
            key: value
            for key, value in source_bundle.binding.items()
            if key != "input_binding_digest"
        }
        input_source["quality_start_activation"] = activation_binding
        bundles[coordinate] = InputBundle(
            coordinate=source_bundle.coordinate,
            checkpoint_path=source_bundle.checkpoint_path,
            training_summary_path=source_bundle.training_summary_path,
            training_matrix_summary_path=source_bundle.training_matrix_summary_path,
            calibration_path=source_bundle.calibration_path,
            reuse_admission_path=source_bundle.reuse_admission_path,
            preheldout_genesis_path=source_bundle.preheldout_genesis_path,
            quality_start_activation_path=activation_path,
            calibration_payload=source_bundle.calibration_payload,
            binding={
                **input_source,
                "input_binding_digest": contract.json_digest(input_source),
            },
        )
    public_binding = {
        **dict(base.public_binding),
        "base_prerequisites_sha256": contract.json_digest(base.public_binding),
        "quality_start_activation": activation_binding,
    }
    return FrozenPrerequisites(
        context=base.context,
        trust_root=base.trust_root,
        activation=activation,
        bundles=bundles,
        base_public_binding=dict(base.public_binding),
        public_binding=public_binding,
    )


def load_and_validate_prerequisites(
    *,
    manifest_path: Path,
    training_output_root: Path,
    calibration_output_root: Path,
    reuse_admission_path: Path,
    preheldout_genesis_path: Path,
    output_root: Path,
    attestation_key_path: Path | None,
    expected_worker_count: int | None = None,
    expected_activation_binding: Mapping[str, Any] | None = None,
    sealed_source_provenance: Mapping[str, Any] | None = None,
    sealed_launch_routing: Mapping[str, Any] | None = None,
    gpu_lease: GPULockLease | None = None,
    device_guard_lease: GPULockLease | None = None,
) -> FrozenPrerequisites:
    """Authenticate only the immutable postactivation authority chain."""

    _require(
        (gpu_lease is None) == (device_guard_lease is None),
        "Controller prerequisites require both scheduler and physical-device leases.",
    )
    if gpu_lease is not None and device_guard_lease is not None:
        gpu_lease.assert_held()
        device_guard_lease.assert_held()
    context, trust_root, active_source = _establish_prerequisite_context(
        manifest_path=manifest_path,
        training_output_root=training_output_root,
        calibration_output_root=calibration_output_root,
        output_root=output_root,
        attestation_key_path=attestation_key_path,
    )
    source = active_source if sealed_source_provenance is None else dict(sealed_source_provenance)
    route = sealed_launch_routing
    if route is None:
        raw_route = globals().get("SEALED_LAUNCH_ROUTING_V1_3_5")
        if isinstance(raw_route, Mapping) and raw_route.get("entrypoint_selector") == "matrix":
            route = cast(Mapping[str, Any], raw_route)
    activation = admission.load_activated_quality_authority(
        quality_context=context,
        trust_root=trust_root,
        expected_shards=EXPECTED_SHARDS,
        coordinate_digest=coordinate_digest(),
        exact_fill_arm_names=ARM_NAMES,
        sealed_source_provenance=source,
        sealed_launch_routing=route,
        expected_public_binding=expected_activation_binding,
    )
    raw_base = activation.payload.get("base_prerequisites_binding")
    _require(isinstance(raw_base, Mapping), "Activation base prerequisites are missing.")
    topology = cast(Mapping[str, Any], raw_base).get("quality_execution_topology")
    _require(isinstance(topology, Mapping), "Activated execution topology is missing.")
    bound_worker_count = cast(Mapping[str, Any], topology).get("worker_count")
    _require(
        type(bound_worker_count) is int
        and (expected_worker_count is None or bound_worker_count == expected_worker_count),
        "Activated execution topology differs from the requested worker count.",
    )
    reuse = admission.load_activated_reuse_admission(
        activation,
        trust_root=trust_root,
    )
    genesis = admission.load_activated_preheldout_genesis(
        activation,
        trust_root=trust_root,
        expected_shards=EXPECTED_SHARDS,
        coordinate_digest=coordinate_digest(),
        exact_fill_arm_names=ARM_NAMES,
    )
    base = _build_base_prerequisites(
        context=context,
        trust_root=trust_root,
        sealed_source_provenance=source,
        reuse_admission=reuse,
        preheldout_genesis=genesis,
        training_output_root=training_output_root,
        calibration_output_root=calibration_output_root,
        reuse_admission_path=reuse_admission_path,
        preheldout_genesis_path=preheldout_genesis_path,
        worker_count=cast(int, bound_worker_count),
    )
    _require(
        dict(base.public_binding) == dict(cast(Mapping[str, Any], raw_base)),
        "Rebuilt activated prerequisites differ from the activation receipt.",
    )
    activation = admission.revalidate_activated_quality_authority(
        activation,
        trust_root=trust_root,
    )
    _require(
        activation.payload.get("base_prerequisites_binding")
        == dict(base.public_binding),
        "Revalidated activation differs from the rebuilt prerequisite base.",
    )
    result = _promote_activated_prerequisites(base, activation)
    admission.assert_quality_context_unchanged(context)
    if gpu_lease is not None and device_guard_lease is not None:
        gpu_lease.assert_held()
        device_guard_lease.assert_held()
    return result


QUALITY_START_MODES = ("fresh", "resume", "prerequisites-only")


def _assert_one_cell_full_resume_gate(
    completed: Sequence[Mapping[str, Any]],
) -> None:
    first = _mixed_device_coordinates(contract.V1_3_5_MIXED_DEVICE_SITE)[0]
    _require(
        len(completed) == 1
        and completed[0].get("coordinate_key") == first.key
        and all(
            completed[0].get(field) == expected
            for field, expected in first.payload.items()
        )
        and completed[0].get("integrity_decision") == "INTEGRITY-PASS",
        "One-cell activation prefix failed its canonical integrity gate.",
    )


def _quality_lock_protected_paths(
    *,
    layout: MatrixLayout,
    manifest_path: Path,
    attestation_key_path: Path | None,
) -> tuple[Path, ...]:
    paths = [
        _exact_resolved_path(manifest_path, label="Controller v1.3.5 manifest"),
        layout.output_root,
        layout.matrix_summary,
        layout.activation_root,
        layout.activation_path,
        layout.lock_path,
        layout.training_output_root,
        layout.calibration_output_root,
        layout.reuse_admission_path,
        layout.preheldout_genesis_path,
        _exact_resolved_path(
            admission.V1_3_5_ACTIVATION_BOOTSTRAP_LOCK_PATH,
            label="Activation bootstrap lock",
        ),
        _exact_resolved_path(
            _worker_ledger_root(layout.output_root),
            label="Controller worker-ledger root",
        ),
        _exact_resolved_path(
            persistent_session.session_ledger_root(layout.output_root),
            label="Persistent session ledger root",
        ),
        _exact_resolved_path(
            persistent_session.session_ledger_lock_path(layout.output_root),
            label="Persistent session ledger lock",
        ),
        _exact_resolved_path(
            contract.V1_3_5_INTEGRITY_OUTPUT_PATH,
            label="Controller integrity artifact",
        ),
        _exact_resolved_path(
            contract.V1_3_5_SUMMARY_OUTPUT_PATH,
            label="Controller summary artifact",
        ),
    ]
    paths.extend(
        _exact_resolved_path(
            REPOSITORY_ROOT / relative,
            label="Frozen implementation path",
        )
        for relative in contract.V1_3_5_IMPLEMENTATION_PATHS
    )
    if attestation_key_path is not None:
        paths.append(
            _exact_resolved_path(attestation_key_path, label="Attestation key")
        )
    return tuple(paths)


def _validate_quality_mutating_lock_path(
    path: Path,
    *,
    layout: MatrixLayout,
    manifest_path: Path,
    attestation_key_path: Path | None,
    label: str,
    require_canonical_scheduler: bool,
) -> Path:
    candidate = _exact_resolved_path(path, label=label)
    if require_canonical_scheduler:
        _require(
            candidate
            == _exact_resolved_path(
                contract.DIRECT_GPU_SCHEDULER_LOCK_PATH,
                label="Canonical GPU scheduler lock",
            ),
            "Controller v1.3.5 requires the canonical GPU scheduler lock path.",
        )
    _require(
        not candidate.is_relative_to(REPOSITORY_ROOT.resolve(strict=True)),
        f"{label} must be outside the repository.",
    )
    protected = _quality_lock_protected_paths(
        layout=layout,
        manifest_path=manifest_path,
        attestation_key_path=attestation_key_path,
    )
    if not require_canonical_scheduler:
        protected = (
            *protected,
            _exact_resolved_path(
                contract.DIRECT_GPU_SCHEDULER_LOCK_PATH,
                label="Canonical GPU scheduler lock",
            ),
        )
    _require(
        all(not _paths_overlap(candidate, item) for item in protected),
        f"{label} overlaps a controller input, artifact, authority, or key path.",
    )
    if os.path.lexists(candidate):
        metadata = os.stat(candidate, follow_symlinks=False)
        _require(
            stat.S_ISREG(metadata.st_mode)
            and metadata.st_uid == os.getuid()
            and metadata.st_nlink == 1
            and stat.S_IMODE(metadata.st_mode) == GPU_LOCK_MODE,
            f"{label} has unsafe pre-existing metadata.",
        )
        candidate_identity = (metadata.st_dev, metadata.st_ino)
        for item in protected:
            if not os.path.lexists(item):
                continue
            item_metadata = os.stat(item, follow_symlinks=False)
            _require(
                (item_metadata.st_dev, item_metadata.st_ino) != candidate_identity,
                f"{label} aliases a protected controller inode.",
            )
    return candidate


def _prepare_quality_start_authority(
    *,
    start_mode: str,
    layout: MatrixLayout,
    manifest_path: Path,
    attestation_key_path: Path | None,
    worker_count: int,
    scheduler_lease: GPULockLease | None,
    fresh_prestart: tuple[
        ValidatedBasePrerequisites,
        admission.PrestartQualityAuthorityV1_3_5,
    ] | None = None,
    resume_initial: FrozenPrerequisites | None = None,
) -> tuple[
    FrozenPrerequisites,
    admission.QualityStartActivationLeaseV1_3_5,
]:
    _require(start_mode in {"fresh", "resume"}, "Quality start mode is not mutable.")
    if scheduler_lease is not None:
        scheduler_lease.assert_held()
    sealed_source = _validated_source_provenance()
    sealed_routing = _validated_launch_routing(expected_selector="matrix")
    lease: admission.QualityStartActivationLeaseV1_3_5 | None = None
    returned = False
    try:
        if start_mode == "fresh":
            _require(
                scheduler_lease is not None,
                "Fresh quality activation requires the canonical GPU scheduler lease.",
            )
            _require(resume_initial is None, "Fresh start received resume prerequisites.")
            if fresh_prestart is None:
                base, prestart = load_and_validate_prestart_prerequisites(
                    manifest_path=manifest_path,
                    training_output_root=layout.training_output_root,
                    calibration_output_root=layout.calibration_output_root,
                    reuse_admission_path=layout.reuse_admission_path,
                    preheldout_genesis_path=layout.preheldout_genesis_path,
                    output_root=layout.output_root,
                    attestation_key_path=attestation_key_path,
                    worker_count=worker_count,
                )
            else:
                base, prestart = fresh_prestart
                _require(
                    type(base) is ValidatedBasePrerequisites
                    and type(prestart) is admission.PrestartQualityAuthorityV1_3_5,
                    "Fresh read-only prerequisite handoff is invalid.",
                )
            cast(GPULockLease, scheduler_lease).assert_held()
            lease = admission.publish_quality_start_activation(
                prestart=prestart,
                trust_root=base.trust_root,
                base_prerequisites_binding=base.public_binding,
                sealed_source_provenance=sealed_source,
                sealed_launch_routing=sealed_routing,
            )
            lease.assert_held()
            prerequisites = _promote_activated_prerequisites(base, lease.activation)
            _require(
                prerequisites.base_public_binding == base.public_binding,
                "Fresh activated prerequisites differ from the signed prestart base.",
            )
        else:
            _require(fresh_prestart is None, "Resume received fresh prestart authority.")
            initial = resume_initial
            if initial is None:
                initial = load_and_validate_prerequisites(
                    manifest_path=manifest_path,
                    training_output_root=layout.training_output_root,
                    calibration_output_root=layout.calibration_output_root,
                    reuse_admission_path=layout.reuse_admission_path,
                    preheldout_genesis_path=layout.preheldout_genesis_path,
                    output_root=layout.output_root,
                    attestation_key_path=attestation_key_path,
                    expected_worker_count=worker_count,
                    sealed_source_provenance=sealed_source,
                    sealed_launch_routing=sealed_routing,
                )
            else:
                _require(
                    type(initial) is FrozenPrerequisites,
                    "Resume read-only prerequisite handoff is invalid.",
                )
            lease = admission.acquire_quality_start_activation_lease(
                initial.activation,
                trust_root=initial.trust_root,
            )
            lease.assert_held()
            revalidated = admission.revalidate_activated_quality_authority(
                lease.activation,
                trust_root=initial.trust_root,
            )
            _require(
                revalidated.public_binding == lease.activation.public_binding
                and revalidated.public_binding
                == initial.public_binding["quality_start_activation"],
                "Activated prerequisites changed while acquiring the resume lease.",
            )
            prerequisites = initial
        lease.assert_held()
        if scheduler_lease is not None:
            scheduler_lease.assert_held()
        returned = True
        return prerequisites, lease
    finally:
        if lease is not None and not returned:
            lease.close()


def _activation_lock_binding(
    prerequisites: FrozenPrerequisites,
    lease: admission.QualityStartActivationLeaseV1_3_5,
) -> dict[str, Any]:
    lease.assert_held()
    _require(
        lease.activation.public_binding
        == prerequisites.public_binding["quality_start_activation"]
        and lease.activation.matrix_lock_binding
        == prerequisites.activation.matrix_lock_binding,
        "Held activation lease differs from frozen prerequisites.",
    )
    return dict(lease.activation.matrix_lock_binding)


def _complete_activation_ledger_boundary(
    *,
    start_mode: str,
    layout: MatrixLayout,
    prerequisites: FrozenPrerequisites,
    activation_lease: admission.QualityStartActivationLeaseV1_3_5,
    evaluator_binding: Mapping[str, Any],
    ready_only_preflight: Mapping[str, Any],
    worker_count: int,
    gpu_lease_binding: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Publish or authenticate the first ledger while the activation FD is held."""

    activation_lease.assert_held()
    lock_binding = _activation_lock_binding(prerequisites, activation_lease)
    _require(
        lock_binding["path"] == str(layout.lock_path),
        "Activation matrix-lock path differs from the canonical layout.",
    )
    if os.path.lexists(layout.matrix_summary):
        _require(start_mode == "resume", "Fresh activation observed a pre-existing matrix ledger.")
        payload = _load_json_nofollow(
            layout.matrix_summary, label="activated resume matrix ledger"
        )
        _verify_attested_payload(
            payload,
            trust_root=prerequisites.trust_root,
        )
        _require(
            payload.get("prerequisites") == dict(prerequisites.public_binding)
            and payload.get("matrix_lock") == lock_binding
            and payload.get("ready_only_preflight") == dict(ready_only_preflight)
            and payload.get("worker_count") == worker_count,
            "Resume matrix ledger differs from activated authority.",
        )
        directory_descriptor = os.open(
            layout.output_root,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            os.fsync(directory_descriptor)
        finally:
            os.close(directory_descriptor)
    else:
        if os.path.lexists(layout.output_root):
            _require(
                start_mode == "resume",
                "Fresh activation observed an unexpected canonical output root.",
            )
            root_metadata = os.stat(layout.output_root, follow_symlinks=False)
            _require(
                stat.S_ISDIR(root_metadata.st_mode)
                and root_metadata.st_uid == os.getuid()
                and stat.S_IMODE(root_metadata.st_mode) == 0o700,
                "Activation-only recovery output root is unsafe.",
            )
            interrupted_prefix = f".{layout.matrix_summary.name}."
            interrupted_suffix = ".tmp"
            for member in tuple(layout.output_root.iterdir()):
                metadata = os.stat(member, follow_symlinks=False)
                _require(
                    member.name.startswith(interrupted_prefix)
                    and member.name.endswith(interrupted_suffix)
                    and stat.S_ISREG(metadata.st_mode)
                    and metadata.st_uid == os.getuid()
                    and metadata.st_nlink == 1
                    and stat.S_IMODE(metadata.st_mode) == 0o600,
                    "Activation-only recovery found a non-temporary output entry.",
                )
                member.unlink()
            directory_descriptor = os.open(
                layout.output_root,
                os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
            )
            try:
                os.fsync(directory_descriptor)
            finally:
                os.close(directory_descriptor)
            _require(
                not tuple(layout.output_root.iterdir()),
                "Activation-only recovery output root did not become empty.",
            )
        if worker_count == 1:
            _require(
                gpu_lease_binding is not None,
                "Single-worker zero ledger requires its selected GPU lease binding.",
            )
            payload = _matrix_payload(
                (),
                output_root=layout.output_root,
                prerequisites=prerequisites,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                worker_count=1,
                gpu_worker_leases={
                    0: dict(cast(Mapping[str, Any], gpu_lease_binding))
                },
            )
        else:
            payload = _matrix_payload(
                (),
                output_root=layout.output_root,
                prerequisites=prerequisites,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                worker_count=worker_count,
                gpu_worker_leases={},
                worker_ledger_root=_worker_ledger_root_binding(
                    layout.output_root, worker_count=worker_count
                ),
            )
        _atomic_write_json(layout.matrix_summary, payload)
        _require(
            payload.get("ready_only_preflight") == dict(ready_only_preflight),
            "Initial matrix did not bind the authenticated ready-only preflight.",
        )
        _require(
            _load_json_nofollow(
                layout.matrix_summary, label="initial activated matrix ledger"
            )
            == payload,
            "Initial activated matrix ledger changed after durable publication.",
        )
    activation_lease.assert_held()
    return payload

def _validated_source_provenance() -> dict[str, Any]:
    value = globals().get("SEALED_SOURCE_PROVENANCE_V1_3_5")
    _require(
        isinstance(value, Mapping)
        and set(value)
        == {
            "schema_version",
            "launcher",
            "repository_root",
            "bundle_sha256",
            "pinned_head_oid",
            "frozen_source_commit",
            "implementation_tree_digest",
            "head_manifest",
        },
        "Sealed launcher source provenance is unavailable.",
    )
    checked = dict(cast(Mapping[str, Any], value))
    manifest = checked.get("head_manifest")
    _require(
        checked.get("schema_version") == 1
        and checked.get("launcher")
        == "p2-direct-controller-git-object-launcher-v1-3-5"
        and checked.get("repository_root")
        == str(REPOSITORY_ROOT.resolve(strict=True))
        and contract.is_sha256(checked.get("bundle_sha256"))
        and contract.is_sha256(checked.get("implementation_tree_digest"))
        and contract.is_git_oid(checked.get("pinned_head_oid"))
        and contract.is_git_oid(checked.get("frozen_source_commit"))
        and isinstance(manifest, Mapping)
        and set(cast(Mapping[str, Any], manifest))
        == {"path", "git_mode", "git_blob_oid", "sha256", "bytes", "source_base64"}
        and cast(Mapping[str, Any], manifest).get("git_mode") in {"100644", "100755"}
        and contract.is_sha256(cast(Mapping[str, Any], manifest).get("sha256"))
        and type(cast(Mapping[str, Any], manifest).get("bytes")) is int,
        "Sealed launcher source provenance semantics drifted.",
    )
    try:
        head_payload = json.loads(
            base64.b64decode(
                cast(str, cast(Mapping[str, Any], manifest)["source_base64"]),
                validate=True,
            )
        )
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as error:
        raise ValueError("Sealed HEAD manifest source is invalid.") from error
    implementation = (
        head_payload.get("implementation") if isinstance(head_payload, Mapping) else None
    )
    _require(
        isinstance(implementation, Mapping)
        and implementation.get("source_commit") == checked["frozen_source_commit"]
        and implementation.get("tree_digest") == checked["implementation_tree_digest"],
        "Sealed source provenance differs from decoded HEAD manifest implementation.",
    )
    return checked


def _validate_live_manifest_against_sealed_source(manifest_path: Path) -> dict[str, Any]:
    provenance = _validated_source_provenance()
    expected = cast(Mapping[str, Any], provenance["head_manifest"])
    expected_path = REPOSITORY_ROOT.resolve(strict=True) / cast(str, expected["path"])
    exact = Path(os.path.abspath(manifest_path))
    _require(
        exact == expected_path and exact.resolve(strict=True) == expected_path,
        "Live manifest path differs from the sealed HEAD manifest path.",
    )
    opened = attestation.open_regular_nofollow(exact)
    try:
        data = opened.read_bytes(maximum_bytes=16 << 20)
        blob_source = b"blob " + str(len(data)).encode("ascii") + b"\0" + data
        blob_oid = cast(str, expected["git_blob_oid"])
        observed_blob = hashlib.new(
            "sha1" if len(blob_oid) == 40 else "sha256", blob_source
        ).hexdigest()
        observed_mode = "100755" if opened.mode & 0o111 else "100644"
        _require(
            opened.bytes == expected["bytes"]
            and opened.sha256 == expected["sha256"]
            and observed_blob == blob_oid
            and observed_mode == expected["git_mode"]
            and data
            == base64.b64decode(cast(str, expected["source_base64"]), validate=True),
            "Live manifest bytes differ from the sealed HEAD manifest binding.",
        )
        opened.assert_unchanged()
    finally:
        opened.close()
    return provenance


def _require_launcher_authority() -> dict[str, Any]:
    authority = globals().get("SEALED_LAUNCH_AUTHORITY_V1_3_5")
    _require(
        authority
        == {
            "schema_version": 1,
            "launcher": "p2-direct-controller-git-object-launcher-v1-3-5",
            "sealed_runner": True,
            "sealed_inventory": True,
        },
        "Direct controller mutation requires sealed Git-object launch authority.",
    )
    _validated_launch_routing(expected_selector="matrix")
    runtime = _validated_launcher_python_runtime()
    source = _validated_source_provenance()
    return {
        "launcher": dict(cast(Mapping[str, Any], authority)),
        "python_runtime": runtime,
        "source_provenance": source,
    }


def _validated_launch_routing(*, expected_selector: str) -> dict[str, Any]:
    value = globals().get("SEALED_LAUNCH_ROUTING_V1_3_5")
    expected_paths = {
        "matrix": (
            "research/adaptive_v4_memory/scripts/"
            "run_p2_direct_controller_matrix_v1_3.py"
        ),
        "audit": (
            "research/adaptive_v4_memory/scripts/"
            "audit_p2_direct_controller_integrity_v1_3.py"
        ),
        "summary": (
            "research/adaptive_v4_memory/scripts/"
            "summarize_p2_direct_controller_v1_3.py"
        ),
    }
    _require(
        expected_selector in expected_paths
        and isinstance(value, Mapping)
        and set(value)
        == {
            "schema_version",
            "launcher",
            "entrypoint_selector",
            "entrypoint_relative_path",
            "source_bundle_sha256",
            "git_mode",
            "git_blob_oid",
            "sha256",
            "bytes",
        },
        "Sealed launch routing is unavailable.",
    )
    checked = dict(cast(Mapping[str, Any], value))
    source = _validated_source_provenance()
    relative = expected_paths[expected_selector]
    active_path = Path(cast(str, globals().get("__file__"))).resolve(strict=True)
    _require(
        checked.get("schema_version") == 1
        and checked.get("launcher")
        == "p2-direct-controller-git-object-launcher-v1-3-5"
        and checked.get("entrypoint_selector") == expected_selector
        and checked.get("entrypoint_relative_path") == relative
        and checked.get("source_bundle_sha256") == source["bundle_sha256"]
        and checked.get("git_mode") in {"100644", "100755"}
        and contract.is_git_oid(checked.get("git_blob_oid"))
        and contract.is_sha256(checked.get("sha256"))
        and type(checked.get("bytes")) is int
        and cast(int, checked["bytes"]) > 0
        and active_path == REPOSITORY_ROOT.resolve(strict=True) / relative,
        "Sealed launch routing semantics drifted.",
    )
    return checked


def _validated_launcher_python_runtime() -> dict[str, Any]:
    runtime = globals().get("SEALED_PYTHON_RUNTIME_V1_3_5")
    _require(
        isinstance(runtime, Mapping)
        and set(runtime)
        == {
            "schema_version",
            "implementation",
            "cache_tag",
            "version",
            "executable",
            "venv_executable",
            "resolved_executable",
            "executable_sha256",
            "executable_metadata",
            "base_prefix",
            "site_packages",
        },
        "Sealed launcher Python runtime binding is unavailable.",
    )
    checked = dict(cast(Mapping[str, Any], runtime))
    active = Path("/proc/self/exe").resolve(strict=True)
    metadata = active.stat()
    expected_metadata = checked.get("executable_metadata")
    site_packages = Path(cast(str, checked.get("site_packages")))
    _require(
        checked.get("schema_version") == 1
        and checked.get("implementation") == sys.implementation.name
        and checked.get("cache_tag") == sys.implementation.cache_tag
        and checked.get("version")
        == [
            sys.version_info.major,
            sys.version_info.minor,
            sys.version_info.micro,
            sys.version_info.releaselevel,
            sys.version_info.serial,
        ]
        and checked.get("executable") == str(active)
        and checked.get("resolved_executable") == str(active)
        and Path(cast(str, checked.get("venv_executable"))).resolve(strict=True) == active
        and checked.get("base_prefix") == str(Path(sys.base_prefix).resolve(strict=True))
        and isinstance(expected_metadata, Mapping)
        and dict(cast(Mapping[str, Any], expected_metadata))
        == {
            "device": metadata.st_dev,
            "inode": metadata.st_ino,
            "mode": metadata.st_mode,
            "uid": metadata.st_uid,
            "gid": metadata.st_gid,
            "bytes": metadata.st_size,
        }
        and contract.is_sha256(checked.get("executable_sha256"))
        and site_packages == site_packages.resolve(strict=True)
        and site_packages.is_dir()
        and not site_packages.is_symlink(),
        "Sealed launcher Python runtime binding drifted before evaluator launch.",
    )
    return checked


def _sealed_import_inventory_fd(context: admission.QualityContext) -> int:
    admission.assert_quality_context_unchanged(context)
    python_runtime = _validated_launcher_python_runtime()
    source_provenance = _validated_source_provenance()
    files = [dict(row) for row in admission.quality_implementation_inventory(context)]
    paths = [row.get("path") for row in files]
    _require(
        all(isinstance(path, str) for path in paths)
        and paths == sorted(cast(list[str], paths)),
        "Quality implementation inventory rows are not canonical.",
    )
    source = {
        "repository_root": str(REPOSITORY_ROOT.resolve(strict=True)),
        "files": files,
        "python_runtime": python_runtime,
        "source_provenance": source_provenance,
    }
    payload = {**source, "digest": contract.json_digest(source)}
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    create = getattr(os, "memfd_create", None)
    allow_sealing = getattr(os, "MFD_ALLOW_SEALING", None)
    _require(
        callable(create) and allow_sealing is not None,
        "Import-inventory transport requires sealed memfd support.",
    )
    descriptor = cast(Callable[[str, int], int], create)(
        "adaptive-v4-direct-exact-fill-v1-3-5-import-inventory",
        cast(int, getattr(os, "MFD_CLOEXEC", 0)) | cast(int, allow_sealing),
    )
    try:
        offset = 0
        while offset < len(encoded):
            written = os.write(descriptor, encoded[offset:])
            _require(written > 0, "Import-inventory memfd write stalled.")
            offset += written
        _require(
            os.pread(descriptor, len(encoded), 0) == encoded,
            "Import-inventory memfd bytes drifted.",
        )
        seals = fcntl.F_SEAL_SEAL | fcntl.F_SEAL_SHRINK | fcntl.F_SEAL_GROW | fcntl.F_SEAL_WRITE
        fcntl.fcntl(descriptor, fcntl.F_ADD_SEALS, seals)
        _require(
            fcntl.fcntl(descriptor, fcntl.F_GET_SEALS) & seals == seals,
            "Import-inventory memfd was not sealed.",
        )
        os.lseek(descriptor, 0, os.SEEK_SET)
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise


def _isolated_evaluator_pycache_prefix(launch_nonce: str) -> Path:
    _require(contract.is_sha256(launch_nonce), "Evaluator launch nonce is invalid.")
    root = Path(tempfile.gettempdir()).resolve(strict=True)
    path = root / f"adaptive-v4-direct-exact-fill-v1-3-5-pycache-{launch_nonce}"
    _require(
        not os.path.lexists(path),
        "Fresh evaluator pycache prefix already exists; refusing ambiguous bytecode state.",
    )
    return path


def _evaluator_pycache_prefix_from_command(command: Sequence[str]) -> Path:
    options = [
        value.removeprefix("pycache_prefix=")
        for index, value in enumerate(command)
        if index > 0 and command[index - 1] == "-X" and value.startswith("pycache_prefix=")
    ]
    _require(len(options) == 1, "Evaluator command must bind one isolated pycache prefix.")
    nonce_indices = [index for index, value in enumerate(command) if value == "--launch-nonce"]
    _require(
        len(nonce_indices) == 1 and nonce_indices[0] + 1 < len(command),
        "Evaluator command launch nonce is missing.",
    )
    nonce = command[nonce_indices[0] + 1]
    expected = _isolated_evaluator_pycache_prefix(nonce)
    observed = Path(options[0])
    _require(observed == expected, "Evaluator pycache prefix is not launch-nonce derived.")
    return observed


@contextmanager
def _fresh_evaluator_pycache(command: Sequence[str]) -> Iterator[Path]:
    path = _evaluator_pycache_prefix_from_command(command)
    try:
        os.mkdir(path, mode=0o700)
    except FileExistsError as error:
        raise ValueError("Evaluator pycache prefix lost freshness before launch.") from error
    metadata = os.lstat(path)
    _require(
        stat.S_ISDIR(metadata.st_mode)
        and metadata.st_uid == os.getuid()
        and stat.S_IMODE(metadata.st_mode) == 0o700,
        "Evaluator pycache directory is unsafe.",
    )
    unsafe_contents = False
    try:
        yield path
    finally:
        if os.path.lexists(path):
            current = os.lstat(path)
            if stat.S_ISDIR(current.st_mode):
                unsafe_contents = any(path.iterdir())
                shutil.rmtree(path)
            else:
                unsafe_contents = True
                path.unlink(missing_ok=True)
        else:
            unsafe_contents = True
        _require(
            not os.path.lexists(path) and not unsafe_contents,
            "Evaluator pycache prefix materialized bytecode or changed identity.",
        )


def build_evaluator_command(
    *,
    evaluator_script: Path,
    envelope_path: Path,
    manifest_path: Path,
    coordinate: ShardCoordinate,
    inputs: InputBundle,
    launch_nonce: str,
    gpu_lease_binding: Mapping[str, Any],
) -> list[str]:
    canonical = _canonical_evaluator(evaluator_script)
    python_runtime = _validated_launcher_python_runtime()
    validated_gpu_binding = _validate_gpu_lease_binding(gpu_lease_binding)
    routing_identity = cast(
        Mapping[str, Any], validated_gpu_binding["selected_device_routing_identity"]
    )
    command = [
        cast(str, python_runtime["executable"]),
        "-I",
        "-S",
        "-B",
        "-X",
        f"pycache_prefix={_isolated_evaluator_pycache_prefix(launch_nonce)}",
        "-c",
        EVALUATOR_FD_BOOTSTRAP,
        str(canonical),
        "--checkpoint",
        str(inputs.checkpoint_path.resolve()),
        "--training-summary",
        str(inputs.training_summary_path.resolve()),
        "--training-matrix-summary",
        str(inputs.training_matrix_summary_path.resolve()),
        "--calibration",
        str(inputs.calibration_path.resolve()),
        "--reuse-admission",
        str(inputs.reuse_admission_path.resolve()),
        "--preheldout-genesis",
        str(inputs.preheldout_genesis_path.resolve()),
        "--quality-start-activation",
        str(inputs.quality_start_activation_path.resolve()),
        "--manifest",
        str(manifest_path.resolve()),
        "--scale",
        coordinate.scale,
        "--training-seed",
        str(coordinate.training_seed),
        "--budget",
        coordinate.budget,
        "--family",
        coordinate.family,
        "--context",
        str(coordinate.context),
        "--replicate",
        str(coordinate.replicate),
        "--output",
        str(envelope_path),
        "--device",
        cast(str, validated_gpu_binding["device_argument"]),
        "--expected-device-identity-type",
        cast(str, routing_identity["identity_type"]),
        "--expected-device-identity",
        cast(str, routing_identity["identity"]),
        "--dtype",
        DTYPE,
    ]
    command.extend(("--launch-nonce", launch_nonce))
    return command


def _persistent_plan_coordinates(
    remaining: Sequence[ShardCoordinate],
    *,
    max_new_cells_remaining: int | None,
) -> tuple[ShardCoordinate, ...]:
    _require(bool(remaining), "Persistent session has no remaining coordinate.")
    if max_new_cells_remaining is not None:
        _require(
            type(max_new_cells_remaining) is int and max_new_cells_remaining > 0,
            "Persistent session stop limit is invalid.",
        )
    first = remaining[0]
    result: list[ShardCoordinate] = []
    for coordinate in remaining:
        if (coordinate.scale, coordinate.training_seed) != (
            first.scale,
            first.training_seed,
        ):
            break
        if max_new_cells_remaining is not None and len(result) >= max_new_cells_remaining:
            break
        result.append(coordinate)
    _require(bool(result), "Persistent session deterministic cohort prefix is empty.")
    return tuple(result)


def _persistent_plan_projection(plan: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "session_nonce": plan["session_nonce"],
        "launch_authority_nonce": plan["launch_authority_nonce"],
        "session_role": plan["session_role"],
        "payload_sha256": plan["payload_sha256"],
        "attestation_mac": cast(Mapping[str, Any], plan["attestation"])["mac"],
        "worker_index": plan["worker_index"],
        "worker_count": plan["worker_count"],
        "scale": plan["scale"],
        "training_seed": plan["training_seed"],
        "coordinate_count": plan["coordinate_count"],
        "coordinate_digest": plan["coordinate_digest"],
        "model_load_limit": plan["model_load_limit"],
        "child_full_historical_evidence_replay_count": plan[
            "child_full_historical_evidence_replay_count"
        ],
    }


def _persistent_execution_payload(
    *,
    plan: Mapping[str, Any],
    session_command: Sequence[str],
    work_order: Mapping[str, Any],
    work_result: Mapping[str, Any] | None,
    published_bundle_reingested_after_child_eof: bool,
) -> dict[str, Any]:
    return {
        "protocol": "sealed-hmac-jsonl-model-resident-v1",
        "plan": _persistent_plan_projection(plan),
        "session_command": list(session_command),
        "work_order": dict(work_order),
        "work_result": None if work_result is None else dict(work_result),
        "published_bundle_reingested_after_child_eof": (
            published_bundle_reingested_after_child_eof
        ),
    }


def _validate_persistent_execution_payload(
    value: Mapping[str, Any],
    *,
    coordinate: ShardCoordinate,
    envelope_path: Path,
    launch_nonce: str,
    trust_root: attestation.TrustRoot,
) -> dict[str, Any]:
    _require(
        set(value)
        == {
            "protocol",
            "plan",
            "session_command",
            "work_order",
            "work_result",
            "published_bundle_reingested_after_child_eof",
        }
        and value.get("protocol") == "sealed-hmac-jsonl-model-resident-v1"
        and isinstance(value.get("plan"), Mapping)
        and isinstance(value.get("session_command"), list)
        and isinstance(value.get("work_order"), Mapping)
        and isinstance(value.get("published_bundle_reingested_after_child_eof"), bool),
        "Persistent matrix-record execution schema drifted.",
    )
    plan = cast(Mapping[str, Any], value["plan"])
    session_command = cast(list[Any], value["session_command"])
    work = persistent_session.validate_attested_work_message(
        cast(Mapping[str, Any], value["work_order"]), trust_root=trust_root
    )
    _require(
        set(plan)
        == {
            "session_nonce",
            "launch_authority_nonce",
            "session_role",
            "payload_sha256",
            "attestation_mac",
            "worker_index",
            "worker_count",
            "scale",
            "training_seed",
            "coordinate_count",
            "coordinate_digest",
            "model_load_limit",
            "child_full_historical_evidence_replay_count",
        }
        and contract.is_sha256(plan.get("session_nonce"))
        and contract.is_sha256(plan.get("launch_authority_nonce"))
        and plan.get("session_role") == persistent_session.QUALITY_SESSION_ROLE
        and contract.is_sha256(plan.get("payload_sha256"))
        and contract.is_sha256(plan.get("attestation_mac"))
        and plan.get("model_load_limit") == 1
        and plan.get("child_full_historical_evidence_replay_count") == 0
        and plan.get("scale") == coordinate.scale
        and plan.get("training_seed") == coordinate.training_seed
        and all(isinstance(item, str) for item in session_command)
        and session_command.count("--persistent-session") == 1
        and session_command.count("--launch-nonce") == 1
        and session_command[session_command.index("--launch-nonce") + 1]
        == plan.get("session_nonce")
        and session_command.count("--scale") == 1
        and session_command[session_command.index("--scale") + 1] == plan.get("scale")
        and session_command.count("--training-seed") == 1
        and session_command[session_command.index("--training-seed") + 1]
        == str(plan.get("training_seed"))
        and work.get("session_nonce") == plan.get("session_nonce")
        and work.get("launch_authority_nonce") == plan.get("launch_authority_nonce")
        and work.get("plan_payload_sha256") == plan.get("payload_sha256")
        and work.get("coordinate") == coordinate.payload
        and work.get("launch_nonce") == launch_nonce
        and work.get("envelope_path") == str(envelope_path),
        "Persistent plan/work binding drifted from the matrix record.",
    )
    raw_result = value.get("work_result")
    reingested = cast(bool, value["published_bundle_reingested_after_child_eof"])
    if raw_result is None:
        _require(reingested, "Missing persistent child result lacks EOF reingestion disclosure.")
    else:
        _require(
            isinstance(raw_result, Mapping) and not reingested,
            "Persistent child result/reingestion boundary drifted.",
        )
        result = persistent_session.validate_attested_work_result(
            cast(Mapping[str, Any], raw_result), trust_root=trust_root
        )
        _require(
            result.get("session_nonce") == work.get("session_nonce")
            and result.get("launch_authority_nonce") == work.get("launch_authority_nonce")
            and result.get("plan_payload_sha256") == work.get("plan_payload_sha256")
            and result.get("work_payload_sha256") == work.get("payload_sha256")
            and result.get("coordinate") == coordinate.payload
            and result.get("launch_nonce") == launch_nonce,
            "Persistent child work-result binding drifted.",
        )
    return dict(value)


PERSISTENT_READY_RECEIPT_TIMEOUT_SECONDS = 900.0
PERSISTENT_CHILD_EXIT_TIMEOUT_SECONDS = 30.0
PERSISTENT_CHILD_KILL_TIMEOUT_SECONDS = 5.0
_ACTIVE_PERSISTENT_EVALUATORS: dict[int, PersistentEvaluatorProcess] = {}
_ACTIVE_PERSISTENT_PREPARATION_CLAIMS: dict[int, Any] = {}
_ACTIVE_PERSISTENT_PROJECTION_REFRESHERS: dict[
    int, Callable[[PersistentEvaluatorProcess | None], None]
] = {}
_ACTIVE_PERSISTENT_EVALUATORS_LOCK = threading.Lock()


def _persistent_lease_key(gpu_lease: GPULockLease) -> int:
    return id(gpu_lease)


def _register_active_persistent_evaluator(
    evaluator: PersistentEvaluatorProcess,
) -> None:
    key = _persistent_lease_key(evaluator.gpu_lease)
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        _require(
            key not in _ACTIVE_PERSISTENT_EVALUATORS,
            "GPU lease already owns an active persistent evaluator.",
        )
        _ACTIVE_PERSISTENT_EVALUATORS[key] = evaluator


def _unregister_active_persistent_evaluator(
    evaluator: PersistentEvaluatorProcess,
) -> None:
    key = _persistent_lease_key(evaluator.gpu_lease)
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        if _ACTIVE_PERSISTENT_EVALUATORS.get(key) is evaluator:
            del _ACTIVE_PERSISTENT_EVALUATORS[key]


def _register_persistent_preparation_claim(
    gpu_lease: GPULockLease, claim_manager: Any
) -> None:
    key = _persistent_lease_key(gpu_lease)
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        _require(
            key not in _ACTIVE_PERSISTENT_PREPARATION_CLAIMS,
            "GPU lease already owns a preparation-stage cell claim.",
        )
        _ACTIVE_PERSISTENT_PREPARATION_CLAIMS[key] = claim_manager


def _clear_persistent_preparation_claim(gpu_lease: GPULockLease) -> None:
    key = _persistent_lease_key(gpu_lease)
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        _ACTIVE_PERSISTENT_PREPARATION_CLAIMS.pop(key, None)


def _register_persistent_projection_refresher(
    gpu_lease: GPULockLease,
    refresher: Callable[[PersistentEvaluatorProcess | None], None],
) -> None:
    key = _persistent_lease_key(gpu_lease)
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        _require(
            key not in _ACTIVE_PERSISTENT_PROJECTION_REFRESHERS,
            "GPU lease already owns a persistent projection refresher.",
        )
        _ACTIVE_PERSISTENT_PROJECTION_REFRESHERS[key] = refresher


def _settle_active_persistent_evaluator_scope(
    gpu_lease: GPULockLease,
    exc_type: type[BaseException] | None,
    error: BaseException | None,
    traceback: Any,
) -> bool:
    del traceback
    key = _persistent_lease_key(gpu_lease)
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        claim_manager = _ACTIVE_PERSISTENT_PREPARATION_CLAIMS.pop(key, None)
        active = _ACTIVE_PERSISTENT_EVALUATORS.get(key)
        projection_refresher = _ACTIVE_PERSISTENT_PROJECTION_REFRESHERS.pop(
            key, None
        )
    cleanup_errors: list[tuple[str, BaseException]] = []
    if claim_manager is not None:
        try:
            claim_manager.__exit__(exc_type, error, getattr(error, "__traceback__", None))
        except BaseException as claim_error:
            cleanup_errors.append(("claim release", claim_error))
    reconciliation_succeeded = active is None
    if active is not None:
        if projection_refresher is None:
            cleanup_errors.append(
                (
                    "pre-terminal matrix reconciliation",
                    RuntimeError("Active persistent evaluator lacks its scope refresher."),
                )
            )
        else:
            try:
                projection_refresher(active)
                reconciliation_succeeded = True
            except BaseException as reconcile_error:
                cleanup_errors.append(
                    ("pre-terminal matrix reconciliation", reconcile_error)
                )
    if active is not None and not active.terminal_published:
        try:
            if not reconciliation_succeeded:
                active.terminate_without_terminal()
            else:
                graceful = exc_type is None or (
                    exc_type is not None
                    and issubclass(exc_type, InfrastructurePauseSignal)
                )
                if active.closed and active.verified_eof_reingested:
                    active.finalize_eof(published_bundle_reingested=True)
                elif graceful:
                    if not active.closed:
                        active.close()
                    elif not active.terminal_published:
                        active.finalize_eof(published_bundle_reingested=False)
                else:
                    active.abort_after_parent_commit_failure()
        except BaseException as session_error:
            cleanup_errors.append(("session terminal publication", session_error))
            if reconciliation_succeeded:
                try:
                    active.abort_after_parent_commit_failure()
                except BaseException as abort_error:
                    cleanup_errors.append(("session abort fallback", abort_error))
                    try:
                        active.terminate_without_terminal()
                    except BaseException as termination_error:
                        cleanup_errors.append(
                            ("terminal-free child termination", termination_error)
                        )
    if projection_refresher is not None:
        try:
            projection_refresher(None)
        except BaseException as projection_error:
            cleanup_errors.append(("matrix session-projection refresh", projection_error))
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        if active is not None and _ACTIVE_PERSISTENT_EVALUATORS.get(key) is active:
            del _ACTIVE_PERSISTENT_EVALUATORS[key]
    if cleanup_errors:
        if error is not None:
            for phase, cleanup_error in cleanup_errors:
                add_note = getattr(error, "add_note", None)
                if callable(add_note):
                    cast(Callable[[str], None], add_note)(
                        f"Persistent evaluator {phase} failure: {cleanup_error!r}"
                    )
        else:
            phase, cleanup_error = cleanup_errors[0]
            for secondary_phase, secondary_error in cleanup_errors[1:]:
                add_note = getattr(cleanup_error, "add_note", None)
                if callable(add_note):
                    cast(Callable[[str], None], add_note)(
                        f"Additional persistent evaluator {secondary_phase} failure: "
                        f"{secondary_error!r}"
                    )
            raise RuntimeError(
                f"Persistent evaluator {phase} failed during scope settlement."
            ) from cleanup_error
    return False


def _read_persistent_ready_line_bounded(
    process: subprocess.Popen[bytes],
) -> bytes:
    _require(process.stdout is not None, "Persistent evaluator stdout is unavailable.")
    messages: list[bytes] = []
    read_errors: list[BaseException] = []

    def read_ready_line() -> None:
        try:
            stdout = cast(Any, process.stdout)
            messages.append(
                stdout.readline(persistent_session.MAXIMUM_JSONL_MESSAGE_BYTES + 1)
            )
        except BaseException as read_error:
            read_errors.append(read_error)

    reader = threading.Thread(
        target=read_ready_line,
        name="persistent-evaluator-ready-receipt",
        daemon=True,
    )
    reader.start()
    reader.join(PERSISTENT_READY_RECEIPT_TIMEOUT_SECONDS)
    _require(
        not reader.is_alive(),
        "Persistent evaluator ready receipt timed out.",
    )
    if read_errors:
        raise read_errors[0]
    return messages[0] if messages else b""


def _close_persistent_process_streams(
    process: subprocess.Popen[bytes],
) -> None:
    for stream in (process.stdin, process.stdout, process.stderr):
        if stream is not None and not stream.closed:
            stream.close()


def _reap_launch_failure_child_bounded(
    process: subprocess.Popen[bytes],
) -> int:
    stdin = process.stdin
    if stdin is not None and not stdin.closed:
        stdin.close()
    try:
        return process.wait(timeout=PERSISTENT_CHILD_EXIT_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        if process.poll() is None:
            process.terminate()
    try:
        return process.wait(timeout=PERSISTENT_CHILD_KILL_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        if process.poll() is None:
            process.kill()
    return process.wait(timeout=PERSISTENT_CHILD_KILL_TIMEOUT_SECONDS)


class PersistentEvaluatorProcess:
    def __init__(
        self,
        *,
        process: subprocess.Popen[bytes],
        command: Sequence[str],
        plan: Mapping[str, Any],
        ready_receipt: Mapping[str, Any],
        canonical: Path,
        snapshot: CanonicalEvaluatorSnapshot,
        canonical_descriptor: int,
        pycache_manager: Any,
        prerequisites: FrozenPrerequisites,
        gpu_lease: GPULockLease,
        device_guard_lease: GPULockLease,
        gpu_lease_binding: Mapping[str, Any],
        output_root: Path,
    ) -> None:
        self.process = process
        self.command = list(command)
        self.plan = dict(plan)
        self.ready_receipt = dict(ready_receipt)
        self.canonical = canonical
        self.snapshot = snapshot
        self.canonical_descriptor = canonical_descriptor
        self.pycache_manager = pycache_manager
        self.prerequisites = prerequisites
        self.gpu_lease = gpu_lease
        self.device_guard_lease = device_guard_lease
        self.gpu_lease_binding = dict(gpu_lease_binding)
        self.output_root = output_root
        self.work_orders: list[dict[str, Any]] = []
        self.results: list[dict[str, Any]] = []
        self.committed_count = 0
        self.reingestion_count = 0
        self.eof_work_order: dict[str, Any] | None = None
        self.verified_eof_reingested = False
        self.closed = False
        self.terminal_published = False
        self.eof_returncode: int | None = None

    @property
    def cohort(self) -> tuple[str, int]:
        return cast(str, self.plan["scale"]), cast(int, self.plan["training_seed"])

    def _assert_authority(self) -> None:
        self.gpu_lease.assert_held()
        self.device_guard_lease.assert_held()
        _assert_open_evaluator(self.canonical_descriptor, expected=self.snapshot)
        admission.assert_quality_context_unchanged(self.prerequisites.context)

    def _assert_terminal_authority(self) -> None:
        self._assert_authority()
        _assert_terminal_launch_authority(
            self.plan,
            self.command,
            canonical=self.canonical,
            canonical_descriptor=self.canonical_descriptor,
            evaluator_snapshot=self.snapshot,
            prerequisites=self.prerequisites,
            gpu_binding=self.gpu_lease_binding,
            gpu_lease=self.gpu_lease,
            device_guard_lease=self.device_guard_lease,
            output_root=self.output_root,
        )

    def _read_message(self) -> dict[str, Any] | None:
        _require(self.process.stdout is not None, "Persistent evaluator stdout is unavailable.")
        stdout = cast(Any, self.process.stdout)
        raw = stdout.readline(persistent_session.MAXIMUM_JSONL_MESSAGE_BYTES + 1)
        return None if not raw else persistent_session.decode_jsonl_message(raw)

    def execute(self, work_order: Mapping[str, Any]) -> dict[str, Any] | None:
        _require(not self.closed, "Persistent evaluator session is closed.")
        self._assert_authority()
        work = persistent_session.validate_work_order(
            work_order,
            plan=self.plan,
            expected_sequence_index=len(self.work_orders),
            trust_root=self.prerequisites.trust_root,
        )
        _require(self.process.stdin is not None, "Persistent evaluator stdin is unavailable.")
        stdin = cast(Any, self.process.stdin)
        try:
            stdin.write(persistent_session.encode_jsonl_message(work))
            stdin.flush()
        except (BrokenPipeError, OSError):
            self.eof_work_order = work
            self.finish_eof()
            return None
        observed = self._read_message()
        if observed is None:
            self.eof_work_order = work
            self.finish_eof()
            return None
        result: dict[str, Any] = persistent_session.validate_work_result(
            observed,
            plan=self.plan,
            work_order=work,
            trust_root=self.prerequisites.trust_root,
        )
        self.work_orders.append(work)
        self.results.append(result)
        self._assert_authority()
        return result

    def mark_committed(
        self,
        *,
        work_order: Mapping[str, Any],
        work_result: Mapping[str, Any],
    ) -> None:
        _require(
            self.committed_count < len(self.work_orders) == len(self.results)
            and self.work_orders[self.committed_count] == dict(work_order)
            and self.results[self.committed_count] == dict(work_result),
            "Persistent authoritative commit did not match the next observed child result.",
        )
        self.committed_count += 1

    def _publish_terminal(
        self,
        *,
        status: str,
        final_receipt: Mapping[str, Any] | None,
        returncode: int | None,
    ) -> None:
        if self.terminal_published:
            return
        self._assert_terminal_authority()
        persistent_session.publish_session_terminal(
            self.output_root,
            self.plan,
            status=status,
            ready_receipt=self.ready_receipt,
            final_receipt=final_receipt,
            work_orders=self.work_orders[: self.committed_count],
            results=self.results[: self.committed_count],
            published_bundle_reingestion_count=self.reingestion_count,
            actual_session_argv=self.command,
            child_process_returncode=returncode,
            trust_root=self.prerequisites.trust_root,
        )
        self.terminal_published = True
        _unregister_active_persistent_evaluator(self)
        self._cleanup()

    def _cleanup(self) -> None:
        _close_persistent_process_streams(self.process)
        if self.canonical_descriptor >= 0:
            os.close(self.canonical_descriptor)
            self.canonical_descriptor = -1
        if self.pycache_manager is not None:
            manager = self.pycache_manager
            self.pycache_manager = None
            manager.__exit__(None, None, None)

    def _wait_bounded(self, *, kill_immediately: bool = False) -> int:
        if kill_immediately and self.process.poll() is None:
            self.process.kill()
        try:
            return self.process.wait(
                timeout=(
                    PERSISTENT_CHILD_KILL_TIMEOUT_SECONDS
                    if kill_immediately
                    else PERSISTENT_CHILD_EXIT_TIMEOUT_SECONDS
                )
            )
        except subprocess.TimeoutExpired:
            if self.process.poll() is None:
                self.process.terminate()
            try:
                return self.process.wait(
                    timeout=PERSISTENT_CHILD_KILL_TIMEOUT_SECONDS
                )
            except subprocess.TimeoutExpired:
                if self.process.poll() is None:
                    self.process.kill()
                return self.process.wait(
                    timeout=PERSISTENT_CHILD_KILL_TIMEOUT_SECONDS
                )

    def finish_eof(self) -> None:
        if self.closed:
            return
        stdin = cast(Any, self.process.stdin)
        if stdin is not None and not stdin.closed:
            stdin.close()
        self.eof_returncode = self._wait_bounded()
        self.closed = True
        _close_persistent_process_streams(self.process)

    def finalize_eof(self, *, published_bundle_reingested: bool) -> None:
        _require(
            self.closed and not self.terminal_published and self.reingestion_count == 0,
            "Persistent child-EOF terminal state may be finalized exactly once.",
        )
        self.reingestion_count = int(published_bundle_reingested)
        self._publish_terminal(
            status="child_eof",
            final_receipt=None,
            returncode=self.eof_returncode,
        )

    def abort_after_parent_commit_failure(self) -> None:
        if self.terminal_published:
            return
        try:
            if not self.closed or self.eof_returncode is None:
                self.eof_returncode = self._wait_bounded(kill_immediately=True)
                self.closed = True
            _require(
                type(self.eof_returncode) is int,
                "Persistent parent-commit failure lacks a child return code.",
            )
            self._publish_terminal(
                status="parent_commit_failure",
                final_receipt=None,
                returncode=self.eof_returncode,
            )
        finally:
            self._cleanup()

    def terminate_without_terminal(self) -> None:
        try:
            if not self.closed or self.eof_returncode is None:
                self.eof_returncode = self._wait_bounded(kill_immediately=True)
                self.closed = True
        finally:
            self._cleanup()

    def close(self) -> dict[str, Any] | None:
        if self.closed:
            return None
        self._assert_authority()
        _require(
            self.committed_count == len(self.work_orders) == len(self.results),
            "Persistent graceful close refuses an uncommitted observed child result.",
        )
        _require(self.process.stdin is not None, "Persistent evaluator stdin is unavailable.")
        stdin = cast(Any, self.process.stdin)
        stdin.close()
        observed_messages: list[dict[str, Any] | None] = []
        read_errors: list[BaseException] = []

        def read_final_message() -> None:
            try:
                observed_messages.append(self._read_message())
                _require(
                    self._read_message() is None,
                    "Persistent evaluator emitted trailing output after its final receipt.",
                )
            except BaseException as read_error:
                read_errors.append(read_error)

        reader = threading.Thread(
            target=read_final_message,
            name="persistent-evaluator-final-receipt",
            daemon=True,
        )
        reader.start()
        returncode = self._wait_bounded()
        self.eof_returncode = returncode
        self.closed = True
        reader.join(PERSISTENT_CHILD_KILL_TIMEOUT_SECONDS)
        try:
            _require(
                not reader.is_alive(),
                "Persistent evaluator final receipt reader did not reach EOF.",
            )
            if read_errors:
                raise read_errors[0]
            observed = observed_messages[0] if observed_messages else None
            if observed is None or returncode != 0:
                self._publish_terminal(
                    status="child_eof", final_receipt=None, returncode=returncode
                )
                return None
            receipt: dict[str, Any] = persistent_session.validate_session_receipt(
                observed,
                plan=self.plan,
                work_orders=self.work_orders,
                results=self.results,
                trust_root=self.prerequisites.trust_root,
            )
            self._publish_terminal(
                status=cast(str, receipt["status"]),
                final_receipt=receipt,
                returncode=returncode,
            )
            return receipt
        finally:
            _close_persistent_process_streams(self.process)


def _start_persistent_evaluator(
    *,
    canonical: Path,
    expected: CanonicalEvaluatorSnapshot,
    manifest_path: Path,
    inputs: InputBundle,
    first_coordinate: ShardCoordinate,
    plan_coordinates: Sequence[ShardCoordinate],
    max_new_cells_stop_limit: int | None,
    session_role: str,
    launch_authority_nonce: str,
    worker_index: int,
    worker_count: int,
    evaluator_binding: Mapping[str, Any],
    prerequisites: FrozenPrerequisites,
    gpu_lease_binding: Mapping[str, Any],
    gpu_lease: GPULockLease,
    device_guard_lease: GPULockLease,
    output_root: Path,
) -> PersistentEvaluatorProcess:
    _require(
        bool(plan_coordinates) and plan_coordinates[0] == first_coordinate,
        "Persistent plan does not start at the claimed coordinate.",
    )
    session_nonce = secrets.token_hex(32)
    assigned_payloads = persistent_session.assigned_coordinates(
        worker_index=worker_index, worker_count=worker_count
    )
    first_payload = first_coordinate.payload
    first_assignment_index = assigned_payloads.index(first_payload)
    plan = persistent_session.build_session_plan(
        [coordinate.payload for coordinate in plan_coordinates],
        session_nonce=session_nonce,
        launch_authority_nonce=launch_authority_nonce,
        worker_index=worker_index,
        worker_count=worker_count,
        assignment_completed_prefix=assigned_payloads[:first_assignment_index],
        max_new_cells_stop_limit=max_new_cells_stop_limit,
        input_binding_digest=cast(str, inputs.binding["input_binding_digest"]),
        canonical_evaluator_digest=contract.json_digest(evaluator_binding),
        gpu_lease_binding_digest=contract.json_digest(gpu_lease_binding),
        prerequisites_binding_digest=contract.json_digest(prerequisites.public_binding),
        output_root=_absolute(output_root),
        trust_root=prerequisites.trust_root,
        session_role=session_role,
    )
    command = build_evaluator_command(
        evaluator_script=canonical,
        envelope_path=shard_envelope_path(output_root, first_coordinate),
        manifest_path=manifest_path,
        coordinate=first_coordinate,
        inputs=inputs,
        launch_nonce=session_nonce,
        gpu_lease_binding=gpu_lease_binding,
    )
    command.append("--persistent-session")
    persistent_session.publish_session_launch(
        _absolute(output_root),
        plan,
        actual_session_argv=command,
        trust_root=prerequisites.trust_root,
    )
    descriptor = -1
    snapshot = expected
    sealed: int | None = None
    inventory_descriptor: int | None = None
    key_descriptor: int | None = None
    plan_descriptor: int | None = None
    pycache_manager: Any | None = None
    process: subprocess.Popen[bytes] | None = None
    try:
        descriptor, snapshot = _open_evaluator(canonical, expected=expected)
        sealed = _sealed_evaluator_copy(descriptor, expected=snapshot)
        inventory_descriptor = _sealed_import_inventory_fd(prerequisites.context)
        key_descriptor = attestation.create_sealed_key_fd(prerequisites.trust_root)
        plan_descriptor = persistent_session.create_sealed_plan_fd(plan)
        environment = os.environ.copy()
        for name in (attestation.KEY_PATH_ENV, IMPORT_INVENTORY_FD_ENV, PERSISTENT_PLAN_FD_ENV):
            environment.pop(name, None)
        environment[EVALUATOR_FD_ENV] = str(sealed)
        environment[IMPORT_INVENTORY_FD_ENV] = str(inventory_descriptor)
        environment[PERSISTENT_PLAN_FD_ENV] = str(plan_descriptor)
        environment[attestation.KEY_FD_ENV] = str(key_descriptor)
        pycache_manager = _fresh_evaluator_pycache(command)
        pycache_manager.__enter__()
        inherited_gpu = tuple(sorted({gpu_lease.fileno(), device_guard_lease.fileno()}))
        process = subprocess.Popen(
            command,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            pass_fds=(
                sealed,
                inventory_descriptor,
                key_descriptor,
                plan_descriptor,
                *inherited_gpu,
            ),
            env=environment,
        )
        raw_ready = _read_persistent_ready_line_bounded(process)
        _require(bool(raw_ready), "Persistent evaluator exited before its ready receipt.")
        ready = persistent_session.validate_session_receipt(
            persistent_session.decode_jsonl_message(raw_ready),
            plan=plan,
            work_orders=(),
            results=(),
            trust_root=prerequisites.trust_root,
        )
        _require(
            ready["model_load_count"] == 1
            and ready["child_full_historical_evidence_replay_count"] == 0,
            "Persistent evaluator ready counters drifted.",
        )
        gpu_lease.assert_held()
        device_guard_lease.assert_held()
        _assert_open_evaluator(descriptor, expected=snapshot)
        active = PersistentEvaluatorProcess(
            process=process,
            command=command,
            plan=plan,
            ready_receipt=ready,
            canonical=canonical,
            snapshot=snapshot,
            canonical_descriptor=descriptor,
            pycache_manager=pycache_manager,
            prerequisites=prerequisites,
            gpu_lease=gpu_lease,
            device_guard_lease=device_guard_lease,
            gpu_lease_binding=gpu_lease_binding,
            output_root=_absolute(output_root),
        )
        _register_active_persistent_evaluator(active)
        process = None
        pycache_manager = None
        descriptor = -1
        return active
    except BaseException as launch_error:
        returncode: int | None
        if process is not None:
            try:
                returncode = _reap_launch_failure_child_bounded(process)
            except BaseException as wait_error:
                returncode = process.poll()
                add_note = getattr(launch_error, "add_note", None)
                if callable(add_note):
                    cast(Callable[[str], None], add_note)(
                        "Persistent evaluator launch-failure child reap failed: "
                        f"{wait_error!r}"
                    )
            finally:
                _close_persistent_process_streams(process)
        else:
            returncode = None
        terminal_descriptor = -1
        try:
            _require(
                type(returncode) is int,
                "Persistent launch-failure child was not reaped.",
            )
            terminal_descriptor, terminal_snapshot = _open_evaluator(
                canonical, expected=expected
            )
            _require(
                terminal_snapshot == expected,
                "Persistent launch-failure evaluator snapshot drifted.",
            )
            _assert_terminal_launch_authority(
                plan,
                command,
                canonical=canonical,
                canonical_descriptor=terminal_descriptor,
                evaluator_snapshot=expected,
                prerequisites=prerequisites,
                gpu_binding=gpu_lease_binding,
                gpu_lease=gpu_lease,
                device_guard_lease=device_guard_lease,
                output_root=_absolute(output_root),
            )
            persistent_session.publish_session_terminal(
                _absolute(output_root),
                plan,
                status="launch_failure",
                ready_receipt=None,
                final_receipt=None,
                work_orders=(),
                results=(),
                published_bundle_reingestion_count=0,
                actual_session_argv=command,
                child_process_returncode=returncode,
                trust_root=prerequisites.trust_root,
            )
        except BaseException as terminal_error:
            add_note = getattr(launch_error, "add_note", None)
            if callable(add_note):
                cast(Callable[[str], None], add_note)(
                    "Persistent evaluator launch-failure terminal was not published: "
                    f"{terminal_error!r}"
                )
        finally:
            if terminal_descriptor >= 0:
                os.close(terminal_descriptor)
            if pycache_manager is not None:
                try:
                    pycache_manager.__exit__(None, None, None)
                except BaseException as pycache_error:
                    add_note = getattr(launch_error, "add_note", None)
                    if callable(add_note):
                        cast(Callable[[str], None], add_note)(
                            "Persistent evaluator launch-failure pycache cleanup failed: "
                            f"{pycache_error!r}"
                        )
        raise
    finally:
        for inherited in (plan_descriptor, key_descriptor, inventory_descriptor, sealed):
            if inherited is not None:
                os.close(inherited)
        if descriptor >= 0:
            os.close(descriptor)


def _assert_ready_only_preflight_output_boundary(layout: MatrixLayout) -> None:
    """The readiness probe may create ledgers only in the sibling ledger root."""

    _require(
        not os.path.lexists(layout.matrix_summary),
        "Ready-only preflight must precede the initial matrix ledger.",
    )
    if not os.path.lexists(layout.output_root):
        return
    metadata = os.stat(layout.output_root, follow_symlinks=False)
    _require(
        stat.S_ISDIR(metadata.st_mode)
        and metadata.st_uid == os.getuid()
        and stat.S_IMODE(metadata.st_mode) == 0o700,
        "Ready-only preflight output root is unsafe.",
    )
    interrupted_prefix = f".{layout.matrix_summary.name}."
    for member in tuple(layout.output_root.iterdir()):
        member_metadata = os.stat(member, follow_symlinks=False)
        _require(
            member.name.startswith(interrupted_prefix)
            and member.name.endswith(".tmp")
            and stat.S_ISREG(member_metadata.st_mode)
            and member_metadata.st_uid == os.getuid()
            and member_metadata.st_nlink == 1
            and stat.S_IMODE(member_metadata.st_mode) == 0o600,
            "Ready-only preflight created a claim, envelope, or sidecar.",
        )


def _ensure_ready_only_preflight(
    *,
    start_mode: str,
    layout: MatrixLayout,
    manifest_path: Path,
    canonical: Path,
    evaluator_snapshot: CanonicalEvaluatorSnapshot,
    evaluator_binding: Mapping[str, Any],
    prerequisites: FrozenPrerequisites,
    activation_lease: admission.QualityStartActivationLeaseV1_3_5,
    launch_authority_nonce: str,
    gpu_lease_binding: Mapping[str, Any],
    gpu_lease: GPULockLease,
    device_guard_lease: GPULockLease,
) -> dict[str, Any]:
    """Adopt or execute one post-activation, pre-claim zero-work model probe."""

    del start_mode
    activation_lease.assert_held()
    gpu_lease.assert_held()
    device_guard_lease.assert_held()
    projection = persistent_session.load_session_ledger_projection(
        _absolute(layout.output_root), trust_root=prerequisites.trust_root
    )
    if os.path.lexists(layout.matrix_summary):
        binding = persistent_session.ready_only_preflight_binding(projection)
        payload = _load_json_nofollow(
            layout.matrix_summary, label="ready-only preflight matrix ledger"
        )
        _verify_attested_payload(payload, trust_root=prerequisites.trust_root)
        _require(
            binding is not None
            and isinstance(payload.get("ready_only_preflight"), Mapping)
            and payload.get("ready_only_preflight") == binding,
            "Existing matrix lacks its exact authenticated ready-only preflight.",
        )
        checked_binding = cast(dict[str, Any], binding)
        with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
            _require(
                _persistent_lease_key(gpu_lease)
                not in _ACTIVE_PERSISTENT_EVALUATORS,
                "Adopted ready-only preflight has a live evaluator registry entry.",
            )
        return _validate_ready_only_preflight_snapshot(
            checked_binding,
            session_projection=projection,
            output_root=layout.output_root,
            prerequisites=prerequisites,
            evaluator_binding=evaluator_binding,
            gpu_lease_binding=gpu_lease_binding,
        )

    _assert_ready_only_preflight_output_boundary(layout)
    sessions = cast(list[Mapping[str, Any]], projection["sessions"])
    _require(
        all(
            row["session_role"]
            == persistent_session.READY_ONLY_PREFLIGHT_SESSION_ROLE
            for row in sessions
        ),
        "A quality session exists before the initial matrix ledger.",
    )
    if any(row["status"] == "launch_only" for row in sessions):
        def terminal_authority_check(
            plan: Mapping[str, Any], session_argv: Sequence[str]
        ) -> None:
            descriptor, observed = _open_evaluator(
                canonical, expected=evaluator_snapshot
            )
            try:
                _require(
                    observed == evaluator_snapshot,
                    "Ready-only recovery evaluator snapshot drifted.",
                )
                _assert_terminal_launch_authority(
                    plan,
                    session_argv,
                    canonical=canonical,
                    canonical_descriptor=descriptor,
                    evaluator_snapshot=evaluator_snapshot,
                    prerequisites=prerequisites,
                    gpu_binding=gpu_lease_binding,
                    gpu_lease=gpu_lease,
                    device_guard_lease=device_guard_lease,
                    output_root=_absolute(layout.output_root),
                )
            finally:
                os.close(descriptor)

        projection = persistent_session.reconcile_committed_launch_only_sessions(
            _absolute(layout.output_root),
            (),
            worker_index=0,
            gpu_lease_binding_digest=contract.json_digest(gpu_lease_binding),
            terminal_authority_check=terminal_authority_check,
            trust_root=prerequisites.trust_root,
        )
    binding = persistent_session.ready_only_preflight_binding(projection)
    if binding is None:
        first = _mixed_device_coordinates(contract.V1_3_5_MIXED_DEVICE_SITE)[0]
        inputs = prerequisites.bundles[
            (first.scale, first.training_seed, first.budget)
        ]
        evaluator = _start_persistent_evaluator(
            canonical=canonical,
            expected=evaluator_snapshot,
            manifest_path=manifest_path,
            inputs=inputs,
            first_coordinate=first,
            plan_coordinates=(first,),
            max_new_cells_stop_limit=1,
            session_role=persistent_session.READY_ONLY_PREFLIGHT_SESSION_ROLE,
            launch_authority_nonce=launch_authority_nonce,
            worker_index=0,
            worker_count=1,
            evaluator_binding=evaluator_binding,
            prerequisites=prerequisites,
            gpu_lease_binding=gpu_lease_binding,
            gpu_lease=gpu_lease,
            device_guard_lease=device_guard_lease,
            output_root=layout.output_root,
        )
        try:
            final_receipt = evaluator.close()
        except BaseException as preflight_error:
            if not evaluator.terminal_published:
                try:
                    evaluator.abort_after_parent_commit_failure()
                except BaseException as terminal_error:
                    add_note = getattr(preflight_error, "add_note", None)
                    if callable(add_note):
                        cast(Callable[[str], None], add_note)(
                            "Ready-only preflight failure terminal publication failed: "
                            f"{terminal_error!r}"
                        )
            raise
        _require(
            final_receipt is not None
            and final_receipt == evaluator.ready_receipt
            and evaluator.closed
            and evaluator.terminal_published
            and evaluator.eof_returncode == 0
            and evaluator.committed_count == 0
            and evaluator.work_orders == []
            and evaluator.results == []
            and evaluator.reingestion_count == 0
            and evaluator.canonical_descriptor == -1
            and evaluator.pycache_manager is None
            and all(
                stream is None or stream.closed
                for stream in (
                    evaluator.process.stdin,
                    evaluator.process.stdout,
                    evaluator.process.stderr,
                )
            ),
            "Ready-only preflight did not close as one clean zero-work session.",
        )
        with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
            _require(
                _persistent_lease_key(gpu_lease)
                not in _ACTIVE_PERSISTENT_EVALUATORS,
                "Ready-only preflight survived in the active evaluator registry.",
            )
        projection = persistent_session.load_session_ledger_projection(
            _absolute(layout.output_root), trust_root=prerequisites.trust_root
        )
        binding = persistent_session.ready_only_preflight_binding(projection)
    _require(binding is not None, "Ready-only preflight did not produce a durable proof.")
    checked_binding = cast(dict[str, Any], binding)
    with _ACTIVE_PERSISTENT_EVALUATORS_LOCK:
        _require(
            _persistent_lease_key(gpu_lease)
            not in _ACTIVE_PERSISTENT_EVALUATORS,
            "Ready-only preflight survived in the active evaluator registry.",
        )
    _assert_ready_only_preflight_output_boundary(layout)
    activation_lease.assert_held()
    gpu_lease.assert_held()
    device_guard_lease.assert_held()
    return _validate_ready_only_preflight_snapshot(
        checked_binding,
        session_projection=projection,
        output_root=layout.output_root,
        prerequisites=prerequisites,
        evaluator_binding=evaluator_binding,
        gpu_lease_binding=gpu_lease_binding,
    )

def _evaluator_module() -> Any:
    return importlib.import_module("evaluate_p2_direct_controller_shard_v1_3")


def _envelope_sidecars(payload: Mapping[str, Any]) -> Mapping[str, Any]:
    sidecars = payload.get("sidecars")
    if not isinstance(sidecars, Mapping):
        sidecars = payload.get("bundle_members")
    if not isinstance(sidecars, Mapping):
        raise ValueError("Evaluator sidecar inventory is missing.")
    _require(set(sidecars) == set(BUNDLE_KINDS), "Evaluator sidecar inventory drifted.")
    return sidecars


def _sidecar_relative_path(binding: Mapping[str, Any]) -> str:
    value = binding.get("relative_path")
    if not isinstance(value, str) or value != Path(value).name:
        raise ValueError("Unsafe sidecar path binding.")
    return value


def _validate_bundle_paths(
    envelope_path: Path,
    payload: Mapping[str, Any],
    *,
    coordinate: ShardCoordinate,
) -> dict[str, dict[str, Any]]:
    module = _evaluator_module()
    helper = getattr(module, "canonical_bundle_paths", None)
    _require(callable(helper), "Evaluator canonical-bundle helper is unavailable.")
    expected_paths = cast(Callable[[Path], Any], helper)(envelope_path)
    _require(
        isinstance(expected_paths, Mapping) and set(expected_paths) == {"envelope", *BUNDLE_KINDS},
        "Evaluator canonical-bundle path inventory drifted.",
    )
    result: dict[str, dict[str, Any]] = {}
    for kind, raw in _envelope_sidecars(payload).items():
        _require(isinstance(raw, Mapping), f"Evaluator {kind} sidecar binding is invalid.")
        binding = dict(cast(Mapping[str, Any], raw))
        relative = _sidecar_relative_path(binding)
        path = cast(Path, expected_paths[kind])
        _require(relative == path.name, f"Evaluator {kind} sidecar name drifted.")
        observed = _file_binding(path)
        _require(
            binding.get("compressed_sha256") == observed["sha256"]
            and binding.get("compressed_bytes") == observed["bytes"],
            f"Evaluator {kind} sidecar bytes drifted.",
        )
        result[kind] = {**binding, "path": str(path)}
    return result


def load_and_validate_shard_bundle(
    envelope_path: Path,
    *,
    coordinate: ShardCoordinate,
    inputs: InputBundle,
    launch_nonce: str,
    trust_root: attestation.TrustRoot,
    gpu_lease_binding: Mapping[str, Any],
    execution_environment_projection: Mapping[str, Any],
) -> dict[str, Any]:
    module = _evaluator_module()
    loader = getattr(module, "load_validated_direct_controller_shard", None)
    _require(callable(loader), "Direct evaluator safe shard loader is unavailable.")
    payload = cast(Callable[..., Any], loader)(
        envelope_path, verify_bindings=True, trust_root=trust_root
    )
    _require(isinstance(payload, dict), "Direct evaluator loader returned no envelope.")
    expected_gpu = _validate_gpu_lease_binding(gpu_lease_binding)
    environment = payload.get("environment")
    selected_class = cast(Mapping[str, Any], expected_gpu["selected_device_class"])
    _require(
        isinstance(environment, Mapping)
        and environment.get("device_argument") == expected_gpu["device_argument"]
        and environment.get("device_index") == expected_gpu["selected_device_logical_index"]
        and environment.get("selected_device_routing_identity")
        == expected_gpu["selected_device_routing_identity"]
        and environment.get("cuda_device_name") == selected_class["name"]
        and environment.get("cuda_capability") == selected_class["compute_capability"]
        and environment.get("cuda_total_memory_bytes") == selected_class["total_memory_bytes"]
        and environment.get("python") == execution_environment_projection.get("python_version")
        and environment.get("torch") == execution_environment_projection.get("torch_version")
        and environment.get("torch_cuda_version")
        == execution_environment_projection.get("cuda_runtime_version"),
        "Evaluator envelope runtime environment differs from its guarded worker device.",
    )
    _require(
        payload.get("coordinate") == coordinate.evaluator_payload,
        "Evaluator shard coordinate drifted.",
    )
    _require(payload.get("launch_nonce") == launch_nonce, "Evaluator launch nonce drifted.")
    _require(
        payload.get("terminal_decision") in {"INTEGRITY-PASS", "INTEGRITY-FAIL"},
        "Evaluator terminal integrity decision is invalid.",
    )
    workload = payload.get("workload_contract")
    arm_contract = payload.get("arm_contract")
    _require(isinstance(workload, Mapping), "Evaluator workload contract is missing.")
    _require(isinstance(arm_contract, Mapping), "Evaluator arm contract is missing.")
    _require(
        cast(Mapping[str, Any], workload).get("examples") == EXAMPLES_PER_SHARD,
        "Shard size drifted.",
    )
    _require(
        tuple(cast(Mapping[str, Any], arm_contract).get("all_arms", ())) == ARM_NAMES,
        "Evaluator arm inventory drifted.",
    )
    _require(payload.get("inputs") == dict(inputs.binding), "Evaluator input binding drifted.")
    sidecars = _validate_bundle_paths(envelope_path, payload, coordinate=coordinate)
    return {**payload, "_validated_sidecars": sidecars}


def _expected_exit_code(decision: str) -> int:
    _require(
        decision in {"INTEGRITY-PASS", "INTEGRITY-FAIL"},
        "Unknown evaluator integrity decision.",
    )
    return 0 if decision == "INTEGRITY-PASS" else 2


def _run_record(
    payload: Mapping[str, Any],
    *,
    coordinate: ShardCoordinate,
    envelope_path: Path,
    inputs: InputBundle,
    launch_nonce: str,
    command: Sequence[str],
    persistent_execution: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    sidecars = payload.get("_validated_sidecars")
    _require(isinstance(sidecars, Mapping), "Validated evaluator sidecars are missing.")
    envelope_binding = _file_binding(envelope_path, payload=payload)
    decision = cast(str, payload["terminal_decision"])
    storage = payload.get("storage", payload.get("storage_metrics", {}))
    _require(isinstance(storage, Mapping), "Evaluator storage metrics are invalid.")
    return {
        **coordinate.payload,
        "coordinate_key": coordinate.key,
        "launch_nonce": launch_nonce,
        "status": "terminal",
        "integrity_decision": decision,
        "logical_shard_integrity_exit_code": _expected_exit_code(decision),
        "logical_per_shard_replay_command": list(command),
        "persistent_session_execution": (
            None if persistent_execution is None else dict(persistent_execution)
        ),
        "inputs": dict(inputs.binding),
        "artifact_bundle": {
            "envelope": envelope_binding,
            "sidecars": dict(cast(Mapping[str, Any], sidecars)),
            "storage": dict(cast(Mapping[str, Any], storage)),
        },
    }


def _storage_observations(records: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    observations: list[dict[str, Any]] = []
    for record in records:
        artifact = record.get("artifact_bundle")
        _require(isinstance(artifact, Mapping), "Matrix artifact bundle binding is invalid.")
        artifact_map = cast(Mapping[str, Any], artifact)
        envelope = artifact_map.get("envelope")
        sidecars = artifact_map.get("sidecars")
        storage = artifact_map.get("storage")
        _require(isinstance(envelope, Mapping), "Matrix envelope binding is invalid.")
        _require(isinstance(sidecars, Mapping), "Matrix sidecar binding is invalid.")
        _require(isinstance(storage, Mapping), "Matrix evaluator storage evidence is invalid.")
        sidecars_map = cast(Mapping[str, Any], sidecars)
        storage_map = cast(Mapping[str, Any], storage)
        _require(set(sidecars_map) == set(BUNDLE_KINDS), "Matrix sidecar inventory drifted.")

        def sidecar_int(kind: str, field: str, inventory: Mapping[str, Any] = sidecars_map) -> int:
            binding = inventory.get(kind)
            _require(isinstance(binding, Mapping), f"Matrix {kind} sidecar binding is invalid.")
            value = cast(Mapping[str, Any], binding).get(field)
            _require(
                type(value) is int and value >= 0,
                f"Matrix {kind} sidecar {field} is invalid.",
            )
            return cast(int, value)

        sidecars_compressed = sum(sidecar_int(kind, "compressed_bytes") for kind in BUNDLE_KINDS)
        sidecars_uncompressed = sum(
            sidecar_int(kind, "uncompressed_bytes") for kind in BUNDLE_KINDS
        )
        token_compressed = sidecar_int("tokens", "compressed_bytes")
        token_uncompressed = sidecar_int("tokens", "uncompressed_bytes")
        token_binding = cast(Mapping[str, Any], sidecars_map["tokens"])
        observed_rows = token_binding.get("row_count")
        envelope_bytes = cast(Mapping[str, Any], envelope).get("bytes")
        _require(
            type(observed_rows) is int and observed_rows >= 0,
            "Matrix token sidecar row count is invalid.",
        )
        _require(
            type(envelope_bytes) is int and envelope_bytes >= 1,
            "Matrix envelope byte count is invalid.",
        )
        _require(
            storage_map.get("actual_sidecars_compressed_bytes") == sidecars_compressed
            and storage_map.get("actual_sidecars_uncompressed_bytes") == sidecars_uncompressed
            and storage_map.get("actual_token_sidecar_compressed_bytes") == token_compressed
            and storage_map.get("actual_token_sidecar_uncompressed_bytes") == token_uncompressed
            and storage_map.get("observed_token_rows") == observed_rows,
            "Matrix evaluator storage evidence drifted from its sidecars.",
        )
        if observed_rows:
            _require(
                storage_map.get("token_rate_compressed_numerator_bytes") == token_compressed
                and storage_map.get("token_rate_uncompressed_numerator_bytes") == token_uncompressed
                and storage_map.get("token_rate_denominator_rows") == observed_rows,
                "Matrix evaluator token-rate evidence drifted.",
            )
            rate_compressed_numerator: int | None = token_compressed
            rate_uncompressed_numerator: int | None = token_uncompressed
            rate_denominator: int | None = cast(int, observed_rows)
        else:
            _require(
                storage_map.get("token_rate_compressed_numerator_bytes") is None
                and storage_map.get("token_rate_uncompressed_numerator_bytes") is None
                and storage_map.get("token_rate_denominator_rows") is None,
                "Zero-token evaluator evidence fabricated a token rate.",
            )
            rate_compressed_numerator = None
            rate_uncompressed_numerator = None
            rate_denominator = None
        observations.append(
            {
                "coordinate_key": record.get("coordinate_key"),
                "envelope_bytes": cast(int, envelope_bytes),
                "sidecars_compressed_bytes": sidecars_compressed,
                "sidecars_uncompressed_bytes": sidecars_uncompressed,
                "fixed_sidecars_compressed_bytes": sidecars_compressed - token_compressed,
                "fixed_sidecars_uncompressed_bytes": sidecars_uncompressed - token_uncompressed,
                "token_rate_compressed_numerator_bytes": rate_compressed_numerator,
                "token_rate_uncompressed_numerator_bytes": rate_uncompressed_numerator,
                "token_rate_denominator_rows": rate_denominator,
            }
        )
    return observations


def _maximum_rate(
    observations: Sequence[Mapping[str, Any]], *, numerator_field: str
) -> tuple[int, int] | None:
    result: tuple[int, int] | None = None
    for observation in observations:
        numerator = observation.get(numerator_field)
        denominator = observation.get("token_rate_denominator_rows")
        if numerator is None and denominator is None:
            continue
        _require(
            type(numerator) is int
            and numerator >= 0
            and type(denominator) is int
            and denominator > 0,
            "Matrix token-rate observation is invalid.",
        )
        candidate = (cast(int, numerator), cast(int, denominator))
        if result is None or candidate[0] * result[1] > result[0] * candidate[1]:
            result = candidate
    return result


def _ceil_rate(rate: tuple[int, int], rows: int) -> int:
    _require(type(rows) is int and rows >= 0, "Storage projection row count is invalid.")
    return (rate[0] * rows + rate[1] - 1) // rate[1]


def _storage_rollup(
    records: Sequence[Mapping[str, Any]],
    *,
    remaining_coordinates: Sequence[ShardCoordinate] | None = None,
) -> dict[str, Any]:
    observations = _storage_observations(records)
    remaining_items = (
        tuple(coordinates()[len(records) :])
        if remaining_coordinates is None
        else tuple(remaining_coordinates)
    )
    _require(
        len(observations) + len(remaining_items) == EXPECTED_SHARDS,
        "Storage observations and remaining coordinates do not cover the frozen matrix.",
    )
    remaining = len(remaining_items)
    remaining_token_rows = sum(expected_decode_token_rows(item) for item in remaining_items)
    actual_sidecars_compressed = sum(
        cast(int, item["sidecars_compressed_bytes"]) for item in observations
    )
    actual_sidecars_uncompressed = sum(
        cast(int, item["sidecars_uncompressed_bytes"]) for item in observations
    )
    actual_envelopes = sum(cast(int, item["envelope_bytes"]) for item in observations)
    maximum_fixed_compressed = (
        max(cast(int, item["fixed_sidecars_compressed_bytes"]) for item in observations)
        if observations
        else None
    )
    maximum_fixed_uncompressed = (
        max(cast(int, item["fixed_sidecars_uncompressed_bytes"]) for item in observations)
        if observations
        else None
    )
    maximum_envelope = (
        max(cast(int, item["envelope_bytes"]) for item in observations) if observations else None
    )
    compressed_rate = _maximum_rate(
        observations, numerator_field="token_rate_compressed_numerator_bytes"
    )
    uncompressed_rate = _maximum_rate(
        observations, numerator_field="token_rate_uncompressed_numerator_bytes"
    )
    if remaining == 0:
        estimated_compressed: int | None = 0
        estimated_uncompressed: int | None = 0
        estimate_method: str | None = "terminal-no-remaining-coordinates-v1"
    elif compressed_rate is not None and uncompressed_rate is not None:
        _require(
            maximum_fixed_compressed is not None
            and maximum_fixed_uncompressed is not None
            and maximum_envelope is not None,
            "Token-rate observations lack fixed/envelope observations.",
        )
        fixed_compressed = cast(int, maximum_fixed_compressed)
        fixed_uncompressed = cast(int, maximum_fixed_uncompressed)
        envelope_high_water = cast(int, maximum_envelope)
        estimated_compressed = (fixed_compressed + envelope_high_water) * remaining + _ceil_rate(
            compressed_rate, remaining_token_rows
        )
        estimated_uncompressed = (
            fixed_uncompressed + envelope_high_water
        ) * remaining + _ceil_rate(uncompressed_rate, remaining_token_rows)
        estimate_method = "component-wise-observed-high-water-rebased-to-remaining-grid-v1"
    else:
        estimated_compressed = None
        estimated_uncompressed = None
        estimate_method = None
    actual_bundle_compressed = actual_sidecars_compressed + actual_envelopes
    actual_bundle_uncompressed = actual_sidecars_uncompressed + actual_envelopes
    return {
        "bundle_count_expected": EXPECTED_SHARDS,
        "sidecar_count_expected": EXPECTED_SHARDS * len(BUNDLE_KINDS),
        "completed_bundle_count": len(observations),
        "completed_sidecar_count": len(observations) * len(BUNDLE_KINDS),
        "positive_token_rate_observation_count": sum(
            item["token_rate_denominator_rows"] is not None for item in observations
        ),
        "zero_token_rate_unavailable_observation_count": sum(
            item["token_rate_denominator_rows"] is None for item in observations
        ),
        "observation_components_digest": contract.json_digest(observations),
        "remaining_shards": remaining,
        "remaining_decode_token_rows": remaining_token_rows,
        "remaining_estimate_semantics": (
            "observed-component-high-water-planning-estimate;not-a-future-upper-bound;"
            "not-a-reservation;not-a-write-guarantee"
        ),
        "remaining_estimate_method": estimate_method,
        "maximum_observed_fixed_sidecars_compressed_bytes_per_shard": (maximum_fixed_compressed),
        "maximum_observed_fixed_sidecars_uncompressed_bytes_per_shard": (
            maximum_fixed_uncompressed
        ),
        "maximum_observed_envelope_bytes_per_shard": maximum_envelope,
        "maximum_observed_token_compressed_rate_numerator_bytes": (
            None if compressed_rate is None else compressed_rate[0]
        ),
        "maximum_observed_token_compressed_rate_denominator_rows": (
            None if compressed_rate is None else compressed_rate[1]
        ),
        "maximum_observed_token_uncompressed_rate_numerator_bytes": (
            None if uncompressed_rate is None else uncompressed_rate[0]
        ),
        "maximum_observed_token_uncompressed_rate_denominator_rows": (
            None if uncompressed_rate is None else uncompressed_rate[1]
        ),
        "observed_high_water_remaining_compressed_bytes": estimated_compressed,
        "observed_high_water_remaining_uncompressed_bytes": estimated_uncompressed,
        "completed_actual_sidecars_compressed_bytes": actual_sidecars_compressed,
        "completed_actual_sidecars_uncompressed_bytes": actual_sidecars_uncompressed,
        "completed_actual_envelopes_bytes": actual_envelopes,
        "completed_actual_bundle_compressed_bytes": actual_bundle_compressed,
        "completed_actual_bundle_uncompressed_bytes": actual_bundle_uncompressed,
        "ledger_actual_plus_observed_high_water_estimate_compressed_bytes": (
            None
            if estimated_compressed is None
            else actual_bundle_compressed + estimated_compressed
        ),
        "ledger_actual_plus_observed_high_water_estimate_uncompressed_bytes": (
            None
            if estimated_uncompressed is None
            else actual_bundle_uncompressed + estimated_uncompressed
        ),
        "next_launch_headroom_policy": {
            "method": NEXT_LAUNCH_HEADROOM_METHOD,
            "frozen_minimum_one_shard_headroom_bytes": (FROZEN_MINIMUM_ONE_SHARD_HEADROOM_BYTES),
            "outcome_independent_inputs": [
                "completed-record-byte-components",
                "next-coordinate-decode-row-count",
                "filesystem-available-bytes",
            ],
            "limitations": NEXT_LAUNCH_HEADROOM_LIMITATIONS,
        },
    }


def _headroom_signal_payload(
    *,
    records: Sequence[Mapping[str, Any]],
    coordinate: ShardCoordinate,
    filesystem_available_bytes: int,
) -> dict[str, Any]:
    _require(
        type(filesystem_available_bytes) is int and filesystem_available_bytes >= 0,
        "Filesystem available-byte observation is invalid.",
    )
    observations = _storage_observations(records)
    compressed_rate = _maximum_rate(
        observations, numerator_field="token_rate_compressed_numerator_bytes"
    )
    maximum_fixed = max(
        (cast(int, item["fixed_sidecars_compressed_bytes"]) for item in observations),
        default=0,
    )
    maximum_envelope = max((cast(int, item["envelope_bytes"]) for item in observations), default=0)
    next_rows = expected_decode_token_rows(coordinate)
    observed_estimate = (
        None
        if compressed_rate is None
        else maximum_fixed + maximum_envelope + _ceil_rate(compressed_rate, next_rows)
    )
    required = max(
        FROZEN_MINIMUM_ONE_SHARD_HEADROOM_BYTES,
        maximum_fixed + maximum_envelope,
        0 if observed_estimate is None else observed_estimate,
    )
    return {
        "schema_version": 1,
        "signal_type": "infrastructure-storage-headroom-pause-v1",
        "retryable": True,
        "coordinate_key": coordinate.key,
        "method": NEXT_LAUNCH_HEADROOM_METHOD,
        "outcome_independent": True,
        "completed_record_count": len(observations),
        "positive_token_rate_observation_count": sum(
            item["token_rate_denominator_rows"] is not None for item in observations
        ),
        "next_coordinate_decode_token_rows": next_rows,
        "observed_next_shard_estimate_compressed_bytes": observed_estimate,
        "frozen_minimum_one_shard_headroom_bytes": FROZEN_MINIMUM_ONE_SHARD_HEADROOM_BYTES,
        "required_headroom_bytes": required,
        "filesystem_available_bytes": filesystem_available_bytes,
        "sufficient": filesystem_available_bytes >= required,
        "limitations": NEXT_LAUNCH_HEADROOM_LIMITATIONS,
    }


def _next_launch_headroom_preflight(
    *,
    output_root: Path,
    records: Sequence[Mapping[str, Any]],
    coordinate: ShardCoordinate,
) -> dict[str, Any]:
    payload = _current_headroom_signal(
        output_root=output_root,
        records=records,
        coordinate=coordinate,
    )
    if not payload["sufficient"]:
        raise InfrastructurePauseSignal(payload)
    return payload


def _current_headroom_signal(
    *,
    output_root: Path,
    records: Sequence[Mapping[str, Any]],
    coordinate: ShardCoordinate,
) -> dict[str, Any]:
    output_root.mkdir(parents=True, exist_ok=True)
    filesystem = os.statvfs(output_root)
    available = filesystem.f_bavail * filesystem.f_frsize
    return _headroom_signal_payload(
        records=records,
        coordinate=coordinate,
        filesystem_available_bytes=available,
    )


def _validate_launcher_binding_snapshot(value: Mapping[str, Any]) -> dict[str, Any]:
    _require(
        set(value) == {"launcher", "python_runtime", "source_provenance"}
        and value.get("launcher")
        == {
            "schema_version": 1,
            "launcher": "p2-direct-controller-git-object-launcher-v1-3-5",
            "sealed_runner": True,
            "sealed_inventory": True,
        }
        and isinstance(value.get("python_runtime"), Mapping)
        and isinstance(value.get("source_provenance"), Mapping),
        "Matrix sealed launcher/runtime binding schema drifted.",
    )
    runtime = cast(Mapping[str, Any], value["python_runtime"])
    source = cast(Mapping[str, Any], value["source_provenance"])
    _require(
        set(runtime)
        == {
            "schema_version",
            "implementation",
            "cache_tag",
            "version",
            "executable",
            "venv_executable",
            "resolved_executable",
            "executable_sha256",
            "executable_metadata",
            "base_prefix",
            "site_packages",
        }
        and runtime.get("schema_version") == 1
        and contract.is_sha256(runtime.get("executable_sha256"))
        and isinstance(runtime.get("executable_metadata"), Mapping),
        "Matrix sealed Python runtime binding drifted.",
    )
    _require(
        set(source)
        == {
            "schema_version",
            "launcher",
            "repository_root",
            "bundle_sha256",
            "pinned_head_oid",
            "frozen_source_commit",
            "implementation_tree_digest",
            "head_manifest",
        }
        and source.get("schema_version") == 1
        and contract.is_sha256(source.get("bundle_sha256"))
        and contract.is_sha256(source.get("implementation_tree_digest"))
        and isinstance(source.get("head_manifest"), Mapping),
        "Matrix sealed source provenance binding drifted.",
    )
    if globals().get("SEALED_LAUNCH_AUTHORITY_V1_3_5") is not None:
        active_authority = globals().get("SEALED_LAUNCH_AUTHORITY_V1_3_5")
        _require(
            active_authority
            == {
                "schema_version": 1,
                "launcher": "p2-direct-controller-git-object-launcher-v1-3-5",
                "sealed_runner": True,
                "sealed_inventory": True,
            }
            and dict(value)
            == {
                "launcher": dict(cast(Mapping[str, Any], active_authority)),
                "python_runtime": _validated_launcher_python_runtime(),
                "source_provenance": _validated_source_provenance(),
            },
            "Matrix launcher/runtime binding differs from active sealed authority.",
        )
    return dict(value)


def _validate_launch_routing_snapshot(
    value: Mapping[str, Any],
    *,
    expected_selector: str,
    source_provenance: Mapping[str, Any],
) -> dict[str, Any]:
    expected_paths = {
        "matrix": (
            "research/adaptive_v4_memory/scripts/"
            "run_p2_direct_controller_matrix_v1_3.py"
        ),
        "audit": (
            "research/adaptive_v4_memory/scripts/"
            "audit_p2_direct_controller_integrity_v1_3.py"
        ),
        "summary": (
            "research/adaptive_v4_memory/scripts/"
            "summarize_p2_direct_controller_v1_3.py"
        ),
    }
    _require(
        expected_selector in expected_paths
        and set(value)
        == {
            "schema_version",
            "launcher",
            "entrypoint_selector",
            "entrypoint_relative_path",
            "source_bundle_sha256",
            "git_mode",
            "git_blob_oid",
            "sha256",
            "bytes",
        }
        and value.get("schema_version") == 1
        and value.get("launcher")
        == "p2-direct-controller-git-object-launcher-v1-3-5"
        and value.get("entrypoint_selector") == expected_selector
        and value.get("entrypoint_relative_path") == expected_paths[expected_selector]
        and value.get("source_bundle_sha256")
        == source_provenance.get("bundle_sha256")
        and value.get("git_mode") in {"100644", "100755"}
        and contract.is_git_oid(value.get("git_blob_oid"))
        and contract.is_sha256(value.get("sha256"))
        and type(value.get("bytes")) is int
        and cast(int, value["bytes"]) > 0,
        "Sealed launch-routing snapshot drifted.",
    )
    active = globals().get("SEALED_LAUNCH_ROUTING_V1_3_5")
    if active is not None:
        _require(
            dict(value) == _validated_launch_routing(expected_selector=expected_selector),
            "Stored launch routing differs from active sealed routing.",
        )
    return dict(value)


def _validate_persistent_session_ledger_snapshot(
    value: Mapping[str, Any],
    *,
    output_root: Path,
    trust_root: attestation.TrustRoot,
    require_current_exact: bool,
) -> dict[str, Any]:
    snapshot: dict[str, Any] = persistent_session.validate_session_ledger_projection(value)
    _require(
        snapshot["root"] == str(persistent_session.session_ledger_root(_absolute(output_root))),
        "Matrix persistent-session ledger root drifted.",
    )
    current = persistent_session.load_session_ledger_projection(
        _absolute(output_root), trust_root=trust_root
    )
    if require_current_exact:
        _require(
            snapshot == current,
            "Terminal matrix persistent-session ledger is not the exact current closed world.",
        )
        return snapshot
    current_registry = {
        (row["kind"], row["session_nonce"]): row for row in current["registry"]
    }
    _require(
        all(
            current_registry.get((row["kind"], row["session_nonce"])) == row
            for row in snapshot["registry"]
        ),
        "Matrix persistent-session file watermark is not a monotone verified subset.",
    )
    current_sessions = {row["session_nonce"]: row for row in current["sessions"]}
    for prior in snapshot["sessions"]:
        observed = current_sessions.get(prior["session_nonce"])
        _require(observed is not None, "Matrix persistent-session watermark lost a session.")
        if prior == observed:
            continue
        observed_map = cast(Mapping[str, Any], observed)
        static_fields = {
            "session_nonce",
            "launch_authority_nonce",
            "plan_payload_sha256",
            "worker_index",
            "worker_count",
            "scale",
            "training_seed",
            "coordinate_count",
            "coordinate_digest",
            "max_new_cells_stop_limit",
        }
        _require(
            prior["status"] == "launch_only"
            and all(prior[field] == observed_map[field] for field in static_fields),
            "Matrix persistent-session watermark changed non-monotonically.",
        )
    return snapshot


def _validate_ready_only_preflight_snapshot(
    value: Mapping[str, Any],
    *,
    session_projection: Mapping[str, Any],
    output_root: Path,
    prerequisites: FrozenPrerequisites,
    evaluator_binding: Mapping[str, Any],
    gpu_lease_binding: Mapping[str, Any],
) -> dict[str, Any]:
    reconstructed = persistent_session.ready_only_preflight_binding(
        session_projection
    )
    _require(
        reconstructed is not None and dict(value) == reconstructed,
        "Matrix ready-only preflight differs from its authenticated ledger reconstruction.",
    )
    checked = cast(dict[str, Any], reconstructed)
    first = _mixed_device_coordinates(contract.V1_3_5_MIXED_DEVICE_SITE)[0]
    inputs = prerequisites.bundles[
        (first.scale, first.training_seed, first.budget)
    ]
    _isolated_evaluator_pycache_prefix(cast(str, checked["session_nonce"]))
    _require(
        checked["output_root"] == str(_absolute(output_root))
        and checked["input_binding_digest"]
        == cast(str, inputs.binding["input_binding_digest"])
        and checked["canonical_evaluator_digest"]
        == contract.json_digest(evaluator_binding)
        and checked["gpu_lease_binding_digest"]
        == contract.json_digest(gpu_lease_binding)
        and checked["prerequisites_binding_digest"]
        == contract.json_digest(prerequisites.public_binding)
        and checked["coordinate_digest"]
        == contract.json_digest([first.payload])
        and checked["quality_work_order_count"] == 0
        and checked["quality_result_count"] == 0
        and checked["model_state_reset_count"] == 0
        and checked["published_bundle_reingestion_count"] == 0
        and checked["outcome_dependent_selection"] is False
        and checked["child_process_returncode"] == 0,
        "Matrix ready-only preflight authority or zero-work semantics drifted.",
    )
    return checked


def _crosscheck_matrix_records_with_session_ledger(
    records: Sequence[Mapping[str, Any]],
    projection: Mapping[str, Any],
    *,
    require_terminal_sessions: bool,
) -> None:
    sessions = {row["session_nonce"]: row for row in projection["sessions"]}
    observed_result_digests: dict[str, list[tuple[int, str, str]]] = {}
    eof_records: dict[str, list[Mapping[str, Any]]] = {}
    for record in records:
        execution = record.get("persistent_session_execution")
        _require(isinstance(execution, Mapping), "Matrix record lacks persistent execution.")
        execution_map = cast(Mapping[str, Any], execution)
        raw_plan = execution_map.get("plan")
        raw_work = execution_map.get("work_order")
        _require(
            isinstance(raw_plan, Mapping) and isinstance(raw_work, Mapping),
            "Matrix persistent execution plan or work order is missing.",
        )
        plan = cast(Mapping[str, Any], raw_plan)
        work = cast(Mapping[str, Any], raw_work)
        session_nonce = cast(str, plan.get("session_nonce"))
        session = sessions.get(session_nonce)
        _require(session is not None, "Matrix record session is absent from durable ledger.")
        session_map = cast(Mapping[str, Any], session)
        _require(
            session_map["launch_authority_nonce"] == plan.get("launch_authority_nonce")
            and session_map["plan_payload_sha256"] == plan.get("payload_sha256")
            and session_map["worker_index"] == plan.get("worker_index")
            and session_map["worker_count"] == plan.get("worker_count")
            and session_map["scale"] == plan.get("scale")
            and session_map["training_seed"] == plan.get("training_seed")
            and session_map["coordinate_count"] == plan.get("coordinate_count")
            and session_map["coordinate_digest"] == plan.get("coordinate_digest")
            and execution_map.get("session_command")
            == session_map["actual_session_argv"],
            "Matrix record plan or argv is not bound to its durable session launch.",
        )
        result = execution_map.get("work_result")
        if result is None:
            _require(
                execution_map.get("published_bundle_reingested_after_child_eof") is True,
                "EOF matrix record lacks its exact reingestion disclosure.",
            )
            eof_records.setdefault(session_nonce, []).append(record)
            if session_map["status"] != "launch_only":
                _require(
                    session_map["status"]
                    in {"child_eof", "parent_crash_recovered"}
                    and session_map["published_bundle_reingestion_count"] == 1
                    and work.get("sequence_index")
                    == len(cast(list[Any], session_map["completed_work_payload_sha256"])),
                    "EOF matrix record is not the next durable reingested session coordinate.",
                )
            continue
        result_map = cast(Mapping[str, Any], result)
        sequence_index = cast(int, work.get("sequence_index"))
        observed_result_digests.setdefault(session_nonce, []).append(
            (
                sequence_index,
                cast(str, work.get("payload_sha256")),
                cast(str, result_map.get("payload_sha256")),
            )
        )
        if session_map["status"] != "launch_only":
            completed_work = cast(
                list[Any], session_map["completed_work_payload_sha256"]
            )
            completed_results = cast(
                list[Any], session_map["completed_result_payload_sha256"]
            )
            _require(
                sequence_index < len(completed_work)
                and completed_work[sequence_index] == work.get("payload_sha256")
                and completed_results[sequence_index] == result_map.get("payload_sha256"),
                "Matrix work/result digest differs from its durable terminal session ledger.",
            )
    for _nonce, rows in eof_records.items():
        _require(len(rows) == 1, "A durable child-EOF session has multiple reingested records.")
    if not require_terminal_sessions:
        return
    _require(
        all(session["status"] != "launch_only" for session in sessions.values()),
        "Terminal matrix contains a committed record under a launch-only session.",
    )
    for nonce, session in sessions.items():
        observed = sorted(observed_result_digests.get(nonce, []))
        expected = list(
            enumerate(
                zip(
                    session["completed_work_payload_sha256"],
                    session["completed_result_payload_sha256"],
                    strict=True,
                )
            )
        )
        _require(
            observed == [(index, pair[0], pair[1]) for index, pair in expected],
            "Terminal durable session work/result inventory is not exactly represented by matrix records.",
        )
        if session["published_bundle_reingestion_count"] == 1:
            _require(
                len(eof_records.get(nonce, [])) == 1,
                "Terminal reingestion counter lacks exactly one EOF matrix record.",
            )


def _matrix_body_without_session_projection(value: Mapping[str, Any]) -> dict[str, Any]:
    body = dict(value)
    body.pop("payload_sha256", None)
    body.pop("attestation", None)
    body["persistent_session_ledger"] = None
    if body.get("status") == "awaiting_session_terminal":
        records = cast(list[Mapping[str, Any]], body["records"])
        body["status"] = "terminal"
        body["integrity_status"] = (
            "INTEGRITY-PASS"
            if all(
                record.get("integrity_decision") == "INTEGRITY-PASS"
                for record in records
            )
            else "INTEGRITY-FAIL"
        )
    return body


def _blocked_resume_body_without_session_projection(
    value: Mapping[str, Any],
) -> dict[str, Any]:
    status = value.get("status")
    _require(
        status in {"paused_infrastructure", "draining_infrastructure"},
        "Session-ledger refresh expected a blocked matrix payload.",
    )
    reason_field = (
        "infrastructure_pause"
        if status == "paused_infrastructure"
        else "infrastructure_drain"
    )
    body = dict(value)
    body.pop("payload_sha256", None)
    body.pop("attestation", None)
    body.pop(reason_field)
    body["status"] = "in_progress"
    body["integrity_status"] = None
    records = cast(list[Mapping[str, Any]], body["records"])
    body["integrity_pass_shards"] = sum(
        record.get("integrity_decision") == "INTEGRITY-PASS" for record in records
    )
    body["integrity_fail_shards"] = sum(
        record.get("integrity_decision") == "INTEGRITY-FAIL" for record in records
    )
    body["persistent_session_ledger"] = None
    return body


def _refresh_matrix_session_projection(
    *,
    disk_payload: Mapping[str, Any],
    current_resume_payload: Mapping[str, Any],
    matrix_summary: Path,
    trust_root: attestation.TrustRoot,
) -> dict[str, Any]:
    status = disk_payload.get("status")
    if status not in {"paused_infrastructure", "draining_infrastructure"}:
        _require(
            _matrix_body_without_session_projection(disk_payload)
            == _matrix_body_without_session_projection(current_resume_payload),
            "Matrix changed beyond its monotone persistent-session ledger watermark.",
        )
        if disk_payload == current_resume_payload:
            return dict(disk_payload)
        refreshed = dict(current_resume_payload)
        _atomic_write_json(matrix_summary, refreshed)
        return refreshed
    _require(
        _blocked_resume_body_without_session_projection(disk_payload)
        == _matrix_body_without_session_projection(current_resume_payload),
        "Blocked matrix changed beyond its monotone persistent-session ledger watermark.",
    )
    reason_field = (
        "infrastructure_pause"
        if status == "paused_infrastructure"
        else "infrastructure_drain"
    )
    reason = cast(Mapping[str, Any], disk_payload[reason_field])
    if reason.get("resume_matrix_payload_sha256") == current_resume_payload.get(
        "payload_sha256"
    ):
        return dict(disk_payload)
    signal = {field: reason[field] for field in _HEADROOM_SIGNAL_FIELDS}
    worker_index = cast(int, reason["pause_worker_index"])
    if status == "paused_infrastructure":
        refreshed = _paused_matrix_payload(
            current_resume_payload,
            signal=signal,
            worker_index=worker_index,
            trust_root=trust_root,
        )
    else:
        refreshed = _draining_matrix_payload(
            current_resume_payload,
            signal=signal,
            worker_index=worker_index,
            active_claim_coordinate_indices=cast(
                list[int], reason["active_claim_coordinate_indices"]
            ),
            trust_root=trust_root,
        )
    _atomic_write_json(matrix_summary, refreshed)
    return refreshed


def _matrix_payload(
    records: Sequence[Mapping[str, Any]],
    *,
    output_root: Path,
    prerequisites: FrozenPrerequisites,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    worker_count: int = 1,
    gpu_worker_leases: Mapping[int, Mapping[str, Any]],
    worker_ledger_root: Mapping[str, Any] | None = None,
    worker_ledger_bindings: Sequence[Mapping[str, Any]] = (),
    globally_committed_shards: int | None = None,
    storage_records: Sequence[Mapping[str, Any]] | None = None,
    storage_remaining_coordinates: Sequence[ShardCoordinate] | None = None,
) -> dict[str, Any]:
    _require(type(worker_count) is int and worker_count > 0, "Matrix worker count is invalid.")
    committed_shards = (
        len(records) if globally_committed_shards is None else globally_committed_shards
    )
    _require(
        type(committed_shards) is int
        and len(records) <= committed_shards <= EXPECTED_SHARDS
        and (worker_count > 1 or committed_shards == len(records)),
        "Matrix global committed-shard count is invalid.",
    )
    session_projection = persistent_session.load_session_ledger_projection(
        _absolute(output_root), trust_root=prerequisites.trust_root
    )
    ready_only_preflight = persistent_session.ready_only_preflight_binding(
        session_projection
    )
    _require(
        worker_count != 1 or ready_only_preflight is not None,
        "Single-worker matrix lacks its authenticated ready-only preflight.",
    )
    referenced_sessions = {
        cast(str, cast(Mapping[str, Any], record["persistent_session_execution"])["plan"]["session_nonce"])
        for record in records
    }
    launch_only_sessions = {
        cast(str, row["session_nonce"])
        for row in cast(list[Mapping[str, Any]], session_projection["sessions"])
        if row["status"] == "launch_only"
    }
    full_coordinate_set = len(records) == EXPECTED_SHARDS
    awaiting_session_terminal = (
        full_coordinate_set
        and bool(referenced_sessions & launch_only_sessions)
    )
    terminal = full_coordinate_set and not awaiting_session_terminal
    pass_count = sum(record.get("integrity_decision") == "INTEGRITY-PASS" for record in records)
    fail_count = sum(record.get("integrity_decision") == "INTEGRITY-FAIL" for record in records)
    integrity_status: str | None = None
    if terminal:
        integrity_status = "INTEGRITY-PASS" if fail_count == 0 else "INTEGRITY-FAIL"
    gpu_registry = _gpu_registry_payload(gpu_worker_leases, worker_count=worker_count)
    gpu_device_registry = _gpu_device_identity_registry(
        gpu_worker_leases, worker_count=worker_count
    )
    frozen_projection = prerequisites.public_binding.get("execution_environment_projection")
    _require(
        isinstance(frozen_projection, Mapping)
        and isinstance(frozen_projection.get("selected_device_class"), Mapping),
        "Frozen selected GPU device class is missing from prerequisites.",
    )
    frozen_projection_map = cast(Mapping[str, Any], frozen_projection)
    selected_device_class = dict(
        cast(Mapping[str, Any], frozen_projection_map["selected_device_class"])
    )
    _require(
        all(item.get("selected_device_class") == selected_device_class for item in gpu_registry),
        "GPU worker leases do not match the frozen selected-device class.",
    )
    _require(
        (worker_count == 1 and tuple(gpu_worker_leases) == (0,))
        or (worker_count > 1 and (not terminal or len(gpu_worker_leases) == worker_count)),
        "Matrix GPU worker-lease registry is incomplete.",
    )
    if worker_count == 1:
        _require(
            worker_ledger_root is None and not worker_ledger_bindings,
            "Single-worker matrix requires an exact empty worker-ledger registry.",
        )
    else:
        raw_worker_root = {} if worker_ledger_root is None else dict(worker_ledger_root)
        raw_root_path = raw_worker_root.get("path")
        _require(
            set(raw_worker_root) == {"path", "semantics", "path_semantics", "worker_count"}
            and isinstance(raw_root_path, str)
            and Path(raw_root_path) == Path(os.path.abspath(raw_root_path))
            and raw_worker_root.get("semantics") == WORKER_LEDGER_ROOT_SEMANTICS
            and raw_worker_root.get("path_semantics") == WORKER_LEDGER_PATH_SEMANTICS
            and raw_worker_root.get("worker_count") == worker_count,
            "Distributed worker-ledger root contract drifted.",
        )
    observed_storage_records = records if storage_records is None else storage_records
    _require(
        len(observed_storage_records) == committed_shards,
        "Storage observations do not cover every globally committed shard.",
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "experiment_id": EXPERIMENT_ID,
        "artifact_type": ARTIFACT_TYPE,
        "status": (
            "terminal"
            if terminal
            else "awaiting_session_terminal"
            if awaiting_session_terminal
            else "in_progress"
        ),
        "integrity_status": integrity_status,
        "source": prerequisites.context.source,
        "manifest": prerequisites.context.manifest_binding,
        "attestation_contract": prerequisites.context.manifest_binding["attestation"],
        "prerequisites": dict(prerequisites.public_binding),
        "canonical_evaluator": dict(evaluator_binding),
        "matrix_lock": dict(matrix_lock_binding),
        "gpu_worker_leases": gpu_registry,
        "gpu_device_identity_registry": gpu_device_registry,
        "selected_device_class": selected_device_class,
        "worker_ledger_assignment_rule": (None if worker_count == 1 else WORKER_ASSIGNMENT_RULE),
        "worker_ledger_root": None if worker_ledger_root is None else dict(worker_ledger_root),
        "worker_ledger_registry": [dict(item) for item in worker_ledger_bindings],
        "execution_mode": "single-worker" if worker_count == 1 else "distributed-workers",
        "worker_count": worker_count,
        "cell_claim_semantics": CELL_CLAIM_SEMANTICS,
        "crash_recovery_boundary": CRASH_RECOVERY_BOUNDARY,
        "outcome_policy": OUTCOME_POLICY,
        "outcome_dependent_early_stopping": False,
        "outcome_selection_performed": False,
        "quality_outcomes_aggregated": False,
        "coordinate_order": ("scale,training_seed,budget,family,context,replicate"),
        "coordinate_count": EXPECTED_SHARDS,
        "coordinate_digest": coordinate_digest(),
        "examples_per_shard": EXAMPLES_PER_SHARD,
        "arm_names": list(ARM_NAMES),
        "expected_outcome_rows": EXPECTED_OUTCOME_ROWS,
        "completed_shards": committed_shards,
        "canonical_prefix_shards": len(records),
        "globally_committed_shards": committed_shards,
        "integrity_pass_shards": pass_count,
        "integrity_fail_shards": fail_count,
        "storage_aggregation_scope": "all-globally-committed-records-v1",
        "storage": _storage_rollup(
            observed_storage_records,
            remaining_coordinates=storage_remaining_coordinates,
        ),
        "sealed_launcher": _require_launcher_authority(),
        "launch_routing": _validated_launch_routing(
            expected_selector="matrix"
        ),
        "ready_only_preflight": ready_only_preflight,
        "persistent_session_ledger": session_projection,
        "records": list(records),
    }
    return _attested_payload(payload, trust_root=prerequisites.trust_root)


def _paused_matrix_payload(
    resume_payload: Mapping[str, Any],
    *,
    signal: Mapping[str, Any],
    worker_index: int,
    trust_root: attestation.TrustRoot,
) -> dict[str, Any]:
    _verify_attested_payload(resume_payload, trust_root=trust_root)
    _require(
        set(resume_payload) == _MATRIX_FIELDS and resume_payload.get("status") == "in_progress",
        "Infrastructure pause requires a valid in-progress resume payload.",
    )
    _require(
        set(signal) == _HEADROOM_SIGNAL_FIELDS
        and signal.get("schema_version") == 1
        and signal.get("signal_type") == "infrastructure-storage-headroom-pause-v1"
        and signal.get("retryable") is True
        and signal.get("method") == NEXT_LAUNCH_HEADROOM_METHOD
        and signal.get("outcome_independent") is True
        and signal.get("sufficient") is False
        and type(signal.get("filesystem_available_bytes")) is int
        and type(signal.get("required_headroom_bytes")) is int
        and cast(int, signal["filesystem_available_bytes"])
        < cast(int, signal["required_headroom_bytes"]),
        "Infrastructure pause signal is not an exact insufficient-headroom reason.",
    )
    worker_count = resume_payload.get("worker_count")
    _require(
        type(worker_count) is int and 0 <= worker_index < worker_count,
        "Infrastructure pause worker identity is invalid.",
    )
    body = dict(resume_payload)
    body.pop("payload_sha256")
    body.pop("attestation")
    body.pop("integrity_status")
    body.pop("integrity_pass_shards")
    body.pop("integrity_fail_shards")
    body["status"] = "paused_infrastructure"
    body["infrastructure_pause"] = {
        **dict(signal),
        "resume_rule": INFRASTRUCTURE_PAUSE_RESUME_RULE,
        "matrix_records_digest": contract.json_digest(resume_payload["records"]),
        "canonical_prefix_shards": resume_payload["canonical_prefix_shards"],
        "globally_committed_shards": resume_payload["globally_committed_shards"],
        "worker_ledger_registry_digest": contract.json_digest(
            resume_payload["worker_ledger_registry"]
        ),
        "resume_matrix_payload_sha256": resume_payload["payload_sha256"],
        "pause_worker_index": worker_index,
        "pause_worker_count": worker_count,
    }
    return _attested_payload(body, trust_root=trust_root)


def _draining_matrix_payload(
    resume_payload: Mapping[str, Any],
    *,
    signal: Mapping[str, Any],
    worker_index: int,
    active_claim_coordinate_indices: Sequence[int],
    trust_root: attestation.TrustRoot,
) -> dict[str, Any]:
    _verify_attested_payload(resume_payload, trust_root=trust_root)
    _require(
        set(resume_payload) == _MATRIX_FIELDS and resume_payload.get("status") == "in_progress",
        "Infrastructure drain requires a valid in-progress resume payload.",
    )
    _require(
        set(signal) == _HEADROOM_SIGNAL_FIELDS
        and signal.get("schema_version") == 1
        and signal.get("signal_type") == "infrastructure-storage-headroom-pause-v1"
        and signal.get("retryable") is True
        and signal.get("method") == NEXT_LAUNCH_HEADROOM_METHOD
        and signal.get("outcome_independent") is True
        and type(signal.get("sufficient")) is bool,
        "Infrastructure drain headroom signal is invalid.",
    )
    worker_count = resume_payload.get("worker_count")
    _require(
        type(worker_count) is int and 0 <= worker_index < worker_count,
        "Infrastructure drain owner identity is invalid.",
    )
    active = sorted(active_claim_coordinate_indices)
    _require(
        len(active) == len(set(active))
        and all(type(index) is int and 0 <= index < EXPECTED_SHARDS for index in active),
        "Infrastructure drain active-claim inventory is invalid.",
    )
    body = dict(resume_payload)
    body.pop("payload_sha256")
    body.pop("attestation")
    body.pop("integrity_status")
    body.pop("integrity_pass_shards")
    body.pop("integrity_fail_shards")
    body["status"] = "draining_infrastructure"
    body["infrastructure_drain"] = {
        **dict(signal),
        "resume_rule": INFRASTRUCTURE_PAUSE_RESUME_RULE,
        "matrix_records_digest": contract.json_digest(resume_payload["records"]),
        "canonical_prefix_shards": resume_payload["canonical_prefix_shards"],
        "globally_committed_shards": resume_payload["globally_committed_shards"],
        "worker_ledger_registry_digest": contract.json_digest(
            resume_payload["worker_ledger_registry"]
        ),
        "resume_matrix_payload_sha256": resume_payload["payload_sha256"],
        "pause_worker_index": worker_index,
        "pause_worker_count": worker_count,
        "drain_rule": INFRASTRUCTURE_DRAIN_RULE,
        "active_claim_coordinate_indices": active,
        "active_claim_count": len(active),
    }
    return _attested_payload(body, trust_root=trust_root)


def _infrastructure_owner(payload: Mapping[str, Any]) -> int:
    status = payload.get("status")
    _require(
        status in {"paused_infrastructure", "draining_infrastructure"},
        "Matrix is not infrastructure-blocked.",
    )
    reason_field = (
        "infrastructure_pause" if status == "paused_infrastructure" else "infrastructure_drain"
    )
    reason = payload.get(reason_field)
    _require(isinstance(reason, Mapping), "Infrastructure owner binding is missing.")
    owner = cast(Mapping[str, Any], reason).get("pause_worker_index")
    _require(type(owner) is int, "Infrastructure owner binding is invalid.")
    return cast(int, owner)


def _rebind_infrastructure_after_commit(
    *,
    prior_blocked_payload: Mapping[str, Any],
    resume_payload: Mapping[str, Any],
    ledgers: Mapping[int, Sequence[Mapping[str, Any]]],
    merged_records: Mapping[int, Mapping[str, Any]],
    active_claim_coordinate_indices: Sequence[int],
    output_root: Path,
    worker_count: int,
    trust_root: attestation.TrustRoot,
) -> dict[str, Any]:
    owner = _infrastructure_owner(prior_blocked_payload)
    owner_records = ledgers.get(owner)
    _require(owner_records is not None, "Infrastructure owner worker ledger disappeared.")
    bound_owner_records = cast(Sequence[Mapping[str, Any]], owner_records)
    assigned = _assigned_coordinates(worker_index=owner, worker_count=worker_count)
    if len(bound_owner_records) == len(assigned):
        resumable_workers = [
            candidate
            for candidate, candidate_records in sorted(ledgers.items())
            if len(candidate_records)
            < len(
                _assigned_coordinates(
                    worker_index=candidate, worker_count=worker_count
                )
            )
        ]
        _require(
            bool(resumable_workers),
            "Infrastructure drain has no initialized resumable worker.",
        )
        owner = resumable_workers[0]
        bound_owner_records = ledgers[owner]
        assigned = _assigned_coordinates(
            worker_index=owner, worker_count=worker_count
        )
    _require(
        len(bound_owner_records) < len(assigned),
        "Infrastructure owner no longer has a resumable coordinate.",
    )
    signal = _current_headroom_signal(
        output_root=output_root,
        records=[merged_records[index] for index in sorted(merged_records)],
        coordinate=assigned[len(bound_owner_records)],
    )
    if active_claim_coordinate_indices or signal["sufficient"]:
        return _draining_matrix_payload(
            resume_payload,
            signal=signal,
            worker_index=owner,
            active_claim_coordinate_indices=active_claim_coordinate_indices,
            trust_root=trust_root,
        )
    return _paused_matrix_payload(
        resume_payload,
        signal=signal,
        worker_index=owner,
        trust_root=trust_root,
    )


def _headroom_preflight_with_attested_pause(
    *,
    output_root: Path,
    matrix_summary: Path,
    storage_records: Sequence[Mapping[str, Any]],
    coordinate: ShardCoordinate,
    current_payload: Mapping[str, Any],
    resume_payload: Mapping[str, Any],
    worker_index: int,
    active_claim_coordinate_indices: Sequence[int] = (),
    trust_root: attestation.TrustRoot,
) -> dict[str, Any]:
    _require(
        current_payload.get("status")
        in {"in_progress", "paused_infrastructure", "draining_infrastructure"}
        and resume_payload.get("status") == "in_progress",
        "Headroom preflight requires in-progress, draining, or paused infrastructure state.",
    )
    if current_payload.get("status") in {"paused_infrastructure", "draining_infrastructure"}:
        reason_field = (
            "infrastructure_pause"
            if current_payload.get("status") == "paused_infrastructure"
            else "infrastructure_drain"
        )
        prior_pause = current_payload.get(reason_field)
        _require(
            isinstance(prior_pause, Mapping)
            and cast(Mapping[str, Any], prior_pause).get("pause_worker_index") == worker_index
            and cast(Mapping[str, Any], prior_pause).get("resume_matrix_payload_sha256")
            == resume_payload.get("payload_sha256"),
            "Only the bound paused worker may rerun infrastructure headroom.",
        )
    try:
        result = _next_launch_headroom_preflight(
            output_root=output_root,
            records=storage_records,
            coordinate=coordinate,
        )
    except InfrastructurePauseSignal as signal:
        if active_claim_coordinate_indices:
            draining = _draining_matrix_payload(
                resume_payload,
                signal=signal.payload,
                worker_index=worker_index,
                active_claim_coordinate_indices=active_claim_coordinate_indices,
                trust_root=trust_root,
            )
            _atomic_write_json(matrix_summary, draining)
            raise InfrastructurePauseSignal(
                cast(Mapping[str, Any], draining["infrastructure_drain"])
            ) from None
        paused = _paused_matrix_payload(
            resume_payload,
            signal=signal.payload,
            worker_index=worker_index,
            trust_root=trust_root,
        )
        _atomic_write_json(matrix_summary, paused)
        raise InfrastructurePauseSignal(
            cast(Mapping[str, Any], paused["infrastructure_pause"])
        ) from None
    if (
        current_payload.get("status") == "draining_infrastructure"
        and active_claim_coordinate_indices
    ):
        draining = _draining_matrix_payload(
            resume_payload,
            signal=result,
            worker_index=worker_index,
            active_claim_coordinate_indices=active_claim_coordinate_indices,
            trust_root=trust_root,
        )
        _atomic_write_json(matrix_summary, draining)
        raise InfrastructurePauseSignal(cast(Mapping[str, Any], draining["infrastructure_drain"]))
    if current_payload.get("status") in {"paused_infrastructure", "draining_infrastructure"}:
        _atomic_write_json(matrix_summary, resume_payload)
    return result


def _validate_record_shape(record: Mapping[str, Any], coordinate: ShardCoordinate) -> None:
    for field, expected in coordinate.payload.items():
        _require(record.get(field) == expected, f"Matrix record {field} drifted: {coordinate.key}.")
    _require(record.get("coordinate_key") == coordinate.key, "Matrix coordinate key drifted.")
    _require(record.get("status") == "terminal", "Matrix record is not terminal.")
    _require(contract.is_sha256(record.get("launch_nonce")), "Matrix launch nonce is invalid.")


def _validate_record_against_coordinate(
    record: Mapping[str, Any],
    *,
    coordinate: ShardCoordinate,
    output_root: Path,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    gpu_lease_binding: Mapping[str, Any],
    verify_bundle: bool,
) -> dict[str, Any]:
    _validate_record_shape(record, coordinate)
    inputs = prerequisites.bundles[(coordinate.scale, coordinate.training_seed, coordinate.budget)]
    launch_nonce = cast(str, record["launch_nonce"])
    command = build_evaluator_command(
        evaluator_script=evaluator_script,
        envelope_path=shard_envelope_path(output_root, coordinate),
        manifest_path=prerequisites.context.manifest_path,
        coordinate=coordinate,
        inputs=inputs,
        launch_nonce=launch_nonce,
        gpu_lease_binding=gpu_lease_binding,
    )
    if verify_bundle:
        envelope_path = shard_envelope_path(output_root, coordinate)
        loaded = load_and_validate_shard_bundle(
            envelope_path,
            coordinate=coordinate,
            inputs=inputs,
            launch_nonce=launch_nonce,
            trust_root=prerequisites.trust_root,
            gpu_lease_binding=gpu_lease_binding,
            execution_environment_projection=cast(
                Mapping[str, Any],
                prerequisites.public_binding["execution_environment_projection"],
            ),
        )
        raw_persistent = record.get("persistent_session_execution")
        _require(
            isinstance(raw_persistent, Mapping),
            "Matrix record lacks persistent-session execution evidence.",
        )
        persistent_execution = _validate_persistent_execution_payload(
            cast(Mapping[str, Any], raw_persistent),
            coordinate=coordinate,
            envelope_path=envelope_path,
            launch_nonce=launch_nonce,
            trust_root=prerequisites.trust_root,
        )
        persistent_result = persistent_execution.get("work_result")
        if persistent_result is not None:
            _require(
                isinstance(persistent_result, Mapping)
                and persistent_result.get("envelope_binding")
                == _file_binding(envelope_path, payload=loaded),
                "Persistent child envelope binding differs from the parent-opened envelope.",
            )
        expected = _run_record(
            loaded,
            coordinate=coordinate,
            envelope_path=envelope_path,
            inputs=inputs,
            launch_nonce=launch_nonce,
            command=command,
            persistent_execution=persistent_execution,
        )
        _require(record == expected, f"Controller matrix record drifted: {coordinate.key}.")
    decision = record.get("integrity_decision")
    _require(
        decision in {"INTEGRITY-PASS", "INTEGRITY-FAIL"},
        "Matrix record integrity decision is invalid.",
    )
    return dict(record)


def validate_matrix_summary(
    payload: Mapping[str, Any],
    *,
    output_root: Path,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    verify_bundles: bool = True,
    expected_worker_count: int | None = None,
    expected_gpu_worker_leases: Mapping[int, Mapping[str, Any]] | None = None,
    ready_only_preflight_gpu_lease_binding: Mapping[str, Any] | None = None,
    allow_stale_session_ledger_watermark: bool = False,
) -> list[dict[str, Any]]:
    _verify_attested_payload(payload, trust_root=prerequisites.trust_root)
    paused_infrastructure = payload.get("status") == "paused_infrastructure"
    draining_infrastructure = payload.get("status") == "draining_infrastructure"
    infrastructure_blocked = paused_infrastructure or draining_infrastructure
    expected_schema = (
        _PAUSED_MATRIX_FIELDS
        if paused_infrastructure
        else _DRAINING_MATRIX_FIELDS
        if draining_infrastructure
        else _MATRIX_FIELDS
    )
    _require(set(payload) == expected_schema, "Controller matrix top-level schema drifted.")
    _require(payload.get("schema_version") == SCHEMA_VERSION, "Controller matrix schema drifted.")
    _require(payload.get("experiment_id") == EXPERIMENT_ID, "Wrong controller matrix ID.")
    _require(payload.get("artifact_type") == ARTIFACT_TYPE, "Controller matrix type drifted.")
    _require(payload.get("source") == prerequisites.context.source, "Matrix source drifted.")
    _require(
        payload.get("manifest") == prerequisites.context.manifest_binding,
        "Matrix manifest binding drifted.",
    )
    _require(
        payload.get("attestation_contract")
        == prerequisites.context.manifest_binding["attestation"],
        "Matrix attestation contract drifted.",
    )
    _require(
        payload.get("prerequisites") == dict(prerequisites.public_binding),
        "Matrix prerequisite binding drifted.",
    )
    _require(
        payload.get("canonical_evaluator") == dict(evaluator_binding),
        "Matrix evaluator snapshot drifted.",
    )
    _require(
        payload.get("matrix_lock") == dict(matrix_lock_binding),
        "Matrix lock binding drifted.",
    )
    worker_count = payload.get("worker_count")
    _require(
        type(worker_count) is int
        and worker_count > 0
        and payload.get("execution_mode")
        == ("single-worker" if worker_count == 1 else "distributed-workers")
        and (expected_worker_count is None or worker_count == expected_worker_count),
        "Matrix worker execution contract drifted.",
    )
    raw_gpu_registry = payload.get("gpu_worker_leases")
    _require(isinstance(raw_gpu_registry, list), "Matrix GPU lease registry is invalid.")
    gpu_registry_list = cast(list[Mapping[str, Any]], raw_gpu_registry)
    _require(
        all(
            isinstance(item, Mapping) and type(item.get("worker_index")) is int
            for item in gpu_registry_list
        ),
        "Matrix GPU lease registry entry is invalid.",
    )
    observed_gpu_bindings = {
        cast(int, item["worker_index"]): {
            key: value for key, value in item.items() if key != "worker_index"
        }
        for item in gpu_registry_list
    }
    _require(
        gpu_registry_list
        == _gpu_registry_payload(observed_gpu_bindings, worker_count=cast(int, worker_count))
        and (
            expected_gpu_worker_leases is None
            or gpu_registry_list
            == _gpu_registry_payload(
                expected_gpu_worker_leases, worker_count=cast(int, worker_count)
            )
        ),
        "Matrix GPU worker-lease registry drifted.",
    )
    frozen_projection = prerequisites.public_binding.get("execution_environment_projection")
    _require(
        isinstance(frozen_projection, Mapping)
        and isinstance(frozen_projection.get("selected_device_class"), Mapping)
        and payload.get("selected_device_class") == frozen_projection.get("selected_device_class")
        and payload.get("gpu_device_identity_registry")
        == _gpu_device_identity_registry(
            observed_gpu_bindings, worker_count=cast(int, worker_count)
        ),
        "Matrix selected-device class or physical-identity registry drifted.",
    )
    raw_worker_registry = payload.get("worker_ledger_registry")
    _require(isinstance(raw_worker_registry, list), "Matrix worker-ledger registry is invalid.")
    replayed_worker_ledgers: dict[int, list[dict[str, Any]]] = {}
    replayed_prefix: list[dict[str, Any]] = []
    replayed_merged: dict[int, dict[str, Any]] = {}
    if cast(int, worker_count) == 1:
        _require(
            payload.get("worker_ledger_assignment_rule") is None
            and payload.get("worker_ledger_root") is None
            and raw_worker_registry == []
            and not _worker_ledger_root(output_root).exists(),
            "Single-worker matrix worker-ledger registry must be exact empty.",
        )
    else:
        expected_root_binding = _worker_ledger_root_binding(
            output_root, worker_count=cast(int, worker_count)
        )
        _require(
            payload.get("worker_ledger_assignment_rule") == WORKER_ASSIGNMENT_RULE
            and payload.get("worker_ledger_root") == expected_root_binding,
            "Distributed worker-ledger assignment or root binding drifted.",
        )
        replayed_worker_ledgers, replayed_gpu_bindings = _load_worker_ledgers(
            output_root=output_root,
            worker_count=cast(int, worker_count),
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            verify_bundles=verify_bundles,
        )
        expected_worker_registry = _worker_ledger_registry(
            output_root,
            worker_count=cast(int, worker_count),
            completed_by_worker={
                index: len(worker_records)
                for index, worker_records in replayed_worker_ledgers.items()
            },
        )
        _require(
            raw_worker_registry == expected_worker_registry
            and observed_gpu_bindings == replayed_gpu_bindings,
            "Public matrix worker-ledger registry or GPU provenance drifted.",
        )
        replayed_prefix, replayed_merged = _merge_worker_records(
            replayed_worker_ledgers, worker_count=cast(int, worker_count)
        )
    _require(
        payload.get("coordinate_count") == EXPECTED_SHARDS
        and payload.get("coordinate_digest") == coordinate_digest()
        and payload.get("coordinate_order")
        == "scale,training_seed,budget,family,context,replicate",
        "Matrix coordinate inventory drifted.",
    )
    _require(
        payload.get("examples_per_shard") == EXAMPLES_PER_SHARD
        and tuple(payload.get("arm_names", ())) == ARM_NAMES
        and payload.get("expected_outcome_rows") == EXPECTED_OUTCOME_ROWS,
        "Matrix shard/arm cardinality drifted.",
    )
    _require(
        payload.get("outcome_dependent_early_stopping") is False
        and payload.get("outcome_selection_performed") is False
        and payload.get("quality_outcomes_aggregated") is False
        and payload.get("outcome_policy") == OUTCOME_POLICY,
        "Matrix outcome-independence boundary drifted.",
    )
    _require(
        payload.get("cell_claim_semantics") == CELL_CLAIM_SEMANTICS
        and payload.get("crash_recovery_boundary") == CRASH_RECOVERY_BOUNDARY,
        "Matrix claim or crash-recovery contract drifted.",
    )
    records = payload.get("records")
    _require(isinstance(records, list), "Controller matrix records are invalid.")
    records = cast(list[Mapping[str, Any]], records)
    _require(len(records) <= EXPECTED_SHARDS, "Controller matrix contains extra records.")
    globally_committed_shards = payload.get("globally_committed_shards")
    _require(
        type(globally_committed_shards) is int,
        "Globally committed shard count is invalid.",
    )
    global_count = cast(int, globally_committed_shards)
    _require(
        payload.get("completed_shards") == global_count
        and payload.get("canonical_prefix_shards") == len(records)
        and len(records) <= global_count <= EXPECTED_SHARDS
        and (cast(int, worker_count) > 1 or global_count == len(records)),
        "Canonical-prefix or globally committed shard count drifted.",
    )
    result: list[dict[str, Any]] = []
    pass_count = 0
    fail_count = 0
    canonical = _canonical_evaluator(evaluator_script)
    for record, coordinate in zip(
        records, coordinates()[: len(records)], strict=True
    ):
        _require(isinstance(record, Mapping), "Controller matrix record is invalid.")
        validated_record = _validate_record_against_coordinate(
            record,
            coordinate=coordinate,
            output_root=output_root,
            prerequisites=prerequisites,
            evaluator_script=canonical,
            gpu_lease_binding=observed_gpu_bindings[
                0
                if cast(int, worker_count) == 1
                else cast(
                    int,
                    _coordinate_worker_index(
                        coordinate, worker_count=cast(int, worker_count)
                    ),
                )
            ],
            verify_bundle=verify_bundles,
        )
        decision = validated_record["integrity_decision"]
        pass_count += decision == "INTEGRITY-PASS"
        fail_count += decision == "INTEGRITY-FAIL"
        result.append(validated_record)
    if cast(int, worker_count) > 1:
        _require(
            result == replayed_prefix and global_count == len(replayed_merged),
            "Public matrix prefix/global counts drifted from bound worker ledgers.",
        )
    full_coordinate_set = len(records) == EXPECTED_SHARDS
    awaiting_session_terminal = (
        payload.get("status") == "awaiting_session_terminal"
    )
    terminal = full_coordinate_set and not awaiting_session_terminal
    raw_launcher = payload.get("sealed_launcher")
    raw_launch_routing = payload.get("launch_routing")
    raw_ready_only_preflight = payload.get("ready_only_preflight")
    raw_session_ledger = payload.get("persistent_session_ledger")
    _require(
        isinstance(raw_launcher, Mapping)
        and isinstance(raw_launch_routing, Mapping)
        and isinstance(raw_ready_only_preflight, Mapping)
        and isinstance(raw_session_ledger, Mapping),
        "Matrix sealed launcher, ready-only preflight, or persistent-session ledger binding is missing.",
    )
    _validate_launcher_binding_snapshot(cast(Mapping[str, Any], raw_launcher))
    _validate_launch_routing_snapshot(
        cast(Mapping[str, Any], raw_launch_routing),
        expected_selector="matrix",
        source_provenance=cast(
            Mapping[str, Any],
            cast(Mapping[str, Any], raw_launcher)["source_provenance"],
        ),
    )
    session_projection = _validate_persistent_session_ledger_snapshot(
        cast(Mapping[str, Any], raw_session_ledger),
        output_root=output_root,
        trust_root=prerequisites.trust_root,
        require_current_exact=(
            terminal and not allow_stale_session_ledger_watermark
        ),
    )
    ready_only_preflight_gpu_binding = observed_gpu_bindings.get(0)
    if ready_only_preflight_gpu_binding is None:
        _require(
            ready_only_preflight_gpu_lease_binding is not None,
            "Matrix lacks both worker-0 and live supervisor GPU authority for preflight.",
        )
        ready_only_preflight_gpu_binding = _validate_gpu_lease_binding(
            cast(Mapping[str, Any], ready_only_preflight_gpu_lease_binding)
        )
    elif ready_only_preflight_gpu_lease_binding is not None:
        _require(
            ready_only_preflight_gpu_binding
            == _validate_gpu_lease_binding(ready_only_preflight_gpu_lease_binding),
            "Worker-0 and live supervisor GPU authority disagree for preflight.",
        )
    _validate_ready_only_preflight_snapshot(
        cast(Mapping[str, Any], raw_ready_only_preflight),
        session_projection=session_projection,
        output_root=output_root,
        prerequisites=prerequisites,
        evaluator_binding=evaluator_binding,
        gpu_lease_binding=ready_only_preflight_gpu_binding,
    )
    _crosscheck_matrix_records_with_session_ledger(
        records,
        session_projection,
        require_terminal_sessions=(
            terminal and not allow_stale_session_ledger_watermark
        ),
    )
    referenced_session_nonces = {
        cast(str, cast(Mapping[str, Any], record["persistent_session_execution"])["plan"]["session_nonce"])
        for record in records
    }
    projected_launch_only_nonces = {
        cast(str, row["session_nonce"])
        for row in cast(list[Mapping[str, Any]], session_projection["sessions"])
        if row["status"] == "launch_only"
    }
    _require(
        awaiting_session_terminal
        is (
            full_coordinate_set
            and bool(
                referenced_session_nonces & projected_launch_only_nonces
            )
        ),
        "Matrix awaiting-session-terminal state drifted from its durable projection.",
    )
    _require(
        (worker_count == 1 and tuple(observed_gpu_bindings) == (0,))
        or (
            cast(int, worker_count) > 1
            and (not terminal or len(observed_gpu_bindings) == worker_count)
        ),
        "Matrix GPU worker-lease registry is incomplete for its status.",
    )
    if infrastructure_blocked:
        _require(not terminal, "Terminal controller matrix may not be infrastructure-blocked.")
    else:
        _require(
            payload.get("status")
            == (
                "terminal"
                if terminal
                else "awaiting_session_terminal"
                if awaiting_session_terminal
                else "in_progress"
            ),
            "Controller matrix status drifted.",
        )
    expected_integrity: str | None = None
    if terminal:
        expected_integrity = "INTEGRITY-PASS" if fail_count == 0 else "INTEGRITY-FAIL"
    if infrastructure_blocked:
        reason_field = "infrastructure_pause" if paused_infrastructure else "infrastructure_drain"
        pause = payload.get(reason_field)
        reason_schema = (
            _INFRASTRUCTURE_PAUSE_FIELDS if paused_infrastructure else _INFRASTRUCTURE_DRAIN_FIELDS
        )
        _require(
            isinstance(pause, Mapping) and set(pause) == reason_schema,
            "Infrastructure pause/drain reason schema drifted.",
        )
        pause_map = cast(Mapping[str, Any], pause)
        pause_worker_index = pause_map.get("pause_worker_index")
        _require(
            pause_map.get("schema_version") == 1
            and pause_map.get("signal_type") == "infrastructure-storage-headroom-pause-v1"
            and pause_map.get("retryable") is True
            and pause_map.get("method") == NEXT_LAUNCH_HEADROOM_METHOD
            and pause_map.get("outcome_independent") is True
            and (
                pause_map.get("sufficient") is False
                if paused_infrastructure
                else type(pause_map.get("sufficient")) is bool
            )
            and pause_map.get("limitations") == NEXT_LAUNCH_HEADROOM_LIMITATIONS
            and pause_map.get("resume_rule") == INFRASTRUCTURE_PAUSE_RESUME_RULE
            and type(pause_map.get("filesystem_available_bytes")) is int
            and type(pause_map.get("required_headroom_bytes")) is int
            and pause_map.get("sufficient")
            is (
                cast(int, pause_map["filesystem_available_bytes"])
                >= cast(int, pause_map["required_headroom_bytes"])
            )
            and pause_map.get("completed_record_count") == global_count
            and pause_map.get("canonical_prefix_shards") == len(records)
            and pause_map.get("globally_committed_shards") == global_count
            and pause_map.get("matrix_records_digest") == contract.json_digest(records)
            and pause_map.get("worker_ledger_registry_digest")
            == contract.json_digest(payload["worker_ledger_registry"])
            and pause_map.get("pause_worker_count") == worker_count
            and type(pause_worker_index) is int
            and 0 <= pause_worker_index < cast(int, worker_count),
            "Infrastructure pause reason or bound progress drifted.",
        )
        if draining_infrastructure:
            raw_active_claims = pause_map.get("active_claim_coordinate_indices")
            live_claim_indices: list[int] = []
            for claim_index, claim_coordinate in enumerate(coordinates()):
                claim_path = shard_output_dir(output_root, claim_coordinate) / CELL_CLAIM_NAME
                if claim_path.exists():
                    _validated_live_claim(
                        claim_path,
                        coordinate=claim_coordinate,
                        canonical_index=claim_index,
                        worker_count=cast(int, worker_count),
                    )
                    live_claim_indices.append(claim_index)
            _require(
                cast(int, worker_count) > 1
                and pause_map.get("drain_rule") == INFRASTRUCTURE_DRAIN_RULE
                and isinstance(raw_active_claims, list)
                and pause_map.get("active_claim_count") == len(raw_active_claims)
                and raw_active_claims == sorted(set(raw_active_claims))
                and raw_active_claims == live_claim_indices
                and all(
                    type(index) is int
                    and 0 <= index < EXPECTED_SHARDS
                    and index not in replayed_merged
                    for index in raw_active_claims
                ),
                "Infrastructure drain active-claim binding drifted.",
            )
        else:
            _require(
                not any(
                    (shard_output_dir(output_root, claim_coordinate) / CELL_CLAIM_NAME).exists()
                    for claim_coordinate in coordinates()
                ),
                "Infrastructure pause may not coexist with a live distributed claim.",
            )
        if cast(int, worker_count) == 1:
            expected_pause_coordinate = coordinates()[len(records)]
        else:
            pause_worker_records = replayed_worker_ledgers.get(cast(int, pause_worker_index))
            _require(
                pause_worker_records is not None,
                "Infrastructure pause worker has no bound worker ledger.",
            )
            pause_assignment = _assigned_coordinates(
                worker_index=cast(int, pause_worker_index),
                worker_count=cast(int, worker_count),
            )
            pause_record_count = len(cast(list[dict[str, Any]], pause_worker_records))
            _require(
                pause_record_count < len(pause_assignment),
                "Infrastructure pause worker has no remaining coordinate.",
            )
            expected_pause_coordinate = pause_assignment[pause_record_count]
        pause_storage_records = (
            records
            if cast(int, worker_count) == 1
            else [replayed_merged[index] for index in sorted(replayed_merged)]
        )
        expected_signal = _headroom_signal_payload(
            records=pause_storage_records,
            coordinate=expected_pause_coordinate,
            filesystem_available_bytes=cast(int, pause_map["filesystem_available_bytes"]),
        )
        _require(
            {field: pause_map[field] for field in _HEADROOM_SIGNAL_FIELDS} == expected_signal,
            "Infrastructure pause reason does not exactly replay from bound evidence.",
        )
        resume_body = dict(payload)
        resume_body.pop("payload_sha256")
        resume_body.pop("attestation")
        resume_body.pop(reason_field)
        resume_body["status"] = "in_progress"
        resume_body["integrity_status"] = None
        resume_body["integrity_pass_shards"] = pass_count
        resume_body["integrity_fail_shards"] = fail_count
        resume_payload = _digest_bound_payload(resume_body)
        _require(
            pause_map.get("resume_matrix_payload_sha256") == resume_payload["payload_sha256"],
            "Infrastructure pause resume-payload binding drifted.",
        )
    else:
        _require(
            payload.get("integrity_status") == expected_integrity,
            "Matrix integrity status drifted.",
        )
        _require(
            payload.get("integrity_pass_shards") == pass_count
            and payload.get("integrity_fail_shards") == fail_count,
            "Matrix integrity counts drifted.",
        )
    storage = payload.get("storage")
    _require(
        payload.get("storage_aggregation_scope") == "all-globally-committed-records-v1"
        and isinstance(storage, Mapping),
        "Matrix storage rollup or aggregation scope drifted.",
    )
    storage_map = cast(Mapping[str, Any], storage)
    if cast(int, worker_count) > 1:
        replayed_storage_records = [replayed_merged[index] for index in sorted(replayed_merged)]
        replayed_remaining = [
            coordinate
            for index, coordinate in enumerate(coordinates())
            if index not in replayed_merged
        ]
        _require(
            dict(storage_map)
            == _storage_rollup(
                replayed_storage_records,
                remaining_coordinates=replayed_remaining,
            ),
            "Sparse matrix storage drifted from bound worker ledgers.",
        )
    elif global_count == len(records):
        _require(
            dict(storage_map) == _storage_rollup(records),
            "Matrix storage rollup drifted from its completed records.",
        )
    return result


def _validate_worker_identity(*, worker_index: int, worker_count: int) -> None:
    _require(
        type(worker_count) is int and 2 <= worker_count <= EXPECTED_SHARDS,
        "Distributed worker count must be between 2 and the frozen shard count.",
    )
    _require(
        type(worker_index) is int and 0 <= worker_index < worker_count,
        "Distributed worker index is outside its worker count.",
    )


@functools.cache
def _mixed_device_coordinates(site: str) -> tuple[ShardCoordinate, ...]:
    """Return one quality-blind, factor-balanced device block."""

    _require(
        site in contract.V1_3_5_MIXED_DEVICE_SITES,
        "Mixed-device assignment site is not registered.",
    )
    selected: list[ShardCoordinate] = []
    for coordinate in coordinates():
        offset = (
            FROZEN_SCALES.index(coordinate.scale)
            + FROZEN_TRAINING_SEEDS.index(coordinate.training_seed)
            + 5 * FROZEN_BUDGETS.index(coordinate.budget)
            + FROZEN_FAMILIES.index(coordinate.family)
            + 2 * FROZEN_CONTEXTS.index(coordinate.context)
        ) % len(FROZEN_REPLICATES)
        replicate_index = FROZEN_REPLICATES.index(coordinate.replicate)
        gb10 = (replicate_index - offset) % len(FROZEN_REPLICATES) < 4
        if (site == "gb10") == gb10:
            selected.append(coordinate)
    expected = contract.V1_3_5_MIXED_SITE_COORDINATE_COUNTS[site]
    _require(
        len(selected) == expected,
        "Mixed-device site cardinality drifted.",
    )
    return tuple(selected)


@functools.cache
def _mixed_device_worker_map(site: str, worker_count: int) -> Mapping[str, int]:
    _validate_worker_identity(worker_index=0, worker_count=worker_count)
    return {
        coordinate.key: index % worker_count
        for index, coordinate in enumerate(_mixed_device_coordinates(site))
    }


def _coordinate_worker_index(
    coordinate: ShardCoordinate, *, worker_count: int
) -> int | None:
    if worker_count == 1:
        return 0
    return _mixed_device_worker_map(
        contract.V1_3_5_MIXED_DEVICE_SITE, worker_count
    ).get(coordinate.key)


def _assigned_coordinates(*, worker_index: int, worker_count: int) -> tuple[ShardCoordinate, ...]:
    _validate_worker_identity(worker_index=worker_index, worker_count=worker_count)
    site_coordinates = _mixed_device_coordinates(contract.V1_3_5_MIXED_DEVICE_SITE)
    return tuple(site_coordinates[worker_index::worker_count])

def _worker_payload(
    records: Sequence[Mapping[str, Any]],
    *,
    worker_index: int,
    worker_count: int,
    prerequisites: FrozenPrerequisites,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    gpu_lease_binding: Mapping[str, Any],
) -> dict[str, Any]:
    assigned = _assigned_coordinates(worker_index=worker_index, worker_count=worker_count)
    _require(len(records) <= len(assigned), "Worker ledger contains extra shard records.")
    pass_count = sum(record.get("integrity_decision") == "INTEGRITY-PASS" for record in records)
    fail_count = sum(record.get("integrity_decision") == "INTEGRITY-FAIL" for record in records)
    payload = {
        "schema_version": SCHEMA_VERSION,
        "experiment_id": WORKER_EXPERIMENT_ID,
        "artifact_type": WORKER_ARTIFACT_TYPE,
        "status": "terminal" if len(records) == len(assigned) else "in_progress",
        "source": prerequisites.context.source,
        "manifest": prerequisites.context.manifest_binding,
        "attestation_contract": prerequisites.context.manifest_binding["attestation"],
        "prerequisites": dict(prerequisites.public_binding),
        "canonical_evaluator": dict(evaluator_binding),
        "matrix_lock": dict(matrix_lock_binding),
        "gpu_lease": _validate_gpu_lease_binding(gpu_lease_binding, require_live=True),
        "worker_index": worker_index,
        "worker_count": worker_count,
        "assignment_rule": WORKER_ASSIGNMENT_RULE,
        "global_coordinate_count": EXPECTED_SHARDS,
        "global_coordinate_digest": coordinate_digest(),
        "assigned_coordinate_count": len(assigned),
        "assigned_coordinate_digest": contract.json_digest(
            [coordinate.payload for coordinate in assigned]
        ),
        "completed_shards": len(records),
        "integrity_pass_shards": pass_count,
        "integrity_fail_shards": fail_count,
        "outcome_dependent_early_stopping": False,
        "outcome_selection_performed": False,
        "quality_outcomes_aggregated": False,
        "records": list(records),
    }
    return _attested_worker_payload(payload, trust_root=prerequisites.trust_root)


def _validate_worker_ledger(
    payload: Mapping[str, Any],
    *,
    worker_index: int,
    worker_count: int,
    output_root: Path,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    verify_bundles: bool,
    expected_gpu_lease_binding: Mapping[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    _validate_worker_identity(worker_index=worker_index, worker_count=worker_count)
    _verify_worker_payload(payload, trust_root=prerequisites.trust_root)
    _require(set(payload) == _WORKER_LEDGER_FIELDS, "Worker ledger schema drifted.")
    _require(
        payload.get("schema_version") == SCHEMA_VERSION
        and payload.get("experiment_id") == WORKER_EXPERIMENT_ID
        and payload.get("artifact_type") == WORKER_ARTIFACT_TYPE,
        "Worker ledger identity drifted.",
    )
    _require(
        payload.get("source") == prerequisites.context.source
        and payload.get("manifest") == prerequisites.context.manifest_binding
        and payload.get("attestation_contract")
        == prerequisites.context.manifest_binding["attestation"]
        and payload.get("prerequisites") == dict(prerequisites.public_binding)
        and payload.get("canonical_evaluator") == dict(evaluator_binding)
        and payload.get("matrix_lock") == dict(matrix_lock_binding),
        "Worker ledger prerequisite/evaluator binding drifted.",
    )
    raw_gpu_lease = payload.get("gpu_lease")
    _require(isinstance(raw_gpu_lease, Mapping), "Worker GPU lease binding is missing.")
    gpu_lease = _validate_gpu_lease_binding(cast(Mapping[str, Any], raw_gpu_lease))
    expected_gpu_lease = (
        None
        if expected_gpu_lease_binding is None
        else _validate_gpu_lease_binding(expected_gpu_lease_binding, require_live=True)
    )
    _require(
        expected_gpu_lease is None or gpu_lease == expected_gpu_lease,
        "Worker GPU lease path or persistent identity drifted on resume.",
    )
    assigned = _assigned_coordinates(worker_index=worker_index, worker_count=worker_count)
    _require(
        payload.get("worker_index") == worker_index
        and payload.get("worker_count") == worker_count
        and payload.get("assignment_rule") == WORKER_ASSIGNMENT_RULE
        and payload.get("global_coordinate_count") == EXPECTED_SHARDS
        and payload.get("global_coordinate_digest") == coordinate_digest()
        and payload.get("assigned_coordinate_count") == len(assigned)
        and payload.get("assigned_coordinate_digest")
        == contract.json_digest([coordinate.payload for coordinate in assigned]),
        "Worker ledger assignment binding drifted.",
    )
    _require(
        payload.get("outcome_dependent_early_stopping") is False
        and payload.get("outcome_selection_performed") is False
        and payload.get("quality_outcomes_aggregated") is False,
        "Worker ledger crossed the outcome-independence boundary.",
    )
    raw_records = payload.get("records")
    _require(isinstance(raw_records, list), "Worker ledger records are invalid.")
    records = cast(list[Mapping[str, Any]], raw_records)
    _require(
        len(records) <= len(assigned) and payload.get("completed_shards") == len(records),
        "Worker ledger completed count drifted.",
    )
    canonical = _canonical_evaluator(evaluator_script)
    result: list[dict[str, Any]] = []
    pass_count = 0
    fail_count = 0
    for record, coordinate in zip(records, assigned[: len(records)], strict=True):
        _require(isinstance(record, Mapping), "Worker ledger record is invalid.")
        validated = _validate_record_against_coordinate(
            record,
            coordinate=coordinate,
            output_root=output_root,
            prerequisites=prerequisites,
            evaluator_script=canonical,
            gpu_lease_binding=gpu_lease,
            verify_bundle=verify_bundles,
        )
        pass_count += validated["integrity_decision"] == "INTEGRITY-PASS"
        fail_count += validated["integrity_decision"] == "INTEGRITY-FAIL"
        result.append(validated)
    _require(
        payload.get("status") == ("terminal" if len(records) == len(assigned) else "in_progress")
        and payload.get("integrity_pass_shards") == pass_count
        and payload.get("integrity_fail_shards") == fail_count,
        "Worker ledger status or integrity counts drifted.",
    )
    return result, gpu_lease


def _load_worker_ledgers(
    *,
    output_root: Path,
    worker_count: int,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    verify_bundles: bool,
    expected_worker_index: int | None = None,
    expected_gpu_lease_binding: Mapping[str, Any] | None = None,
) -> tuple[dict[int, list[dict[str, Any]]], dict[int, dict[str, Any]]]:
    _validate_worker_identity(worker_index=0, worker_count=worker_count)
    root = _worker_ledger_root(output_root)
    if not root.exists():
        return {}, {}
    _require(root.is_dir() and not root.is_symlink(), "Worker-ledger root is unsafe.")
    expected = {
        _worker_ledger_path(
            output_root, worker_index=worker_index, worker_count=worker_count
        ): worker_index
        for worker_index in range(worker_count)
    }
    for item in root.iterdir():
        _require(
            not item.is_symlink() and item.is_file() and _absolute(item) in expected,
            f"Worker-ledger root contains an unregistered file: {item}",
        )
    result: dict[int, list[dict[str, Any]]] = {}
    gpu_bindings: dict[int, dict[str, Any]] = {}
    for path, worker_index in expected.items():
        if not path.exists():
            continue
        records, gpu_binding = _validate_worker_ledger(
            _load_json_nofollow(path, label="controller worker ledger"),
            worker_index=worker_index,
            worker_count=worker_count,
            output_root=output_root,
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            verify_bundles=verify_bundles,
            expected_gpu_lease_binding=(
                expected_gpu_lease_binding if expected_worker_index == worker_index else None
            ),
        )
        result[worker_index] = records
        gpu_bindings[worker_index] = gpu_binding
    return result, gpu_bindings


def _merge_worker_records(
    ledgers: Mapping[int, Sequence[Mapping[str, Any]]], *, worker_count: int
) -> tuple[list[dict[str, Any]], dict[int, dict[str, Any]]]:
    coordinate_items = coordinates()
    coordinate_index = {coordinate.key: index for index, coordinate in enumerate(coordinate_items)}
    merged: dict[int, dict[str, Any]] = {}
    for worker_index, records in ledgers.items():
        _validate_worker_identity(worker_index=worker_index, worker_count=worker_count)
        for record in records:
            key = cast(str, record.get("coordinate_key"))
            _require(key in coordinate_index, "Worker ledger contains an unknown coordinate.")
            index = coordinate_index[key]
            _require(
                _coordinate_worker_index(
                    coordinate_items[index], worker_count=worker_count
                )
                == worker_index
                and index not in merged,
                "Worker ledgers overlap or violate their partition.",
            )
            merged[index] = dict(record)
    prefix: list[dict[str, Any]] = []
    for index in range(len(coordinate_items)):
        merged_record = merged.get(index)
        if merged_record is None:
            break
        prefix.append(merged_record)
    return prefix, merged


def _preflight_output_tree(
    *, output_root: Path, matrix_summary: Path, completed_shards: int
) -> None:
    root = _absolute(output_root)
    summary = _absolute(matrix_summary)
    if not root.exists():
        _require(completed_shards == 0, "Completed matrix prefix lost its output root.")
        return
    _require(root.is_dir() and not root.is_symlink(), "Controller output root is unsafe.")
    allowed: set[Path] = {summary}
    for index, coordinate in enumerate(coordinates()):
        output_dir = shard_output_dir(root, coordinate)
        cursor = output_dir
        while cursor != root:
            allowed.add(cursor)
            cursor = cursor.parent
        bundle = canonical_bundle_paths(root, coordinate)
        if index < completed_shards:
            allowed.update(bundle.values())
            _require(
                all(path.is_file() and not path.is_symlink() for path in bundle.values()),
                f"Completed evaluator bundle is missing or unsafe: {coordinate.key}.",
            )
            _require(
                not (output_dir / CELL_CLAIM_NAME).exists(),
                f"Completed evaluator bundle retained a claim: {coordinate.key}.",
            )
        else:
            _require(
                not any(path.exists() for path in bundle.values())
                and not (output_dir / CELL_CLAIM_NAME).exists(),
                f"Orphan or partial evaluator bundle blocks resume: {coordinate.key}.",
            )
    for item in root.rglob("*"):
        _require(not item.is_symlink(), f"Controller output tree contains a symlink: {item}")
        _require(
            _absolute(item) in allowed,
            f"Controller output tree contains an unregistered orphan: {item}",
        )


def _validated_live_claim(
    claim_path: Path,
    *,
    coordinate: ShardCoordinate,
    canonical_index: int,
    worker_count: int,
) -> dict[str, Any]:
    metadata = os.stat(claim_path, follow_symlinks=False)
    _require(
        stat.S_ISREG(metadata.st_mode)
        and metadata.st_uid == os.getuid()
        and metadata.st_nlink == 1
        and stat.S_IMODE(metadata.st_mode) == 0o600,
        f"Distributed cell claim metadata is unsafe: {coordinate.key}.",
    )
    payload = _load_json_nofollow(claim_path, label="distributed cell claim")
    _require(
        set(payload)
        == {
            "schema_version",
            "semantics",
            "coordinate",
            "launch_nonce",
            "pid",
            "process_start_ticks",
            "worker_index",
            "worker_count",
            "created_time_ns",
        },
        f"Distributed cell claim schema drifted: {coordinate.key}.",
    )
    worker_index = _coordinate_worker_index(coordinate, worker_count=worker_count)
    _require(worker_index is not None, "Claim coordinate is outside this device block.")
    pid = payload.get("pid")
    start_ticks = payload.get("process_start_ticks")
    _require(
        payload.get("schema_version") == 1
        and payload.get("semantics") == CELL_CLAIM_SEMANTICS
        and payload.get("coordinate") == coordinate.payload
        and contract.is_sha256(payload.get("launch_nonce"))
        and type(pid) is int
        and pid > 0
        and type(start_ticks) is int
        and start_ticks > 0
        and payload.get("worker_index") == worker_index
        and payload.get("worker_count") == worker_count
        and type(payload.get("created_time_ns")) is int
        and cast(int, payload["created_time_ns"]) > 0,
        f"Distributed cell claim binding drifted: {coordinate.key}.",
    )
    try:
        os.kill(cast(int, pid), 0)
    except (OSError, ProcessLookupError) as error:
        raise ValueError(
            f"Stale distributed cell claim blocks resume: {coordinate.key}."
        ) from error
    _require(
        _process_start_ticks(cast(int, pid)) == start_ticks,
        f"Reused PID in distributed cell claim blocks resume: {coordinate.key}.",
    )
    return payload


def _live_distributed_claims(*, output_root: Path, worker_count: int) -> dict[int, dict[str, Any]]:
    active: dict[int, dict[str, Any]] = {}
    for index, coordinate in enumerate(coordinates()):
        claim_path = shard_output_dir(output_root, coordinate) / CELL_CLAIM_NAME
        if claim_path.exists():
            active[index] = _validated_live_claim(
                claim_path,
                coordinate=coordinate,
                canonical_index=index,
                worker_count=worker_count,
            )
    return active


def _is_evaluator_temporary(path: Path, bundle_paths: Mapping[str, Path]) -> bool:
    return any(
        path.name.startswith(f".{member.name}.") and path.name.endswith(".tmp")
        for member in bundle_paths.values()
    )


def _preflight_distributed_output_tree(
    *,
    output_root: Path,
    matrix_summary: Path,
    merged_records: Mapping[int, Mapping[str, Any]],
    worker_count: int,
) -> dict[int, dict[str, Any]]:
    root = _absolute(output_root)
    summary = _absolute(matrix_summary)
    active_claims: dict[int, dict[str, Any]] = {}
    if not root.exists():
        _require(not merged_records, "Distributed ledgers lost their controller output root.")
        return active_claims
    _require(root.is_dir() and not root.is_symlink(), "Controller output root is unsafe.")
    allowed: set[Path] = {summary}
    concurrent_bundle_members: set[Path] = set()
    concurrent_temporary_bundles: dict[Path, Mapping[str, Path]] = {}
    for index, coordinate in enumerate(coordinates()):
        output_dir = shard_output_dir(root, coordinate)
        cursor = output_dir
        while cursor != root:
            allowed.add(cursor)
            cursor = cursor.parent
        bundle = canonical_bundle_paths(root, coordinate)
        claim_path = output_dir / CELL_CLAIM_NAME
        record = merged_records.get(index)
        if record is not None:
            allowed.update(bundle.values())
            _require(
                all(path.is_file() and not path.is_symlink() for path in bundle.values()),
                f"Completed distributed evaluator bundle is missing: {coordinate.key}.",
            )
            _require(
                not claim_path.exists(),
                f"Completed distributed evaluator bundle retained a claim: {coordinate.key}.",
            )
            continue
        if claim_path.exists():
            active_claims[index] = _validated_live_claim(
                claim_path,
                coordinate=coordinate,
                canonical_index=index,
                worker_count=worker_count,
            )
            allowed.add(claim_path)
            allowed.update(bundle.values())
            concurrent_bundle_members.update(bundle.values())
            concurrent_temporary_bundles[output_dir] = bundle
            for path in bundle.values():
                if path.exists():
                    _require(
                        path.is_file() and not path.is_symlink(),
                        f"Active distributed bundle member is unsafe: {coordinate.key}.",
                    )
                    allowed.add(path)
            if output_dir.exists():
                for path in output_dir.iterdir():
                    if _absolute(path) in allowed:
                        continue
                    _require(
                        path.is_file()
                        and not path.is_symlink()
                        and _is_evaluator_temporary(path, bundle),
                        f"Active distributed cell contains an unknown file: {path}",
                    )
                    allowed.add(path)
        else:
            _require(
                not any(path.exists() for path in bundle.values()),
                f"Orphan distributed evaluator bundle blocks resume: {coordinate.key}.",
            )
            if output_dir.exists():
                _require(
                    not any(output_dir.iterdir()),
                    f"Unclaimed distributed cell contains orphan evidence: {coordinate.key}.",
                )
    for item in root.rglob("*"):
        if not os.path.lexists(item):
            continue
        _require(not item.is_symlink(), f"Controller output tree contains a symlink: {item}")
        absolute = _absolute(item)
        if absolute in allowed:
            _require(
                absolute not in concurrent_bundle_members or item.is_file(),
                f"Active distributed bundle member is unsafe: {item}",
            )
            continue
        live_bundle = concurrent_temporary_bundles.get(item.parent)
        _require(
            live_bundle is not None and item.is_file() and _is_evaluator_temporary(item, live_bundle),
            f"Controller output tree contains an unregistered orphan: {item}",
        )
    return active_claims


def _assert_empty_bundle(output_root: Path, coordinate: ShardCoordinate) -> None:
    bundle = canonical_bundle_paths(output_root, coordinate)
    _require(
        not any(path.exists() for path in bundle.values()),
        f"Refusing pre-existing evaluator bundle: {coordinate.key}.",
    )
    output_dir = shard_output_dir(output_root, coordinate)
    if output_dir.exists():
        _require(
            not any(output_dir.iterdir()), f"Refusing non-empty shard directory: {coordinate.key}."
        )


def _distributed_layout_guard(layout: MatrixLayout, *, attestation_key_path: Path | None) -> None:
    worker_root = _exact_resolved_path(
        _worker_ledger_root(layout.output_root), label="Controller worker-ledger root"
    )
    protected = (
        layout.output_root,
        layout.matrix_summary,
        layout.lock_path,
        layout.training_output_root,
        layout.calibration_output_root,
        layout.reuse_admission_path,
        layout.preheldout_genesis_path,
    )
    _require(
        all(not _paths_overlap(worker_root, path) for path in protected),
        "Controller worker-ledger root must be disjoint from artifacts and inputs.",
    )
    if attestation_key_path is not None:
        key_path = _exact_resolved_path(attestation_key_path, label="Attestation key")
        _require(
            not _paths_overlap(worker_root, key_path),
            "Controller worker-ledger root may not contain the attestation key.",
        )


_SELECTED_DEVICE_CONTEXT_FIELDS = frozenset(
    {
        "compatible_environment_projection",
        "selected_device_class",
        "selected_device_routing_identity",
        "selected_device_logical_index",
        "device_argument",
    }
)
_DEVICE_GUARD_BINDING_FIELDS = frozenset(
    {
        "path",
        "semantics",
        "implementation_path",
        "path_derivation",
        "nonblocking",
        "persistent_inode",
        "device",
        "inode",
    }
)


def _capture_selected_device_context(scheduler_lease: GPULockLease) -> dict[str, Any]:
    scheduler_lease.assert_held()
    captured = execution_environment.capture_execution_environment()
    scheduler_lease.assert_held()
    logical_index = captured.get("current_device_index")
    _require(type(logical_index) is int and logical_index >= 0, "Selected GPU index is invalid.")
    return {
        "compatible_environment_projection": (
            execution_environment.controller_compatible_environment_projection(captured)
        ),
        "selected_device_class": execution_environment.selected_device_class(captured),
        "selected_device_routing_identity": (
            execution_environment.selected_device_routing_identity(captured)
        ),
        "selected_device_logical_index": logical_index,
        "device_argument": f"cuda:{logical_index}",
    }


def _validate_selected_device_context(
    value: Mapping[str, Any], *, prerequisites: FrozenPrerequisites
) -> dict[str, Any]:
    _require(
        set(value) == _SELECTED_DEVICE_CONTEXT_FIELDS,
        "Selected GPU device context schema drifted.",
    )
    projection = value.get("compatible_environment_projection")
    selected_class = value.get("selected_device_class")
    routing_identity = value.get("selected_device_routing_identity")
    logical_index = value.get("selected_device_logical_index")
    device_argument = value.get("device_argument")
    frozen_projection = prerequisites.public_binding.get("execution_environment_projection")
    _require(
        isinstance(projection, Mapping)
        and isinstance(selected_class, Mapping)
        and isinstance(routing_identity, Mapping)
        and isinstance(frozen_projection, Mapping)
        and dict(cast(Mapping[str, Any], projection))
        == dict(cast(Mapping[str, Any], frozen_projection))
        and dict(cast(Mapping[str, Any], selected_class))
        == cast(Mapping[str, Any], projection).get("selected_device_class"),
        "Selected GPU device class or compatible environment projection drifted.",
    )
    identity = dict(cast(Mapping[str, Any], routing_identity))
    _require(
        type(logical_index) is int
        and logical_index >= 0
        and device_argument == f"cuda:{logical_index}",
        "Selected GPU logical index or explicit device argument drifted.",
    )
    try:
        canonical_device_guard_path(identity)
    except RuntimeError as error:
        raise ValueError("Selected GPU routing identity is invalid.") from error
    return {
        "compatible_environment_projection": dict(cast(Mapping[str, Any], projection)),
        "selected_device_class": dict(cast(Mapping[str, Any], selected_class)),
        "selected_device_routing_identity": identity,
        "selected_device_logical_index": logical_index,
        "device_argument": device_argument,
    }


def _acquire_selected_device_guard(
    *, label: str, device_context: Mapping[str, Any], scheduler_lease: GPULockLease
) -> GPULockLease:
    scheduler_lease.assert_held()
    identity = cast(Mapping[str, Any], device_context["selected_device_routing_identity"])
    guard_path = canonical_device_guard_path(identity)
    if scheduler_lease.path == guard_path:
        return scheduler_lease
    guard: GPULockLease | None = None
    returned = False
    try:
        guard = acquire_device_guard(label, identity)
        scheduler_lease.assert_held()
        guard.assert_held()
        returned = True
        return guard
    finally:
        if guard is not None and not returned:
            guard.close()

def _close_gpu_lease_pair(scheduler_lease: GPULockLease, device_guard_lease: GPULockLease) -> None:
    if device_guard_lease is scheduler_lease:
        scheduler_lease.close()
        return
    failure: BaseException | None = None
    try:
        device_guard_lease.close()
    except BaseException as error:
        failure = error
    finally:
        try:
            scheduler_lease.close()
        except BaseException as error:
            if failure is None:
                failure = error
    if failure is not None:
        raise failure


def _run_same_gpu_worker_group(
    *,
    worker_count: int,
    scheduler_owner: GPULockLease,
    device_guard_owner: GPULockLease,
    run_worker: Callable[
        [int, GPULockLease, GPULockLease, threading.Event],
        Mapping[str, Any],
    ],
) -> tuple[dict[str, Any], ...]:
    """Run disjoint worker coordinators under one supervisor-owned physical lease."""

    _require(
        type(worker_count) is int and 2 <= worker_count <= 4,
        "Same-GPU worker count must be one of 2, 3, or 4.",
    )
    scheduler_owner.assert_held()
    device_guard_owner.assert_held()
    drain_event = threading.Event()
    results: list[dict[str, Any] | None] = [None] * worker_count
    failures: list[tuple[int, BaseException]] = []
    failure_lock = threading.Lock()

    def target(worker_index: int) -> None:
        scheduler = admission.borrow_gpu_lock_lease(scheduler_owner)
        guard = (
            scheduler
            if device_guard_owner is scheduler_owner
            else admission.borrow_gpu_lock_lease(device_guard_owner)
        )
        failure: BaseException | None = None
        try:
            results[worker_index] = dict(
                run_worker(worker_index, scheduler, guard, drain_event)
            )
        except BaseException as error:
            failure = error
            drain_event.set()
        finally:
            try:
                _close_gpu_lease_pair(scheduler, guard)
            except BaseException as error:
                if failure is None:
                    failure = error
            if failure is not None:
                with failure_lock:
                    failures.append((worker_index, failure))

    workers = [
        threading.Thread(
            target=target,
            args=(worker_index,),
            name=f"p2-direct-same-gpu-worker-{worker_index}-of-{worker_count}",
        )
        for worker_index in range(worker_count)
    ]
    for worker in workers:
        worker.start()
    for worker in workers:
        worker.join()

    scheduler_owner.assert_held()
    device_guard_owner.assert_held()
    _require(
        admission.active_gpu_lock_borrows(scheduler_owner) == 0
        and (
            device_guard_owner is scheduler_owner
            or admission.active_gpu_lock_borrows(device_guard_owner) == 0
        ),
        "Same-GPU supervisor retained a worker lease after join.",
    )
    if failures:
        failures.sort(key=lambda item: item[0])
        detail = ", ".join(
            f"worker {index}: {type(error).__name__}: {error}" for index, error in failures
        )
        raise RuntimeError(f"Same-GPU worker group failed after drain: {detail}") from failures[0][1]
    _require(
        all(result is not None for result in results),
        "Same-GPU worker group completed without one worker result.",
    )
    return tuple(cast(dict[str, Any], result) for result in results)


def _gpu_lease_binding(
    scheduler_lease: GPULockLease,
    *,
    device_guard_lease: GPULockLease,
    device_context: Mapping[str, Any],
) -> dict[str, Any]:
    scheduler_lease.assert_held()
    device_guard_lease.assert_held()
    path = _exact_resolved_path(scheduler_lease.path, label="GPU scheduler lease path")
    guard_path = _exact_resolved_path(
        device_guard_lease.path, label="GPU physical-device guard path"
    )
    identity = dict(cast(Mapping[str, Any], device_context["selected_device_routing_identity"]))
    _require(
        guard_path == canonical_device_guard_path(identity),
        "GPU physical-device guard path is not derived from its routing identity.",
    )
    return {
        "path": str(path),
        "semantics": GPU_LEASE_SEMANTICS,
        "implementation_path": GPU_LOCK_IMPLEMENTATION_PATH,
        "nonblocking": True,
        "persistent_inode": True,
        "device": scheduler_lease.device,
        "inode": scheduler_lease.inode,
        "selected_device_class": dict(
            cast(Mapping[str, Any], device_context["selected_device_class"])
        ),
        "selected_device_routing_identity": identity,
        "selected_device_logical_index": device_context["selected_device_logical_index"],
        "device_argument": device_context["device_argument"],
        "device_guard": {
            "path": str(guard_path),
            "semantics": DEVICE_GUARD_SEMANTICS,
            "implementation_path": GPU_LOCK_IMPLEMENTATION_PATH,
            "path_derivation": DEVICE_GUARD_PATH_DERIVATION,
            "nonblocking": True,
            "persistent_inode": True,
            "device": device_guard_lease.device,
            "inode": device_guard_lease.inode,
        },
    }


def _validate_gpu_lease_binding(
    binding: Mapping[str, Any], *, require_live: bool = False
) -> dict[str, Any]:
    _require(
        set(binding)
        == {
            "path",
            "semantics",
            "implementation_path",
            "nonblocking",
            "persistent_inode",
            "device",
            "inode",
            "selected_device_class",
            "selected_device_routing_identity",
            "selected_device_logical_index",
            "device_argument",
            "device_guard",
        },
        "GPU worker-lease binding schema drifted.",
    )
    raw_path = binding.get("path")
    _require(isinstance(raw_path, str) and bool(raw_path), "GPU lease path is invalid.")
    path = Path(cast(str, raw_path))
    _require(
        path == Path(os.path.abspath(path)),
        "GPU lease path is not exact and canonical.",
    )
    _require(
        binding.get("semantics") == GPU_LEASE_SEMANTICS
        and binding.get("implementation_path") == GPU_LOCK_IMPLEMENTATION_PATH
        and binding.get("nonblocking") is True
        and binding.get("persistent_inode") is True
        and type(binding.get("device")) is int
        and cast(int, binding["device"]) >= 0
        and type(binding.get("inode")) is int
        and cast(int, binding["inode"]) > 0,
        "GPU worker-lease contract drifted.",
    )
    selected_class = binding.get("selected_device_class")
    routing_identity = binding.get("selected_device_routing_identity")
    raw_guard = binding.get("device_guard")
    _require(
        isinstance(selected_class, Mapping)
        and set(selected_class) == execution_environment.SELECTED_DEVICE_CLASS_FIELDS
        and isinstance(selected_class.get("name"), str)
        and bool(cast(str, selected_class["name"]).strip())
        and isinstance(selected_class.get("compute_capability"), list)
        and len(cast(list[Any], selected_class["compute_capability"])) == 2
        and all(
            type(item) is int and item >= 0
            for item in cast(list[Any], selected_class["compute_capability"])
        )
        and type(selected_class.get("total_memory_bytes")) is int
        and cast(int, selected_class["total_memory_bytes"]) > 0
        and isinstance(routing_identity, Mapping)
        and type(binding.get("selected_device_logical_index")) is int
        and cast(int, binding["selected_device_logical_index"]) >= 0
        and binding.get("device_argument") == f"cuda:{binding.get('selected_device_logical_index')}"
        and isinstance(raw_guard, Mapping)
        and set(raw_guard) == _DEVICE_GUARD_BINDING_FIELDS,
        "GPU selected-device or physical guard binding drifted.",
    )
    identity = dict(cast(Mapping[str, Any], routing_identity))
    try:
        expected_guard_path = canonical_device_guard_path(identity)
    except RuntimeError as error:
        raise ValueError("GPU selected-device routing identity drifted.") from error
    guard = cast(Mapping[str, Any], raw_guard)
    raw_guard_path = guard.get("path")
    _require(
        isinstance(raw_guard_path, str)
        and Path(raw_guard_path) == expected_guard_path
        and guard.get("semantics") == DEVICE_GUARD_SEMANTICS
        and guard.get("implementation_path") == GPU_LOCK_IMPLEMENTATION_PATH
        and guard.get("path_derivation") == DEVICE_GUARD_PATH_DERIVATION
        and guard.get("nonblocking") is True
        and guard.get("persistent_inode") is True
        and type(guard.get("device")) is int
        and cast(int, guard["device"]) >= 0
        and type(guard.get("inode")) is int
        and cast(int, guard["inode"]) > 0,
        "GPU physical-device guard contract drifted.",
    )
    if require_live:
        for live_path, device, inode, label in (
            (path, binding["device"], binding["inode"], "scheduler lease"),
            (expected_guard_path, guard["device"], guard["inode"], "physical-device guard"),
        ):
            try:
                metadata = os.stat(live_path, follow_symlinks=False)
            except OSError as error:
                raise ValueError(f"GPU {label} path is inaccessible.") from error
            _require(
                stat.S_ISREG(metadata.st_mode)
                and metadata.st_uid == os.getuid()
                and metadata.st_nlink == 1
                and stat.S_IMODE(metadata.st_mode) == GPU_LOCK_MODE,
                f"GPU {label} path metadata drifted.",
            )
            _require(
                (metadata.st_dev, metadata.st_ino) == (cast(int, device), cast(int, inode)),
                f"GPU {label} persistent identity drifted.",
            )
    return {
        **dict(binding),
        "selected_device_class": dict(cast(Mapping[str, Any], selected_class)),
        "selected_device_routing_identity": identity,
        "device_guard": dict(guard),
    }


def _gpu_device_identity_registry(
    gpu_bindings: Mapping[int, Mapping[str, Any]], *, worker_count: int
) -> list[dict[str, Any]]:
    validated = {
        index: _validate_gpu_lease_binding(binding) for index, binding in gpu_bindings.items()
    }
    by_identity: dict[tuple[str, str], dict[str, Any]] = {}
    scheduler_to_identity: dict[tuple[str, int, int], tuple[str, str]] = {}
    for worker_index in sorted(validated):
        _require(
            type(worker_index) is int and 0 <= worker_index < worker_count,
            "GPU identity registry contains an invalid worker index.",
        )
        binding = validated[worker_index]
        identity = cast(Mapping[str, Any], binding["selected_device_routing_identity"])
        key = (cast(str, identity["identity_type"]), cast(str, identity["identity"]))
        scheduler = {
            "path": binding["path"],
            "device": binding["device"],
            "inode": binding["inode"],
        }
        scheduler_key = (
            cast(str, scheduler["path"]),
            cast(int, scheduler["device"]),
            cast(int, scheduler["inode"]),
        )
        prior_identity = scheduler_to_identity.setdefault(scheduler_key, key)
        _require(
            prior_identity == key,
            "One scheduler lease identity is assigned to different physical GPUs.",
        )
        candidate = {
            "routing_identity": dict(identity),
            "selected_device_class": dict(
                cast(Mapping[str, Any], binding["selected_device_class"])
            ),
            "scheduler_lease": scheduler,
            "device_guard": dict(cast(Mapping[str, Any], binding["device_guard"])),
            "worker_indices": [worker_index],
            "worker_device_routes": [
                {
                    "worker_index": worker_index,
                    "logical_index": binding["selected_device_logical_index"],
                    "device_argument": binding["device_argument"],
                }
            ],
        }
        prior = by_identity.get(key)
        if prior is None:
            by_identity[key] = candidate
            continue
        _require(
            prior["selected_device_class"] == candidate["selected_device_class"]
            and prior["scheduler_lease"] == scheduler
            and prior["device_guard"] == candidate["device_guard"],
            "One physical GPU routing identity maps to different scheduler or device leases.",
        )
        cast(list[int], prior["worker_indices"]).append(worker_index)
        cast(list[dict[str, Any]], prior["worker_device_routes"]).extend(
            cast(list[dict[str, Any]], candidate["worker_device_routes"])
        )
    return [by_identity[key] for key in sorted(by_identity)]


def _gpu_registry_payload(
    gpu_bindings: Mapping[int, Mapping[str, Any]], *, worker_count: int
) -> list[dict[str, Any]]:
    _require(
        all(type(index) is int and 0 <= index < worker_count for index in gpu_bindings),
        "GPU worker-lease registry contains an invalid worker index.",
    )
    result = [
        {"worker_index": index, **_validate_gpu_lease_binding(gpu_bindings[index])}
        for index in sorted(gpu_bindings)
    ]
    _gpu_device_identity_registry(gpu_bindings, worker_count=worker_count)
    return result


def _distributed_summary_from_ledgers(
    ledgers: Mapping[int, Sequence[Mapping[str, Any]]],
    *,
    output_root: Path,
    gpu_bindings: Mapping[int, Mapping[str, Any]],
    worker_count: int,
    prerequisites: FrozenPrerequisites,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[int, dict[str, Any]]]:
    prefix, merged = _merge_worker_records(ledgers, worker_count=worker_count)
    coordinate_items = coordinates()
    storage_records = [merged[index] for index in sorted(merged)]
    storage_remaining = [
        coordinate for index, coordinate in enumerate(coordinate_items) if index not in merged
    ]
    completed_by_worker = {index: len(records) for index, records in ledgers.items()}
    worker_registry = _worker_ledger_registry(
        output_root,
        worker_count=worker_count,
        completed_by_worker=completed_by_worker,
    )
    return (
        _matrix_payload(
            prefix,
            output_root=output_root,
            prerequisites=prerequisites,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            worker_count=worker_count,
            gpu_worker_leases=gpu_bindings,
            worker_ledger_root=_worker_ledger_root_binding(output_root, worker_count=worker_count),
            worker_ledger_bindings=worker_registry,
            globally_committed_shards=len(merged),
            storage_records=storage_records,
            storage_remaining_coordinates=storage_remaining,
        ),
        merged,
    )


def _historical_worker_ledger_registry(
    ledgers: Mapping[int, Sequence[Mapping[str, Any]]],
    *,
    output_root: Path,
    gpu_bindings: Mapping[int, Mapping[str, Any]],
    worker_count: int,
    prerequisites: FrozenPrerequisites,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
) -> list[dict[str, Any]]:
    _require(
        set(ledgers) == set(gpu_bindings),
        "Historical worker-ledger/GPU registries disagree.",
    )
    root_binding = _worker_ledger_root_binding(
        output_root, worker_count=worker_count
    )
    _require(
        root_binding is not None,
        "Historical distributed worker-ledger root binding is missing.",
    )
    result: list[dict[str, Any]] = []
    for worker_index in sorted(ledgers):
        records = ledgers[worker_index]
        payload = _worker_payload(
            records,
            worker_index=worker_index,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            gpu_lease_binding=gpu_bindings[worker_index],
        )
        encoded = (
            json.dumps(payload, indent=2, sort_keys=True, allow_nan=False) + "\n"
        ).encode()
        envelope = payload.get("attestation")
        _require(
            isinstance(envelope, Mapping),
            "Historical worker-ledger attestation is missing.",
        )
        path = _worker_ledger_path(
            output_root,
            worker_index=worker_index,
            worker_count=worker_count,
        )
        assigned_count = len(
            _assigned_coordinates(
                worker_index=worker_index, worker_count=worker_count
            )
        )
        status = "terminal" if len(records) == assigned_count else "in_progress"
        result.append(
            {
                "worker_index": worker_index,
                "worker_count": worker_count,
                "assignment_rule": WORKER_ASSIGNMENT_RULE,
                "root": dict(cast(Mapping[str, Any], root_binding)),
                "path_semantics": WORKER_LEDGER_PATH_SEMANTICS,
                "relative_path": path.name,
                "path": str(path),
                "sha256": hashlib.sha256(encoded).hexdigest(),
                "bytes": len(encoded),
                "payload_sha256": payload.get("payload_sha256"),
                "attestation_mac": cast(Mapping[str, Any], envelope).get("mac"),
                "attestation": dict(cast(Mapping[str, Any], envelope)),
                "status": status,
                "completed_shards": len(records),
                "assigned_coordinate_count": assigned_count,
            }
        )
    return result


def _validate_stale_distributed_matrix_predecessor(
    disk_payload: Mapping[str, Any],
    *,
    layout: MatrixLayout,
    worker_count: int,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    expected_gpu_worker_leases: Mapping[int, Mapping[str, Any]],
) -> dict[str, Any] | None:
    status = disk_payload.get("status")
    expected_schema = (
        _MATRIX_FIELDS if status == "in_progress" else _DRAINING_MATRIX_FIELDS
    )
    _require(
        status in {"in_progress", "draining_infrastructure"}
        and set(disk_payload) == expected_schema,
        "Only an active or draining matrix may be a stale worker-ledger predecessor.",
    )
    current_ledgers, current_gpu_bindings = _load_worker_ledgers(
        output_root=layout.output_root,
        worker_count=worker_count,
        prerequisites=prerequisites,
        evaluator_script=evaluator_script,
        evaluator_binding=evaluator_binding,
        matrix_lock_binding=matrix_lock_binding,
        verify_bundles=False,
    )
    _require(
        current_gpu_bindings
        == {
            index: _validate_gpu_lease_binding(binding)
            for index, binding in expected_gpu_worker_leases.items()
        },
        "Current worker-ledger GPU bindings drifted during predecessor recovery.",
    )
    raw_registry = disk_payload.get("worker_ledger_registry")
    _require(
        isinstance(raw_registry, list),
        "Stale matrix worker-ledger registry is invalid.",
    )
    old_counts: dict[int, int] = {}
    for row in cast(list[Any], raw_registry):
        _require(
            isinstance(row, Mapping)
            and type(row.get("worker_index")) is int
            and type(row.get("completed_shards")) is int,
            "Stale matrix worker-ledger registry row is invalid.",
        )
        row_map = cast(Mapping[str, Any], row)
        index = cast(int, row_map["worker_index"])
        count = cast(int, row_map["completed_shards"])
        _require(
            0 <= index < worker_count
            and count >= 0
            and index not in old_counts,
            "Stale matrix worker-ledger registry is non-canonical.",
        )
        old_counts[index] = count
    _require(
        list(old_counts) == sorted(old_counts)
        and set(old_counts).issubset(current_ledgers),
        "Stale matrix worker-ledger registry is not a current-ledger subset.",
    )
    current_counts = {
        index: len(records) for index, records in current_ledgers.items()
    }
    added_workers = set(current_counts) - set(old_counts)
    advanced_workers = {
        index
        for index in old_counts
        if current_counts[index] != old_counts[index]
    }
    created_empty_ledger = (
        len(added_workers) == 1
        and not advanced_workers
        and current_counts[next(iter(added_workers))] == 0
    )
    committed_one_record = (
        not added_workers
        and len(advanced_workers) == 1
        and current_counts[next(iter(advanced_workers))]
        == old_counts[next(iter(advanced_workers))] + 1
    )
    _require(
        created_empty_ledger or committed_one_record,
        "Distributed matrix is not the exact one-step worker-ledger predecessor.",
    )
    _require(
        status == "in_progress" or committed_one_record,
        "A draining predecessor requires exactly one declared record commit.",
    )
    historical_ledgers = {
        index: list(current_ledgers[index][:count])
        for index, count in old_counts.items()
    }
    historical_gpu_bindings = {
        index: current_gpu_bindings[index] for index in old_counts
    }
    historical_registry = _historical_worker_ledger_registry(
        historical_ledgers,
        output_root=layout.output_root,
        gpu_bindings=historical_gpu_bindings,
        worker_count=worker_count,
        prerequisites=prerequisites,
        evaluator_binding=evaluator_binding,
        matrix_lock_binding=matrix_lock_binding,
    )
    _require(
        raw_registry == historical_registry,
        "Stale matrix registry does not bind the exact predecessor worker ledgers.",
    )
    historical_prefix, historical_merged = _merge_worker_records(
        historical_ledgers, worker_count=worker_count
    )
    coordinate_items = coordinates()
    storage_records = [
        historical_merged[index] for index in sorted(historical_merged)
    ]
    storage_remaining = [
        coordinate
        for index, coordinate in enumerate(coordinate_items)
        if index not in historical_merged
    ]
    reconstructed = _matrix_payload(
        historical_prefix,
        output_root=layout.output_root,
        prerequisites=prerequisites,
        evaluator_binding=evaluator_binding,
        matrix_lock_binding=matrix_lock_binding,
        worker_count=worker_count,
        gpu_worker_leases=historical_gpu_bindings,
        worker_ledger_root=_worker_ledger_root_binding(
            layout.output_root, worker_count=worker_count
        ),
        worker_ledger_bindings=historical_registry,
        globally_committed_shards=len(historical_merged),
        storage_records=storage_records,
        storage_remaining_coordinates=storage_remaining,
    )
    raw_session_projection = disk_payload.get("persistent_session_ledger")
    _require(
        isinstance(raw_session_projection, Mapping),
        "Stale matrix persistent-session watermark is missing.",
    )
    checked_session_projection = _validate_persistent_session_ledger_snapshot(
        cast(Mapping[str, Any], raw_session_projection),
        output_root=layout.output_root,
        trust_root=prerequisites.trust_root,
        require_current_exact=False,
    )
    _crosscheck_matrix_records_with_session_ledger(
        storage_records,
        checked_session_projection,
        require_terminal_sessions=False,
    )
    historical_resume_body = dict(reconstructed)
    historical_resume_body.pop("payload_sha256", None)
    historical_resume_body.pop("attestation", None)
    historical_resume_body["persistent_session_ledger"] = checked_session_projection
    historical_resume = _attested_payload(
        historical_resume_body, trust_root=prerequisites.trust_root
    )
    if status == "in_progress":
        _require(
            disk_payload == historical_resume,
            "Stale matrix differs from the exact authenticated predecessor.",
        )
        return None

    raw_reason = disk_payload.get("infrastructure_drain")
    _require(
        isinstance(raw_reason, Mapping),
        "Draining predecessor reason is missing.",
    )
    reason = cast(Mapping[str, Any], raw_reason)
    owner = reason.get("pause_worker_index")
    raw_declared_claims = reason.get("active_claim_coordinate_indices")
    filesystem_available_bytes = reason.get("filesystem_available_bytes")
    _require(
        type(owner) is int
        and isinstance(raw_declared_claims, list)
        and all(type(index) is int for index in raw_declared_claims)
        and raw_declared_claims == sorted(set(raw_declared_claims))
        and type(filesystem_available_bytes) is int,
        "Draining predecessor owner, signal, or declared claims drifted.",
    )
    owner_index = cast(int, owner)
    owner_assignment = _assigned_coordinates(
        worker_index=owner_index, worker_count=worker_count
    )
    _require(
        owner_index in historical_ledgers,
        "Draining predecessor owner has no historical worker ledger.",
    )
    owner_records = historical_ledgers[owner_index]
    _require(
        len(owner_records) < len(owner_assignment),
        "Draining predecessor owner has no historical next coordinate.",
    )
    historical_signal = _headroom_signal_payload(
        records=storage_records,
        coordinate=owner_assignment[len(owner_records)],
        filesystem_available_bytes=cast(int, filesystem_available_bytes),
    )
    historical_draining = _draining_matrix_payload(
        historical_resume,
        signal=historical_signal,
        worker_index=owner_index,
        active_claim_coordinate_indices=cast(list[int], raw_declared_claims),
        trust_root=prerequisites.trust_root,
    )
    _require(
        disk_payload == historical_draining,
        "Draining predecessor is not the exact authenticated blocked state.",
    )

    advanced_worker = next(iter(advanced_workers))
    advanced_assignment = _assigned_coordinates(
        worker_index=advanced_worker, worker_count=worker_count
    )
    committed_coordinate = advanced_assignment[old_counts[advanced_worker]]
    committed_coordinate_index = coordinate_items.index(committed_coordinate)
    current_prefix, current_merged = _merge_worker_records(
        current_ledgers, worker_count=worker_count
    )
    del current_prefix
    active_claims = _preflight_distributed_output_tree(
        output_root=layout.output_root,
        matrix_summary=layout.matrix_summary,
        merged_records=current_merged,
        worker_count=worker_count,
    )
    declared_claims = set(cast(list[int], raw_declared_claims))
    _require(
        committed_coordinate_index in declared_claims
        and declared_claims
        == set(active_claims) | {committed_coordinate_index},
        "Draining predecessor commit was not exactly one predeclared live claim.",
    )
    current_resume, checked_current_merged = _distributed_summary_from_ledgers(
        current_ledgers,
        output_root=layout.output_root,
        gpu_bindings=current_gpu_bindings,
        worker_count=worker_count,
        prerequisites=prerequisites,
        evaluator_binding=evaluator_binding,
        matrix_lock_binding=matrix_lock_binding,
    )
    _require(
        checked_current_merged == current_merged,
        "Draining predecessor current merged records drifted.",
    )
    if current_resume.get("globally_committed_shards") == EXPECTED_SHARDS:
        return current_resume
    _require(
        current_resume.get("status") == "in_progress",
        "Draining predecessor did not recover to a resumable matrix body.",
    )
    return _rebind_infrastructure_after_commit(
        prior_blocked_payload=disk_payload,
        resume_payload=current_resume,
        ledgers=current_ledgers,
        merged_records=current_merged,
        active_claim_coordinate_indices=tuple(sorted(active_claims)),
        output_root=layout.output_root,
        worker_count=worker_count,
        trust_root=prerequisites.trust_root,
    )


def _validate_distributed_disk_summary(
    *,
    layout: MatrixLayout,
    expected_payload: Mapping[str, Any],
    worker_count: int,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    expected_gpu_worker_leases: Mapping[int, Mapping[str, Any]],
    ready_only_preflight_gpu_lease_binding: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    _require(layout.matrix_summary.exists(), "Distributed matrix summary disappeared.")
    disk_payload = _load_json_nofollow(
        layout.matrix_summary, label="controller matrix ledger"
    )
    _verify_attested_payload(
        disk_payload, trust_root=prerequisites.trust_root
    )
    same_worker_watermark = (
        disk_payload.get("worker_ledger_registry")
        == expected_payload.get("worker_ledger_registry")
        and disk_payload.get("globally_committed_shards")
        == expected_payload.get("globally_committed_shards")
    )
    if not same_worker_watermark:
        recovered_blocked_payload = _validate_stale_distributed_matrix_predecessor(
            disk_payload,
            layout=layout,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            expected_gpu_worker_leases=expected_gpu_worker_leases,
        )
        if expected_payload.get("globally_committed_shards") == EXPECTED_SHARDS:
            replayed_ledgers, replayed_gpu_bindings = _load_worker_ledgers(
                output_root=layout.output_root,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_script=evaluator_script,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=matrix_lock_binding,
                verify_bundles=True,
            )
            replayed_payload, replayed_merged = _distributed_summary_from_ledgers(
                replayed_ledgers,
                output_root=layout.output_root,
                gpu_bindings=replayed_gpu_bindings,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=matrix_lock_binding,
            )
            _require(
                len(replayed_merged) == EXPECTED_SHARDS
                and replayed_payload == expected_payload,
                "Recovered full matrix differs after exact all-bundle replay.",
            )
        recovered_payload = (
            expected_payload
            if recovered_blocked_payload is None
            else recovered_blocked_payload
        )
        _atomic_write_json(layout.matrix_summary, recovered_payload)
        validate_matrix_summary(
            recovered_payload,
            output_root=layout.output_root,
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            verify_bundles=False,
            expected_worker_count=worker_count,
            expected_gpu_worker_leases=expected_gpu_worker_leases,
            ready_only_preflight_gpu_lease_binding=(
                ready_only_preflight_gpu_lease_binding
            ),
        )
        return dict(recovered_payload)
    disk_records = validate_matrix_summary(
        disk_payload,
        output_root=layout.output_root,
        prerequisites=prerequisites,
        evaluator_script=evaluator_script,
        evaluator_binding=evaluator_binding,
        matrix_lock_binding=matrix_lock_binding,
        verify_bundles=False,
        expected_worker_count=worker_count,
        expected_gpu_worker_leases=expected_gpu_worker_leases,
        ready_only_preflight_gpu_lease_binding=(
            ready_only_preflight_gpu_lease_binding
        ),
        allow_stale_session_ledger_watermark=True,
    )
    _require(
        disk_records == expected_payload["records"],
        "Distributed matrix summary record projection drifted from worker ledgers.",
    )
    refreshed = _refresh_matrix_session_projection(
        disk_payload=disk_payload,
        current_resume_payload=expected_payload,
        matrix_summary=layout.matrix_summary,
        trust_root=prerequisites.trust_root,
    )
    validate_matrix_summary(
        refreshed,
        output_root=layout.output_root,
        prerequisites=prerequisites,
        evaluator_script=evaluator_script,
        evaluator_binding=evaluator_binding,
        matrix_lock_binding=matrix_lock_binding,
        verify_bundles=False,
        expected_worker_count=worker_count,
        expected_gpu_worker_leases=expected_gpu_worker_leases,
        ready_only_preflight_gpu_lease_binding=(
            ready_only_preflight_gpu_lease_binding
        ),
    )
    return refreshed


def _reconcile_active_persistent_session_records(
    active: PersistentEvaluatorProcess,
    records: Sequence[Mapping[str, Any]],
) -> None:
    session_nonce = active.plan["session_nonce"]
    committed_records: dict[int, tuple[dict[str, Any], dict[str, Any]]] = {}
    eof_work_orders: list[dict[str, Any]] = []
    for record in records:
        raw_execution = record.get("persistent_session_execution")
        _require(
            isinstance(raw_execution, Mapping),
            "Scope reconciliation found a matrix record without persistent execution.",
        )
        execution = cast(Mapping[str, Any], raw_execution)
        raw_plan = execution.get("plan")
        if not isinstance(raw_plan, Mapping) or raw_plan.get("session_nonce") != session_nonce:
            continue
        raw_work = execution.get("work_order")
        raw_result = execution.get("work_result")
        if raw_result is None:
            _require(
                isinstance(raw_work, Mapping)
                and execution.get("published_bundle_reingested_after_child_eof") is True,
                "Scope reconciliation found a malformed durable EOF reingestion.",
            )
            eof_work_orders.append(dict(cast(Mapping[str, Any], raw_work)))
            continue
        _require(
            isinstance(raw_work, Mapping) and isinstance(raw_result, Mapping),
            "Scope reconciliation found a malformed committed work/result pair.",
        )
        work = dict(cast(Mapping[str, Any], raw_work))
        result = dict(cast(Mapping[str, Any], raw_result))
        sequence_index = work.get("sequence_index")
        _require(
            type(sequence_index) is int,
            "Scope reconciliation found a malformed session sequence.",
        )
        checked_sequence_index = cast(int, sequence_index)
        _require(
            checked_sequence_index not in committed_records,
            "Scope reconciliation found a duplicate session sequence.",
        )
        committed_records[checked_sequence_index] = (work, result)
    for sequence_index in range(active.committed_count):
        _require(
            committed_records.get(sequence_index)
            == (active.work_orders[sequence_index], active.results[sequence_index]),
            "Previously committed persistent result disappeared from the signed matrix.",
        )
    while active.committed_count in committed_records:
        sequence_index = active.committed_count
        _require(
            sequence_index < len(active.work_orders) == len(active.results),
            "Signed matrix advanced beyond the live persistent child transcript.",
        )
        work, result = committed_records[sequence_index]
        active.mark_committed(work_order=work, work_result=result)
    _require(
        not any(index >= active.committed_count for index in committed_records),
        "Signed matrix contains a non-contiguous persistent-session commit.",
    )
    _require(
        len(eof_work_orders) <= 1,
        "Signed matrix contains multiple persistent-session EOF reingestions.",
    )
    if eof_work_orders:
        _require(
            active.closed
            and not active.terminal_published
            and active.eof_work_order is not None
            and eof_work_orders[0] == active.eof_work_order
            and eof_work_orders[0].get("sequence_index") == len(active.work_orders),
            "Durable EOF reingestion differs from the live child EOF boundary.",
        )
        active.verified_eof_reingested = True


def _refresh_single_scope_session_projection(
    *,
    layout: MatrixLayout,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    gpu_binding: Mapping[str, Any],
    active: PersistentEvaluatorProcess | None,
) -> None:
    with _exclusive_matrix_lock(
        layout.lock_path,
        matrix_summary=layout.matrix_summary,
        expected_binding=matrix_lock_binding,
    ):
        disk_payload = _load_json_nofollow(
            layout.matrix_summary, label="controller matrix ledger"
        )
        records = validate_matrix_summary(
            disk_payload,
            output_root=layout.output_root,
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            verify_bundles=False,
            expected_gpu_worker_leases={0: gpu_binding},
            allow_stale_session_ledger_watermark=True,
        )
        if active is not None:
            _reconcile_active_persistent_session_records(active, records)
            return
        current_payload = _matrix_payload(
            records,
            output_root=layout.output_root,
            prerequisites=prerequisites,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            gpu_worker_leases={0: gpu_binding},
        )
        refreshed = _refresh_matrix_session_projection(
            disk_payload=disk_payload,
            current_resume_payload=current_payload,
            matrix_summary=layout.matrix_summary,
            trust_root=prerequisites.trust_root,
        )
        validate_matrix_summary(
            refreshed,
            output_root=layout.output_root,
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            verify_bundles=False,
            expected_gpu_worker_leases={0: gpu_binding},
        )


def _refresh_distributed_scope_session_projection(
    *,
    layout: MatrixLayout,
    worker_index: int,
    worker_count: int,
    prerequisites: FrozenPrerequisites,
    evaluator_script: Path,
    evaluator_binding: Mapping[str, Any],
    matrix_lock_binding: Mapping[str, Any],
    gpu_binding: Mapping[str, Any],
    active: PersistentEvaluatorProcess | None,
) -> None:
    with _exclusive_matrix_lock(
        layout.lock_path,
        matrix_summary=layout.matrix_summary,
        expected_binding=matrix_lock_binding,
    ):
        ledgers, gpu_bindings = _load_worker_ledgers(
            output_root=layout.output_root,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            verify_bundles=False,
            expected_worker_index=worker_index,
            expected_gpu_lease_binding=gpu_binding,
        )
        current_payload, merged = _distributed_summary_from_ledgers(
            ledgers,
            output_root=layout.output_root,
            gpu_bindings=gpu_bindings,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
        )
        _validate_distributed_disk_summary(
            layout=layout,
            expected_payload=current_payload,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_script=evaluator_script,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=matrix_lock_binding,
            expected_gpu_worker_leases=gpu_bindings,
            ready_only_preflight_gpu_lease_binding=gpu_binding,
        )
        if active is not None:
            _reconcile_active_persistent_session_records(
                active, [merged[index] for index in sorted(merged)]
            )


def _assert_terminal_launch_authority(
    plan: Mapping[str, Any],
    command: Sequence[str],
    *,
    canonical: Path,
    canonical_descriptor: int,
    evaluator_snapshot: CanonicalEvaluatorSnapshot,
    prerequisites: FrozenPrerequisites,
    gpu_binding: Mapping[str, Any],
    gpu_lease: GPULockLease,
    device_guard_lease: GPULockLease,
    output_root: Path,
) -> None:
    gpu_lease.assert_held()
    device_guard_lease.assert_held()
    admission.assert_quality_context_unchanged(prerequisites.context)
    _assert_open_evaluator(canonical_descriptor, expected=evaluator_snapshot)
    _require(
        str(canonical) == evaluator_snapshot.path and bool(command),
        "Persistent terminal evaluator or launch command authority drifted.",
    )
    checked_plan = persistent_session.validate_session_plan(
        plan, trust_root=prerequisites.trust_root
    )
    current_gpu_binding = _gpu_lease_binding(
        gpu_lease,
        device_guard_lease=device_guard_lease,
        device_context=gpu_binding,
    )
    _require(
        checked_plan == dict(plan)
        and checked_plan["canonical_evaluator_digest"]
        == contract.json_digest(evaluator_snapshot.public_binding)
        and checked_plan["prerequisites_binding_digest"]
        == contract.json_digest(prerequisites.public_binding)
        and checked_plan["gpu_lease_binding_digest"]
        == contract.json_digest(gpu_binding)
        and checked_plan["output_root"] == str(_absolute(output_root))
        and current_gpu_binding == dict(gpu_binding),
        "Persistent recovery terminal authority drifted.",
    )
    projection = persistent_session.load_session_ledger_projection(
        _absolute(output_root), trust_root=prerequisites.trust_root
    )
    matching = [
        row
        for row in cast(list[Mapping[str, Any]], projection["sessions"])
        if row["session_nonce"] == checked_plan["session_nonce"]
    ]
    _require(
        len(matching) == 1
        and matching[0]["status"] == "launch_only"
        and matching[0]["launch_authority_nonce"]
        == checked_plan["launch_authority_nonce"]
        and matching[0]["plan_payload_sha256"]
        == checked_plan["payload_sha256"]
        and matching[0]["actual_session_argv"] == list(command),
        "Persistent terminal durable launch authority drifted.",
    )


def _reconcile_committed_sessions_with_terminal_authority(
    output_root: Path,
    records: Sequence[Mapping[str, Any]],
    *,
    worker_index: int,
    canonical: Path,
    evaluator_snapshot: CanonicalEvaluatorSnapshot,
    prerequisites: FrozenPrerequisites,
    gpu_binding: Mapping[str, Any],
    gpu_lease: GPULockLease,
    device_guard_lease: GPULockLease,
) -> dict[str, Any]:
    descriptor, checked_snapshot = _open_evaluator(
        canonical, expected=evaluator_snapshot
    )
    _require(
        checked_snapshot == evaluator_snapshot,
        "Persistent recovery retained evaluator snapshot drifted.",
    )
    try:
        reconciled: dict[str, Any] = (
            persistent_session.reconcile_committed_launch_only_sessions(
                output_root,
                records,
                worker_index=worker_index,
                gpu_lease_binding_digest=contract.json_digest(gpu_binding),
                terminal_authority_check=lambda plan, command: (
                    _assert_terminal_launch_authority(
                        plan,
                        command,
                        canonical=canonical,
                        canonical_descriptor=descriptor,
                        evaluator_snapshot=evaluator_snapshot,
                        prerequisites=prerequisites,
                        gpu_binding=gpu_binding,
                        gpu_lease=gpu_lease,
                        device_guard_lease=device_guard_lease,
                        output_root=output_root,
                    )
                ),
                trust_root=prerequisites.trust_root,
            )
        )
        return reconciled
    finally:
        os.close(descriptor)

def _run_distributed_matrix(
    *,
    layout: MatrixLayout,
    manifest_path: Path,
    evaluator_script: Path,
    attestation_key_path: Path | None,
    start_mode: str,
    max_new_cells: int | None,
    worker_index: int,
    worker_count: int,
    coordinator_only: bool,
    gpu_lock_path: Path,
    _stop_before_new_claim: threading.Event | None = None,
    _prepared: tuple[
        Path,
        Mapping[str, Any],
        FrozenPrerequisites,
        CanonicalEvaluatorSnapshot,
        Mapping[str, Any],
        GPULockLease | None,
        GPULockLease | None,
        Mapping[str, Any] | None,
    ]
    | None = None,
) -> dict[str, Any]:
    _validate_worker_identity(worker_index=worker_index, worker_count=worker_count)
    _distributed_layout_guard(layout, attestation_key_path=attestation_key_path)
    if _prepared is None:
        canonical = _canonical_evaluator(evaluator_script)
        activation_lease: admission.QualityStartActivationLeaseV1_3_5 | None = None
        gpu_lease = (
            None
            if coordinator_only
            else acquire_gpu_lock(
                f"p2-direct-controller-exact-fill-v1-3-5-worker-{worker_index}-of-{worker_count}",
                path=gpu_lock_path,
            )
        )
        device_guard_lease: GPULockLease | None = None
        device_context: dict[str, Any] | None = None
        try:
            prerequisites, activation_lease = _prepare_quality_start_authority(
                start_mode=start_mode,
                layout=layout,
                manifest_path=manifest_path,
                attestation_key_path=attestation_key_path,
                worker_count=worker_count,
                scheduler_lease=gpu_lease,
            )
            lock_binding = _activation_lock_binding(
                prerequisites, activation_lease
            )
            admission.assert_quality_context_unchanged(prerequisites.context)
            if gpu_lease is not None:
                gpu_lease.assert_held()
                device_context = _capture_selected_device_context(gpu_lease)
                device_guard_lease = _acquire_selected_device_guard(
                    label=f"p2-direct-controller-exact-fill-v1-3-5-worker-{worker_index}-of-{worker_count}",
                    device_context=device_context,
                    scheduler_lease=gpu_lease,
                )
                device_guard_lease.assert_held()
            if gpu_lease is not None:
                gpu_lease.assert_held()
                _require(
                    device_guard_lease is not None and device_context is not None,
                    "Distributed controller physical-device guard is missing.",
                )
                cast(GPULockLease, device_guard_lease).assert_held()
                device_context = _validate_selected_device_context(
                    cast(Mapping[str, Any], device_context), prerequisites=prerequisites
                )
            _require(
                EVALUATOR_IMPLEMENTATION_PATH in contract.V1_3_5_IMPLEMENTATION_PATHS
                and GPU_LOCK_IMPLEMENTATION_PATH in contract.V1_3_5_IMPLEMENTATION_PATHS,
                "Canonical evaluator or GPU lease helper is absent from the frozen inventory.",
            )
            _require(
                contract.v1_3_5_implementation_tree_digest()
                == prerequisites.context.manifest_binding["implementation_digest"],
                "Canonical evaluator is not bound by the frozen manifest.",
            )
            evaluator_fd, evaluator_snapshot = _open_evaluator(canonical)
            os.close(evaluator_fd)
            evaluator_binding = evaluator_snapshot.public_binding
            gpu_binding = (
                None
                if gpu_lease is None
                else _gpu_lease_binding(
                    gpu_lease,
                    device_guard_lease=cast(GPULockLease, device_guard_lease),
                    device_context=cast(Mapping[str, Any], device_context),
                )
            )
            _require(
                activation_lease is not None,
                "Distributed activation lease disappeared before ledger adoption.",
            )
            _complete_activation_ledger_boundary(
                start_mode=start_mode,
                layout=layout,
                prerequisites=prerequisites,
                activation_lease=activation_lease,
                evaluator_binding=evaluator_binding,
                ready_only_preflight={},
                worker_count=worker_count,
                gpu_lease_binding=gpu_binding,
            )
            activation_lease.close()
            activation_lease = None
            prepared_result = _run_distributed_matrix(
                layout=layout,
                manifest_path=manifest_path,
                evaluator_script=evaluator_script,
                attestation_key_path=attestation_key_path,
                start_mode=start_mode,
                max_new_cells=max_new_cells,
                worker_index=worker_index,
                worker_count=worker_count,
                coordinator_only=coordinator_only,
                gpu_lock_path=gpu_lock_path,
                _stop_before_new_claim=_stop_before_new_claim,
                _prepared=(
                    canonical,
                    lock_binding,
                    prerequisites,
                    evaluator_snapshot,
                    evaluator_binding,
                    gpu_lease,
                    device_guard_lease,
                    gpu_binding,
                ),
            )
            if gpu_lease is not None:
                gpu_lease.assert_held()
                cast(GPULockLease, device_guard_lease).assert_held()
            return prepared_result
        finally:
            if activation_lease is not None:
                activation_lease.close()
            if gpu_lease is not None:
                scope_exc_type, scope_error, scope_traceback = sys.exc_info()
                try:
                    _settle_active_persistent_evaluator_scope(
                        gpu_lease, scope_exc_type, scope_error, scope_traceback
                    )
                finally:
                    if device_guard_lease is None:
                        gpu_lease.close()
                    else:
                        _close_gpu_lease_pair(gpu_lease, device_guard_lease)
    canonical = _prepared[0]
    lock_binding = dict(_prepared[1])
    prerequisites = _prepared[2]
    evaluator_snapshot = _prepared[3]
    evaluator_binding = dict(_prepared[4])
    current_gpu_lease = _prepared[5]
    current_device_guard_lease = _prepared[6]
    current_gpu_binding = _prepared[7]
    _require(
        coordinator_only
        == (
            current_gpu_lease is None
            and current_device_guard_lease is None
            and current_gpu_binding is None
        ),
        "Distributed controller GPU lease preparation mode drifted.",
    )
    if current_gpu_lease is not None:
        current_gpu_lease.assert_held()
        cast(GPULockLease, current_device_guard_lease).assert_held()

    with _exclusive_matrix_lock(
        layout.lock_path,
        matrix_summary=layout.matrix_summary,
        expected_binding=lock_binding,
    ):
        ledgers, gpu_bindings = _load_worker_ledgers(
            output_root=layout.output_root,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_script=canonical,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=lock_binding,
            verify_bundles=coordinator_only,
            expected_worker_index=None if coordinator_only else worker_index,
            expected_gpu_lease_binding=current_gpu_binding,
        )
        # A resuming worker replays its own immutable partition once. Other partitions are
        # accepted through their HMAC ledgers and are independently replayed by their owners.
        if not coordinator_only and worker_index in ledgers:
            own_path = _worker_ledger_path(
                layout.output_root,
                worker_index=worker_index,
                worker_count=worker_count,
            )
            own_records, own_gpu_binding = _validate_worker_ledger(
                _load_json_nofollow(own_path, label="controller worker ledger"),
                worker_index=worker_index,
                worker_count=worker_count,
                output_root=layout.output_root,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                verify_bundles=True,
                expected_gpu_lease_binding=current_gpu_binding,
            )
            ledgers[worker_index] = own_records
            gpu_bindings[worker_index] = own_gpu_binding
        if not coordinator_only:
            _require(
                current_gpu_binding is not None,
                "Persistent recovery requires the reacquired worker GPU lease.",
            )
            cast(GPULockLease, current_gpu_lease).assert_held()
            cast(GPULockLease, current_device_guard_lease).assert_held()
            _reconcile_committed_sessions_with_terminal_authority(
                layout.output_root,
                [
                    record
                    for ledger_index in sorted(ledgers)
                    for record in ledgers[ledger_index]
                ],
                worker_index=worker_index,
                canonical=canonical,
                evaluator_snapshot=evaluator_snapshot,
                prerequisites=prerequisites,
                gpu_binding=cast(Mapping[str, Any], current_gpu_binding),
                gpu_lease=cast(GPULockLease, current_gpu_lease),
                device_guard_lease=cast(
                    GPULockLease, current_device_guard_lease
                ),
            )
            cast(GPULockLease, current_gpu_lease).assert_held()
            cast(GPULockLease, current_device_guard_lease).assert_held()
        summary_payload, merged = _distributed_summary_from_ledgers(
            ledgers,
            output_root=layout.output_root,
            gpu_bindings=gpu_bindings,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=lock_binding,
        )
        active_claims = _preflight_distributed_output_tree(
            output_root=layout.output_root,
            matrix_summary=layout.matrix_summary,
            merged_records=merged,
            worker_count=worker_count,
        )
        if layout.matrix_summary.exists():
            disk_summary_payload = _validate_distributed_disk_summary(
                layout=layout,
                expected_payload=summary_payload,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                expected_gpu_worker_leases=gpu_bindings,
                ready_only_preflight_gpu_lease_binding=current_gpu_binding,
            )
            if disk_summary_payload.get("status") in {
                "paused_infrastructure",
                "draining_infrastructure",
            }:
                reason_field = (
                    "infrastructure_pause"
                    if disk_summary_payload.get("status") == "paused_infrastructure"
                    else "infrastructure_drain"
                )
                pause = cast(Mapping[str, Any], disk_summary_payload[reason_field])
                if coordinator_only or pause.get("pause_worker_index") != worker_index:
                    return disk_summary_payload
        else:
            _atomic_write_json(layout.matrix_summary, summary_payload)
        if coordinator_only:
            _require(
                not active_claims,
                "Coordinator-only finalization refuses live distributed cell claims.",
            )
            _require(
                summary_payload.get("status") in {"terminal", "in_progress"}
                and len(ledgers) == worker_count
                and all(
                    len(ledgers[index])
                    == len(_assigned_coordinates(worker_index=index, worker_count=worker_count))
                    for index in range(worker_count)
                ),
                "Coordinator-only site finalization requires every worker ledger to be terminal.",
            )
            _atomic_write_json(layout.matrix_summary, summary_payload)
            validate_matrix_summary(
                summary_payload,
                output_root=layout.output_root,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                verify_bundles=False,
                expected_worker_count=worker_count,
                expected_gpu_worker_leases=gpu_bindings,
                ready_only_preflight_gpu_lease_binding=current_gpu_binding,
            )
            return summary_payload
        _require(
            not any(_coordinate_worker_index(coordinates()[index], worker_count=worker_count)
                == worker_index
                for index in active_claims),
            "This distributed worker already owns a live cell claim.",
        )
        if worker_index not in ledgers:
            if current_gpu_binding is None:
                raise ValueError("Distributed worker cannot initialize without a held GPU lease.")
            ledgers[worker_index] = []
            gpu_bindings[worker_index] = dict(current_gpu_binding)
            _atomic_write_json(
                _worker_ledger_path(
                    layout.output_root,
                    worker_index=worker_index,
                    worker_count=worker_count,
                ),
                _worker_payload(
                    [],
                    worker_index=worker_index,
                    worker_count=worker_count,
                    prerequisites=prerequisites,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    gpu_lease_binding=current_gpu_binding,
                ),
            )
            summary_payload, _ = _distributed_summary_from_ledgers(
                ledgers,
                output_root=layout.output_root,
                gpu_bindings=gpu_bindings,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
            )
            _atomic_write_json(layout.matrix_summary, summary_payload)

    _register_persistent_projection_refresher(
        cast(GPULockLease, current_gpu_lease),
        lambda active: _refresh_distributed_scope_session_projection(
            layout=layout,
            worker_index=worker_index,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_script=canonical,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=lock_binding,
            gpu_binding=cast(Mapping[str, Any], current_gpu_binding),
            active=active,
        ),
    )
    assigned = _assigned_coordinates(worker_index=worker_index, worker_count=worker_count)
    launch_authority_nonce = secrets.token_hex(32)
    persistent_evaluator: PersistentEvaluatorProcess | None = None
    new_cells = 0
    while True:
        if _stop_before_new_claim is not None and _stop_before_new_claim.is_set():
            break
        if max_new_cells is not None and new_cells >= max_new_cells:
            break
        claim_manager: Any | None = None
        claim_binding: Mapping[str, Any] | None = None
        claim_active = False
        coordinate: ShardCoordinate | None = None
        command: list[str] | None = None
        launch_nonce: str | None = None
        projected_shards = 0
        projected_token_rows = 0
        plan_coordinates: tuple[ShardCoordinate, ...] = ()
        blocked_after_commit = False
        with _exclusive_matrix_lock(
            layout.lock_path,
            matrix_summary=layout.matrix_summary,
            expected_binding=lock_binding,
        ):
            if _stop_before_new_claim is not None and _stop_before_new_claim.is_set():
                break
            ledgers, gpu_bindings = _load_worker_ledgers(
                output_root=layout.output_root,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                verify_bundles=False,
                expected_worker_index=worker_index,
                expected_gpu_lease_binding=current_gpu_binding,
            )
            current_records = ledgers.get(worker_index)
            if current_records is None:
                raise ValueError("Distributed worker ledger disappeared.")
            summary_payload, merged = _distributed_summary_from_ledgers(
                ledgers,
                output_root=layout.output_root,
                gpu_bindings=gpu_bindings,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
            )
            disk_summary_payload = _validate_distributed_disk_summary(
                layout=layout,
                expected_payload=summary_payload,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                expected_gpu_worker_leases=gpu_bindings,
                ready_only_preflight_gpu_lease_binding=current_gpu_binding,
            )
            active_claims = _preflight_distributed_output_tree(
                output_root=layout.output_root,
                matrix_summary=layout.matrix_summary,
                merged_records=merged,
                worker_count=worker_count,
            )
            _require(
                not any(_coordinate_worker_index(coordinates()[index], worker_count=worker_count)
                == worker_index
                for index in active_claims),
                "This distributed worker already owns a live cell claim.",
            )
            if len(current_records) == len(assigned):
                break
            coordinate = assigned[len(current_records)]
            remaining_limit = (
                None if max_new_cells is None else max_new_cells - new_cells
            )
            plan_coordinates = _persistent_plan_coordinates(
                assigned[len(current_records) :],
                max_new_cells_remaining=remaining_limit,
            )
            coordinate_index = coordinates().index(coordinate)
            _require(
                coordinate_index not in merged,
                "Distributed worker's next coordinate is already committed elsewhere.",
            )
            _headroom_preflight_with_attested_pause(
                output_root=layout.output_root,
                matrix_summary=layout.matrix_summary,
                storage_records=[merged[index] for index in sorted(merged)],
                coordinate=coordinate,
                current_payload=disk_summary_payload,
                resume_payload=summary_payload,
                worker_index=worker_index,
                active_claim_coordinate_indices=tuple(sorted(active_claims)),
                trust_root=prerequisites.trust_root,
            )
            _assert_empty_bundle(layout.output_root, coordinate)
            incomplete = [item for index, item in enumerate(coordinates()) if index not in merged]
            projected_shards = len(incomplete)
            projected_token_rows = projected_decode_token_rows(incomplete)
            inputs = prerequisites.bundles[
                (coordinate.scale, coordinate.training_seed, coordinate.budget)
            ]
            launch_nonce = secrets.token_hex(32)
            command = build_evaluator_command(
                evaluator_script=canonical,
                envelope_path=shard_envelope_path(layout.output_root, coordinate),
                manifest_path=prerequisites.context.manifest_path,
                coordinate=coordinate,
                inputs=inputs,
                launch_nonce=launch_nonce,
                gpu_lease_binding=cast(Mapping[str, Any], current_gpu_binding),
            )
            claim_manager = _exclusive_cell_claim(
                shard_output_dir(layout.output_root, coordinate),
                coordinate=coordinate,
                launch_nonce=launch_nonce,
                worker_index=worker_index,
                worker_count=worker_count,
            )
            claim_binding = cast(Mapping[str, Any], claim_manager.__enter__())
            _register_persistent_preparation_claim(
                cast(GPULockLease, current_gpu_lease), claim_manager
            )
            _assert_cell_claim_binding(claim_binding)
            claim_active = True

        try:
            _clear_persistent_preparation_claim(
                cast(GPULockLease, current_gpu_lease)
            )
            _require(
                coordinate is not None and command is not None and launch_nonce is not None,
                "Distributed claim preparation did not produce a launch.",
            )
            _require(claim_binding is not None, "Distributed cell claim binding is missing.")
            _assert_cell_claim_binding(claim_binding)
            admission.assert_quality_context_unchanged(prerequisites.context)
            if current_gpu_lease is None:
                raise ValueError("Distributed evaluator launch lacks its worker GPU lease.")
            active_gpu_lease = current_gpu_lease
            active_gpu_lease.assert_held()
            cast(GPULockLease, current_device_guard_lease).assert_held()
            if (
                persistent_evaluator is None
                or persistent_evaluator.closed
                or persistent_evaluator.cohort
                != (coordinate.scale, coordinate.training_seed)
                or len(persistent_evaluator.work_orders)
                == cast(int, persistent_evaluator.plan["coordinate_count"])
            ):
                if persistent_evaluator is not None and not persistent_evaluator.closed:
                    persistent_evaluator.close()
                persistent_evaluator = _start_persistent_evaluator(
                    canonical=canonical,
                    expected=evaluator_snapshot,
                    manifest_path=prerequisites.context.manifest_path,
                    inputs=prerequisites.bundles[
                        (coordinate.scale, coordinate.training_seed, coordinate.budget)
                    ],
                    first_coordinate=coordinate,
                    plan_coordinates=plan_coordinates,
                    max_new_cells_stop_limit=remaining_limit,
                    session_role=persistent_session.QUALITY_SESSION_ROLE,
                    launch_authority_nonce=launch_authority_nonce,
                    worker_index=worker_index,
                    worker_count=worker_count,
                    evaluator_binding=evaluator_binding,
                    prerequisites=prerequisites,
                    gpu_lease_binding=cast(Mapping[str, Any], current_gpu_binding),
                    gpu_lease=active_gpu_lease,
                    device_guard_lease=cast(GPULockLease, current_device_guard_lease),
                    output_root=layout.output_root,
                )
            active_session = persistent_evaluator
            _require(active_session is not None, "Persistent distributed session is missing.")
            sequence_index = len(active_session.work_orders)
            planned = cast(list[Mapping[str, Any]], active_session.plan["coordinates"])
            _require(
                sequence_index < len(planned)
                and planned[sequence_index] == coordinate.payload,
                "Persistent distributed session deviated from its sealed plan.",
            )
            work_order = persistent_session.build_work_order(
                active_session.plan,
                sequence_index=sequence_index,
                launch_nonce=launch_nonce,
                envelope_path=shard_envelope_path(layout.output_root, coordinate),
                projected_remaining_shards=projected_shards,
                projected_remaining_token_rows=projected_token_rows,
                trust_root=prerequisites.trust_root,
            )
            work_result = active_session.execute(work_order)
            active_gpu_lease.assert_held()
            cast(GPULockLease, current_device_guard_lease).assert_held()
            verification_fd, _ = _open_evaluator(canonical, expected=evaluator_snapshot)
            os.close(verification_fd)
            admission.assert_quality_context_unchanged(prerequisites.context)
            with _exclusive_matrix_lock(
                layout.lock_path,
                matrix_summary=layout.matrix_summary,
                expected_binding=lock_binding,
            ):
                ledgers, gpu_bindings = _load_worker_ledgers(
                    output_root=layout.output_root,
                    worker_count=worker_count,
                    prerequisites=prerequisites,
                    evaluator_script=canonical,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    verify_bundles=False,
                    expected_worker_index=worker_index,
                    expected_gpu_lease_binding=current_gpu_binding,
                )
                commit_records = ledgers.get(worker_index)
                if commit_records is None:
                    raise ValueError("Distributed worker ledger disappeared.")
                _summary_before, merged_before = _distributed_summary_from_ledgers(
                    ledgers,
                    output_root=layout.output_root,
                    gpu_bindings=gpu_bindings,
                    worker_count=worker_count,
                    prerequisites=prerequisites,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                )
                disk_summary_before = _validate_distributed_disk_summary(
                    layout=layout,
                    expected_payload=_summary_before,
                    worker_count=worker_count,
                    prerequisites=prerequisites,
                    evaluator_script=canonical,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    expected_gpu_worker_leases=gpu_bindings,
                    ready_only_preflight_gpu_lease_binding=current_gpu_binding,
                )
                active_claims = _preflight_distributed_output_tree(
                    output_root=layout.output_root,
                    matrix_summary=layout.matrix_summary,
                    merged_records=merged_before,
                    worker_count=worker_count,
                )
                coordinate_index = coordinates().index(coordinate)
                claim = active_claims.get(coordinate_index)
                _require(
                    claim is not None and claim.get("launch_nonce") == launch_nonce,
                    "Distributed cell claim changed before commit.",
                )
                envelope_path = shard_envelope_path(layout.output_root, coordinate)
                if not envelope_path.is_file():
                    if work_result is None:
                        active_session.finalize_eof(
                            published_bundle_reingested=False
                        )
                        persistent_evaluator = None
                    raise ValueError(
                        f"Evaluator did not publish its terminal envelope: {coordinate.key}."
                    )
                inputs = prerequisites.bundles[
                    (coordinate.scale, coordinate.training_seed, coordinate.budget)
                ]
                payload = load_and_validate_shard_bundle(
                    envelope_path,
                    coordinate=coordinate,
                    inputs=inputs,
                    launch_nonce=launch_nonce,
                    trust_root=prerequisites.trust_root,
                    gpu_lease_binding=cast(Mapping[str, Any], current_gpu_binding),
                    execution_environment_projection=cast(
                        Mapping[str, Any],
                        prerequisites.public_binding["execution_environment_projection"],
                    ),
                )
                decision = cast(str, payload["terminal_decision"])
                if work_result is not None:
                    _require(
                        work_result.get("terminal_decision") == decision,
                        "Persistent child result differs from its shard envelope.",
                    )
                    _require(
                        work_result.get("envelope_binding")
                        == _file_binding(envelope_path, payload=payload),
                        "Persistent child envelope binding differs from the parent-opened envelope.",
                    )
                persistent_execution = _persistent_execution_payload(
                    plan=active_session.plan,
                    session_command=active_session.command,
                    work_order=work_order,
                    work_result=work_result,
                    published_bundle_reingested_after_child_eof=(work_result is None),
                )
                record = _run_record(
                    payload,
                    coordinate=coordinate,
                    envelope_path=envelope_path,
                    inputs=inputs,
                    launch_nonce=launch_nonce,
                    command=command,
                    persistent_execution=persistent_execution,
                )
                if work_result is not None:
                    _require(
                        cast(Mapping[str, Any], record["artifact_bundle"])["envelope"]
                        == work_result["envelope_binding"],
                        "Persistent envelope changed while constructing its matrix record.",
                    )
                _require(
                    len(commit_records) < len(assigned)
                    and assigned[len(commit_records)] == coordinate
                    and coordinate_index not in merged_before,
                    "Distributed worker ledger advanced during its cell execution.",
                )
                active_gpu_lease.assert_held()
                cast(GPULockLease, current_device_guard_lease).assert_held()
                _assert_cell_claim_binding(claim_binding)
                claim_active = False
                cast(Any, claim_manager).__exit__(None, None, None)
                _require(
                    not os.path.lexists(Path(cast(str, claim_binding["path"]))),
                    "Distributed cell claim survived validated release before commit.",
                )
                claim_path = Path(cast(str, claim_binding["path"]))
                prior_records = list(commit_records)
                prior_worker_payload = _worker_payload(
                    prior_records,
                    worker_index=worker_index,
                    worker_count=worker_count,
                    prerequisites=prerequisites,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    gpu_lease_binding=cast(Mapping[str, Any], current_gpu_binding),
                )
                commit_records.append(record)
                worker_path = _worker_ledger_path(
                    layout.output_root,
                    worker_index=worker_index,
                    worker_count=worker_count,
                )
                try:
                    _atomic_write_json(
                        worker_path,
                        _worker_payload(
                            commit_records,
                            worker_index=worker_index,
                            worker_count=worker_count,
                            prerequisites=prerequisites,
                            evaluator_binding=evaluator_binding,
                            matrix_lock_binding=lock_binding,
                            gpu_lease_binding=cast(Mapping[str, Any], current_gpu_binding),
                        ),
                    )
                    _require(
                        not os.path.lexists(claim_path),
                        "Distributed cell claim reappeared during worker-ledger commit.",
                    )
                    ledgers[worker_index] = commit_records
                    gpu_bindings[worker_index] = dict(cast(Mapping[str, Any], current_gpu_binding))
                    summary_payload, _merged_after = _distributed_summary_from_ledgers(
                        ledgers,
                        output_root=layout.output_root,
                        gpu_bindings=gpu_bindings,
                        worker_count=worker_count,
                        prerequisites=prerequisites,
                        evaluator_binding=evaluator_binding,
                        matrix_lock_binding=lock_binding,
                    )
                    if len(_merged_after) == EXPECTED_SHARDS:
                        terminal_ledgers, terminal_gpu_bindings = _load_worker_ledgers(
                            output_root=layout.output_root,
                            worker_count=worker_count,
                            prerequisites=prerequisites,
                            evaluator_script=canonical,
                            evaluator_binding=evaluator_binding,
                            matrix_lock_binding=lock_binding,
                            verify_bundles=True,
                            expected_worker_index=worker_index,
                            expected_gpu_lease_binding=current_gpu_binding,
                        )
                        summary_payload, _merged_after = _distributed_summary_from_ledgers(
                            terminal_ledgers,
                            output_root=layout.output_root,
                            gpu_bindings=terminal_gpu_bindings,
                            worker_count=worker_count,
                            prerequisites=prerequisites,
                            evaluator_binding=evaluator_binding,
                            matrix_lock_binding=lock_binding,
                        )
                        _require(
                            summary_payload["status"]
                            in {"awaiting_session_terminal", "terminal"}
                            and len(_merged_after) == EXPECTED_SHARDS,
                            "Full-coordinate coordinator replay lost a worker record.",
                        )
                    remaining_active_claims = _preflight_distributed_output_tree(
                        output_root=layout.output_root,
                        matrix_summary=layout.matrix_summary,
                        merged_records=_merged_after,
                        worker_count=worker_count,
                    )
                    published_payload = summary_payload
                    if disk_summary_before.get("status") in {
                        "paused_infrastructure",
                        "draining_infrastructure",
                    }:
                        published_payload = _rebind_infrastructure_after_commit(
                            prior_blocked_payload=disk_summary_before,
                            resume_payload=summary_payload,
                            ledgers=ledgers,
                            merged_records=_merged_after,
                            active_claim_coordinate_indices=tuple(sorted(remaining_active_claims)),
                            output_root=layout.output_root,
                            worker_count=worker_count,
                            trust_root=prerequisites.trust_root,
                        )
                    blocked_after_commit = published_payload.get("status") in {
                        "paused_infrastructure",
                        "draining_infrastructure",
                    }
                    _atomic_write_json(layout.matrix_summary, published_payload)
                    _require(
                        not os.path.lexists(claim_path),
                        "Distributed cell claim reappeared during authoritative commit.",
                    )
                    verified_active_claims = _preflight_distributed_output_tree(
                        output_root=layout.output_root,
                        matrix_summary=layout.matrix_summary,
                        merged_records=_merged_after,
                        worker_count=worker_count,
                    )
                    _require(
                        set(verified_active_claims) == set(remaining_active_claims),
                        "Distributed active claims changed during authoritative commit.",
                    )
                    active_gpu_lease.assert_held()
                    cast(GPULockLease, current_device_guard_lease).assert_held()
                except BaseException:
                    _atomic_write_json(worker_path, prior_worker_payload)
                    _atomic_write_json(layout.matrix_summary, disk_summary_before)
                    raise
                if work_result is None:
                    active_session.finalize_eof(
                        published_bundle_reingested=True
                    )
                    persistent_evaluator = None
                else:
                    active_session.mark_committed(
                        work_order=work_order, work_result=work_result
                    )
            new_cells += 1
            if blocked_after_commit:
                break
        except BaseException as error:
            if claim_active:
                with _exclusive_matrix_lock(
                    layout.lock_path,
                    matrix_summary=layout.matrix_summary,
                    expected_binding=lock_binding,
                ):
                    claim_active = False
                    cast(Any, claim_manager).__exit__(type(error), error, error.__traceback__)
            raise

    if persistent_evaluator is not None:
        if not persistent_evaluator.closed:
            persistent_evaluator.close()
        elif not persistent_evaluator.terminal_published:
            persistent_evaluator.finalize_eof(published_bundle_reingested=False)

    with _exclusive_matrix_lock(
        layout.lock_path,
        matrix_summary=layout.matrix_summary,
        expected_binding=lock_binding,
    ):
        ledgers, gpu_bindings = _load_worker_ledgers(
            output_root=layout.output_root,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_script=canonical,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=lock_binding,
            verify_bundles=False,
            expected_worker_index=worker_index,
            expected_gpu_lease_binding=current_gpu_binding,
        )
        terminal_or_prefix, merged = _distributed_summary_from_ledgers(
            ledgers,
            output_root=layout.output_root,
            gpu_bindings=gpu_bindings,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=lock_binding,
        )
        if terminal_or_prefix.get("status") == "terminal":
            terminal_ledgers, terminal_gpu_bindings = _load_worker_ledgers(
                output_root=layout.output_root,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                verify_bundles=True,
                expected_worker_index=worker_index,
                expected_gpu_lease_binding=current_gpu_binding,
            )
            terminal_or_prefix, merged = _distributed_summary_from_ledgers(
                terminal_ledgers,
                output_root=layout.output_root,
                gpu_bindings=terminal_gpu_bindings,
                worker_count=worker_count,
                prerequisites=prerequisites,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
            )
            _require(
                terminal_or_prefix.get("status") == "terminal"
                and len(merged) == EXPECTED_SHARDS,
                "Distributed terminalization requires an exact full bundle replay.",
            )
            ledgers = terminal_ledgers
            gpu_bindings = terminal_gpu_bindings
        disk_terminal_or_prefix = _validate_distributed_disk_summary(
            layout=layout,
            expected_payload=terminal_or_prefix,
            worker_count=worker_count,
            prerequisites=prerequisites,
            evaluator_script=canonical,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=lock_binding,
            expected_gpu_worker_leases=gpu_bindings,
            ready_only_preflight_gpu_lease_binding=current_gpu_binding,
        )
        final_active_claims = _preflight_distributed_output_tree(
            output_root=layout.output_root,
            matrix_summary=layout.matrix_summary,
            merged_records=merged,
            worker_count=worker_count,
        )
        if disk_terminal_or_prefix.get("status") == "draining_infrastructure":
            drain = cast(Mapping[str, Any], disk_terminal_or_prefix["infrastructure_drain"])
            _require(
                drain.get("active_claim_coordinate_indices") == sorted(final_active_claims),
                "Infrastructure drain does not bind the exact live claim inventory.",
            )
        elif disk_terminal_or_prefix.get("status") == "paused_infrastructure":
            _require(
                not final_active_claims,
                "Infrastructure pause may not coexist with live distributed claims.",
            )
        else:
            _atomic_write_json(layout.matrix_summary, terminal_or_prefix)
        validate_matrix_summary(
            disk_terminal_or_prefix,
            output_root=layout.output_root,
            prerequisites=prerequisites,
            evaluator_script=canonical,
            evaluator_binding=evaluator_binding,
            matrix_lock_binding=lock_binding,
            verify_bundles=False,
            expected_worker_count=worker_count,
            expected_gpu_worker_leases=gpu_bindings,
            ready_only_preflight_gpu_lease_binding=current_gpu_binding,
        )
        return disk_terminal_or_prefix


def _run_same_gpu_supervisor(
    *,
    layout: MatrixLayout,
    manifest_path: Path,
    evaluator_script: Path,
    attestation_key_path: Path | None,
    start_mode: str,
    max_new_cells: int | None,
    worker_count: int,
    gpu_lock_path: Path,
) -> dict[str, Any]:
    """Own one physical GPU lease and coordinate disjoint local worker threads."""

    _require(
        2 <= worker_count <= 4,
        "Same-GPU full17 supervisor requires two to four frozen workers.",
    )
    _require(
        (start_mode == "fresh" and max_new_cells == 1)
        or (start_mode == "resume" and max_new_cells is None),
        "Same-GPU supervisor received an invalid start/stop boundary.",
    )
    canonical = _canonical_evaluator(evaluator_script)
    scheduler_owner = acquire_gpu_lock(
        f"p2-direct-controller-exact-fill-v1-3-5-supervisor-{worker_count}",
        path=gpu_lock_path,
    )
    with ExitStack() as execution_stack:
        execution_stack.callback(admission.close_gpu_lock_owner, scheduler_owner)
        scheduler_owner.assert_held()
        fresh_prestart_authority: tuple[
            ValidatedBasePrerequisites,
            admission.PrestartQualityAuthorityV1_3_5,
        ] | None = None
        resume_initial_prerequisites: FrozenPrerequisites | None = None
        if start_mode == "fresh":
            fresh_prestart_authority = load_and_validate_prestart_prerequisites(
                manifest_path=manifest_path,
                training_output_root=layout.training_output_root,
                calibration_output_root=layout.calibration_output_root,
                reuse_admission_path=layout.reuse_admission_path,
                preheldout_genesis_path=layout.preheldout_genesis_path,
                output_root=layout.output_root,
                attestation_key_path=attestation_key_path,
                worker_count=worker_count,
            )
        else:
            resume_initial_prerequisites = load_and_validate_prerequisites(
                manifest_path=manifest_path,
                training_output_root=layout.training_output_root,
                calibration_output_root=layout.calibration_output_root,
                reuse_admission_path=layout.reuse_admission_path,
                preheldout_genesis_path=layout.preheldout_genesis_path,
                output_root=layout.output_root,
                attestation_key_path=attestation_key_path,
                expected_worker_count=worker_count,
            )
        device_context = _capture_selected_device_context(scheduler_owner)
        device_guard_path = canonical_device_guard_path(
            cast(
                Mapping[str, Any],
                device_context["selected_device_routing_identity"],
            )
        )
        _validate_quality_mutating_lock_path(
            device_guard_path,
            layout=layout,
            manifest_path=manifest_path,
            attestation_key_path=attestation_key_path,
            label="GPU physical-device guard",
            require_canonical_scheduler=False,
        )
        device_guard_owner = _acquire_selected_device_guard(
            label=f"p2-direct-controller-exact-fill-v1-3-5-supervisor-{worker_count}",
            device_context=device_context,
            scheduler_lease=scheduler_owner,
        )
        if device_guard_owner is not scheduler_owner:
            execution_stack.callback(admission.close_gpu_lock_owner, device_guard_owner)
        device_guard_owner.assert_held()
        execution_stack.push(
            lambda exc_type, error, traceback: (
                _settle_active_persistent_evaluator_scope(
                    scheduler_owner,
                    exc_type,
                    error,
                    traceback,
                )
            )
        )
        prerequisites, activation_lease = _prepare_quality_start_authority(
            start_mode=start_mode,
            layout=layout,
            manifest_path=manifest_path,
            attestation_key_path=attestation_key_path,
            worker_count=worker_count,
            scheduler_lease=scheduler_owner,
            fresh_prestart=fresh_prestart_authority,
            resume_initial=resume_initial_prerequisites,
        )
        execution_stack.callback(activation_lease.close)
        lock_binding = _activation_lock_binding(prerequisites, activation_lease)
        admission.assert_quality_context_unchanged(prerequisites.context)
        scheduler_owner.assert_held()
        device_guard_owner.assert_held()
        device_context = _validate_selected_device_context(
            device_context,
            prerequisites=prerequisites,
        )
        _require(
            EVALUATOR_IMPLEMENTATION_PATH in contract.V1_3_5_IMPLEMENTATION_PATHS
            and GPU_LOCK_IMPLEMENTATION_PATH in contract.V1_3_5_IMPLEMENTATION_PATHS,
            "Canonical evaluator or GPU lease helper is absent from v1.3.5.",
        )
        _require(
            contract.v1_3_5_implementation_tree_digest()
            == prerequisites.context.manifest_binding["implementation_digest"],
            "Canonical evaluator differs from the v1.3.5 manifest.",
        )
        evaluator_fd, evaluator_snapshot = _open_evaluator(canonical)
        os.close(evaluator_fd)
        evaluator_binding = evaluator_snapshot.public_binding
        supervisor_gpu_binding = _gpu_lease_binding(
            scheduler_owner,
            device_guard_lease=device_guard_owner,
            device_context=device_context,
        )
        ready_only_preflight = _ensure_ready_only_preflight(
            start_mode=start_mode,
            layout=layout,
            manifest_path=prerequisites.context.manifest_path,
            canonical=canonical,
            evaluator_snapshot=evaluator_snapshot,
            evaluator_binding=evaluator_binding,
            prerequisites=prerequisites,
            activation_lease=activation_lease,
            launch_authority_nonce=secrets.token_hex(32),
            gpu_lease_binding=supervisor_gpu_binding,
            gpu_lease=scheduler_owner,
            device_guard_lease=device_guard_owner,
        )
        _complete_activation_ledger_boundary(
            start_mode=start_mode,
            layout=layout,
            prerequisites=prerequisites,
            activation_lease=activation_lease,
            evaluator_binding=evaluator_binding,
            ready_only_preflight=ready_only_preflight,
            worker_count=worker_count,
            gpu_lease_binding=supervisor_gpu_binding,
        )
        activation_lease.close()
        scheduler_owner.assert_held()
        device_guard_owner.assert_held()

        def run_worker(
            worker_index: int,
            scheduler: GPULockLease,
            guard: GPULockLease,
            drain_event: threading.Event,
        ) -> Mapping[str, Any]:
            scheduler.assert_held()
            guard.assert_held()
            worker_binding = _gpu_lease_binding(
                scheduler,
                device_guard_lease=guard,
                device_context=device_context,
            )
            return _run_distributed_matrix(
                layout=layout,
                manifest_path=manifest_path,
                evaluator_script=evaluator_script,
                attestation_key_path=attestation_key_path,
                start_mode=start_mode,
                max_new_cells=max_new_cells,
                worker_index=worker_index,
                worker_count=worker_count,
                coordinator_only=False,
                gpu_lock_path=gpu_lock_path,
                _stop_before_new_claim=drain_event,
                _prepared=(
                    canonical,
                    lock_binding,
                    prerequisites,
                    evaluator_snapshot,
                    evaluator_binding,
                    scheduler,
                    guard,
                    worker_binding,
                ),
            )

        if start_mode == "fresh":
            scheduler = admission.borrow_gpu_lock_lease(scheduler_owner)
            guard = (
                scheduler
                if device_guard_owner is scheduler_owner
                else admission.borrow_gpu_lock_lease(device_guard_owner)
            )
            try:
                result = dict(run_worker(0, scheduler, guard, threading.Event()))
            finally:
                _close_gpu_lease_pair(scheduler, guard)
            scheduler_owner.assert_held()
            device_guard_owner.assert_held()
            return result

        _run_same_gpu_worker_group(
            worker_count=worker_count,
            scheduler_owner=scheduler_owner,
            device_guard_owner=device_guard_owner,
            run_worker=run_worker,
        )
        scheduler_owner.assert_held()
        device_guard_owner.assert_held()
        return _run_distributed_matrix(
            layout=layout,
            manifest_path=manifest_path,
            evaluator_script=evaluator_script,
            attestation_key_path=attestation_key_path,
            start_mode=start_mode,
            max_new_cells=None,
            worker_index=0,
            worker_count=worker_count,
            coordinator_only=True,
            gpu_lock_path=gpu_lock_path,
            _prepared=(
                canonical,
                lock_binding,
                prerequisites,
                evaluator_snapshot,
                evaluator_binding,
                None,
                None,
                None,
            ),
        )


def run_matrix(
    *,
    manifest_path: Path = contract.V1_3_5_MANIFEST_PATH,
    training_output_root: Path = TRAINING_OUTPUT_ROOT,
    calibration_output_root: Path = CALIBRATION_OUTPUT_ROOT,
    reuse_admission_path: Path = REUSE_ADMISSION_PATH,
    preheldout_genesis_path: Path = PREHELDOUT_GENESIS_PATH,
    output_root: Path = OUTPUT_ROOT,
    matrix_summary: Path | None = None,
    evaluator_script: Path = EVALUATOR_SCRIPT,
    attestation_key_path: Path | None = None,
    start_mode: str,
    max_new_cells: int | None = None,
    worker_index: int = 0,
    worker_count: int = 1,
    coordinator_only: bool = False,
    gpu_lock_path: Path = DEFAULT_GPU_LOCK_PATH,
) -> dict[str, Any]:
    _require_launcher_authority()
    _require(
        start_mode in QUALITY_START_MODES,
        "Explicit quality start mode is required.",
    )
    _require(
        (start_mode == "fresh" and max_new_cells == 1)
        or (start_mode in {"resume", "prerequisites-only"} and max_new_cells is None),
        "Fresh requires exactly one new cell; resume/prerequisites-only forbid a stop limit.",
    )
    if max_new_cells is not None:
        _require(
            type(max_new_cells) is int and max_new_cells > 0,
            "max-new-cells must be a positive integer.",
        )
    key_path_for_layout = attestation_key_path
    if key_path_for_layout is None and os.environ.get(attestation.KEY_PATH_ENV):
        key_path_for_layout = Path(os.environ[attestation.KEY_PATH_ENV])
    requested_summary = (
        output_root / MATRIX_SUMMARY_NAME if matrix_summary is None else matrix_summary
    )
    layout = _validate_matrix_layout(
        output_root=output_root,
        matrix_summary=requested_summary,
        training_output_root=training_output_root,
        calibration_output_root=calibration_output_root,
        reuse_admission_path=reuse_admission_path,
        preheldout_genesis_path=preheldout_genesis_path,
        attestation_key_path=key_path_for_layout,
    )
    _require(
        not _paths_overlap(
            _absolute(gpu_lock_path).resolve(strict=False),
            _absolute(calibration_matrix.SUPERSEDED_OUTPUT_ROOT).resolve(strict=False),
        ),
        "Controller GPU lock may not overlap the immutable calibration quarantine.",
    )
    _require(
        type(worker_count) is int and worker_count >= 1,
        "worker-count must be a positive integer.",
    )
    _require(
        type(worker_index) is int and 0 <= worker_index < worker_count,
        "worker-index is outside worker-count.",
    )
    _require(
        1 <= worker_count <= 4 and worker_index == 0 and not coordinator_only,
        "Controller v1.3.5 requires one supervisor and one to four frozen same-GPU workers.",
    )
    _validate_quality_mutating_lock_path(
        gpu_lock_path,
        layout=layout,
        manifest_path=manifest_path,
        attestation_key_path=key_path_for_layout,
        label="GPU scheduler lock",
        require_canonical_scheduler=True,
    )
    if start_mode == "prerequisites-only":
        base, prestart = load_and_validate_prestart_prerequisites(
            manifest_path=manifest_path,
            training_output_root=layout.training_output_root,
            calibration_output_root=layout.calibration_output_root,
            reuse_admission_path=layout.reuse_admission_path,
            preheldout_genesis_path=layout.preheldout_genesis_path,
            output_root=layout.output_root,
            attestation_key_path=attestation_key_path,
            worker_count=worker_count,
        )
        return {
            "experiment_id": EXPERIMENT_ID,
            "status": "prerequisites_validated",
            "integrity_status": None,
            "completed_shards": 0,
            "canonical_prefix_shards": 0,
            "expected_shards": EXPECTED_SHARDS,
            "storage": None,
            "prerequisites": dict(base.public_binding),
            "prestart_absence_witness": dict(prestart.absence_witness),
        }
    _require(
        start_mode != "fresh"
        or (worker_index == 0 and not coordinator_only),
        "Fresh activation requires an executing worker 0.",
    )
    if worker_count > 1:
        return _run_same_gpu_supervisor(
            layout=layout,
            manifest_path=manifest_path,
            evaluator_script=evaluator_script,
            attestation_key_path=attestation_key_path,
            start_mode=start_mode,
            max_new_cells=max_new_cells,
            worker_count=worker_count,
            gpu_lock_path=gpu_lock_path,
        )
    _require(worker_index == 0, "Single-worker execution requires worker-index 0.")
    _require(
        not _worker_ledger_root(layout.output_root).exists(),
        "Single-worker execution refuses an existing distributed worker-ledger root.",
    )
    canonical = _canonical_evaluator(evaluator_script)
    gpu_lease = acquire_gpu_lock("p2-direct-controller-exact-fill-v1-3-5-matrix-single", path=gpu_lock_path)
    with ExitStack() as execution_stack:
        execution_stack.callback(gpu_lease.close)
        gpu_lease.assert_held()
        fresh_prestart_authority: tuple[
            ValidatedBasePrerequisites,
            admission.PrestartQualityAuthorityV1_3_5,
        ] | None = None
        resume_initial_prerequisites: FrozenPrerequisites | None = None
        if start_mode == "fresh":
            fresh_prestart_authority = load_and_validate_prestart_prerequisites(
                manifest_path=manifest_path,
                training_output_root=layout.training_output_root,
                calibration_output_root=layout.calibration_output_root,
                reuse_admission_path=layout.reuse_admission_path,
                preheldout_genesis_path=layout.preheldout_genesis_path,
                output_root=layout.output_root,
                attestation_key_path=attestation_key_path,
                worker_count=1,
            )
        else:
            resume_initial_prerequisites = load_and_validate_prerequisites(
                manifest_path=manifest_path,
                training_output_root=layout.training_output_root,
                calibration_output_root=layout.calibration_output_root,
                reuse_admission_path=layout.reuse_admission_path,
                preheldout_genesis_path=layout.preheldout_genesis_path,
                output_root=layout.output_root,
                attestation_key_path=attestation_key_path,
                expected_worker_count=1,
            )
        device_context = _capture_selected_device_context(gpu_lease)
        device_guard_path = canonical_device_guard_path(
            cast(
                Mapping[str, Any],
                device_context["selected_device_routing_identity"],
            )
        )
        _validate_quality_mutating_lock_path(
            device_guard_path,
            layout=layout,
            manifest_path=manifest_path,
            attestation_key_path=key_path_for_layout,
            label="GPU physical-device guard",
            require_canonical_scheduler=False,
        )
        device_guard_lease = _acquire_selected_device_guard(
            label="p2-direct-controller-exact-fill-v1-3-5-matrix-single",
            device_context=device_context,
            scheduler_lease=gpu_lease,
        )
        if device_guard_lease is not gpu_lease:
            execution_stack.callback(device_guard_lease.close)
        device_guard_lease.assert_held()
        execution_stack.push(
            lambda exc_type, error, traceback: (
                _settle_active_persistent_evaluator_scope(
                    gpu_lease, exc_type, error, traceback
                )
            )
        )
        prerequisites, activation_lease = _prepare_quality_start_authority(
            start_mode=start_mode,
            layout=layout,
            manifest_path=manifest_path,
            attestation_key_path=attestation_key_path,
            worker_count=1,
            scheduler_lease=gpu_lease,
            fresh_prestart=fresh_prestart_authority,
            resume_initial=resume_initial_prerequisites,
        )
        execution_stack.callback(activation_lease.close)
        lock_binding = _activation_lock_binding(
            prerequisites, activation_lease
        )
        admission.assert_quality_context_unchanged(prerequisites.context)
        gpu_lease.assert_held()
        device_guard_lease.assert_held()
        device_context = _validate_selected_device_context(
            device_context, prerequisites=prerequisites
        )
        _require(
            EVALUATOR_IMPLEMENTATION_PATH in contract.V1_3_5_IMPLEMENTATION_PATHS
            and GPU_LOCK_IMPLEMENTATION_PATH in contract.V1_3_5_IMPLEMENTATION_PATHS,
            "Canonical evaluator or GPU lease helper is absent from the frozen inventory.",
        )
        _require(
            contract.v1_3_5_implementation_tree_digest()
            == prerequisites.context.manifest_binding["implementation_digest"],
            "Canonical evaluator is not bound by the frozen manifest.",
        )
        evaluator_fd, evaluator_snapshot = _open_evaluator(canonical)
        os.close(evaluator_fd)
        evaluator_binding = evaluator_snapshot.public_binding
        gpu_binding = _gpu_lease_binding(
            gpu_lease,
            device_guard_lease=device_guard_lease,
            device_context=device_context,
        )
        preflight_launch_authority_nonce = secrets.token_hex(32)
        ready_only_preflight = _ensure_ready_only_preflight(
            start_mode=start_mode,
            layout=layout,
            manifest_path=prerequisites.context.manifest_path,
            canonical=canonical,
            evaluator_snapshot=evaluator_snapshot,
            evaluator_binding=evaluator_binding,
            prerequisites=prerequisites,
            activation_lease=activation_lease,
            launch_authority_nonce=preflight_launch_authority_nonce,
            gpu_lease_binding=gpu_binding,
            gpu_lease=gpu_lease,
            device_guard_lease=device_guard_lease,
        )
        activation_boundary = _complete_activation_ledger_boundary(
            start_mode=start_mode,
            layout=layout,
            prerequisites=prerequisites,
            activation_lease=activation_lease,
            evaluator_binding=evaluator_binding,
            ready_only_preflight=ready_only_preflight,
            worker_count=1,
            gpu_lease_binding=gpu_binding,
        )
        activation_boundary_completed = activation_boundary.get(
            "completed_shards"
        )
        _require(
            type(activation_boundary_completed) is int
            and 0 <= activation_boundary_completed <= EXPECTED_SHARDS,
            "Activation-bound matrix prefix count is invalid.",
        )
        operational_prefix_only = activation_boundary_completed == 0
        activation_lease.close()
        completed: list[dict[str, Any]] = []
        with _exclusive_matrix_lock(
            layout.lock_path,
            matrix_summary=layout.matrix_summary,
            expected_binding=lock_binding,
        ):
            _require(
                not _worker_ledger_root(layout.output_root).exists(),
                "Single-worker execution refuses an existing distributed worker-ledger root.",
            )
            if layout.matrix_summary.exists():
                initial_disk_payload = _load_json_nofollow(
                    layout.matrix_summary, label="controller matrix ledger"
                )
                completed = validate_matrix_summary(
                    initial_disk_payload,
                    output_root=layout.output_root,
                    prerequisites=prerequisites,
                    evaluator_script=canonical,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    verify_bundles=True,
                    expected_gpu_worker_leases={0: gpu_binding},
                    allow_stale_session_ledger_watermark=True,
                )
                gpu_lease.assert_held()
                device_guard_lease.assert_held()
                _reconcile_committed_sessions_with_terminal_authority(
                    layout.output_root,
                    completed,
                    worker_index=0,
                    canonical=canonical,
                    evaluator_snapshot=evaluator_snapshot,
                    prerequisites=prerequisites,
                    gpu_binding=gpu_binding,
                    gpu_lease=gpu_lease,
                    device_guard_lease=device_guard_lease,
                )
                gpu_lease.assert_held()
                device_guard_lease.assert_held()
                initial_current_payload = _matrix_payload(
                    completed,
                    output_root=layout.output_root,
                    prerequisites=prerequisites,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    gpu_worker_leases={0: gpu_binding},
                )
                _refresh_matrix_session_projection(
                    disk_payload=initial_disk_payload,
                    current_resume_payload=initial_current_payload,
                    matrix_summary=layout.matrix_summary,
                    trust_root=prerequisites.trust_root,
                )
            _preflight_output_tree(
                output_root=layout.output_root,
                matrix_summary=layout.matrix_summary,
                completed_shards=len(completed),
            )
            admission.assert_quality_context_unchanged(prerequisites.context)
            verification_fd, _ = _open_evaluator(canonical, expected=evaluator_snapshot)
            os.close(verification_fd)
            if not layout.matrix_summary.exists():
                _atomic_write_json(
                    layout.matrix_summary,
                    _matrix_payload(
                        completed,
                        output_root=layout.output_root,
                        prerequisites=prerequisites,
                        evaluator_binding=evaluator_binding,
                        matrix_lock_binding=lock_binding,
                        gpu_worker_leases={0: gpu_binding},
                    ),
                )

        if activation_boundary_completed == 1:
            _assert_one_cell_full_resume_gate(completed)
        _register_persistent_projection_refresher(
            gpu_lease,
            lambda active: _refresh_single_scope_session_projection(
                layout=layout,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                gpu_binding=gpu_binding,
                active=active,
            ),
        )
        launch_authority_nonce = secrets.token_hex(32)
        persistent_evaluator: PersistentEvaluatorProcess | None = None
        new_cells = 0
        while len(completed) < len(coordinates()):
            if operational_prefix_only and len(completed) >= 1:
                break
            if max_new_cells is not None and new_cells >= max_new_cells:
                break
            claim_manager: Any | None = None
            claim_binding: Mapping[str, Any] | None = None
            claim_active = False
            coordinate = coordinates()[len(completed)]
            remaining_limit = (
                1 - new_cells
                if operational_prefix_only
                else None
                if max_new_cells is None
                else max_new_cells - new_cells
            )
            plan_coordinates = _persistent_plan_coordinates(
                coordinates()[len(completed) :],
                max_new_cells_remaining=remaining_limit,
            )
            inputs = prerequisites.bundles[
                (coordinate.scale, coordinate.training_seed, coordinate.budget)
            ]
            launch_nonce = secrets.token_hex(32)
            envelope_path = shard_envelope_path(layout.output_root, coordinate)
            command = build_evaluator_command(
                evaluator_script=canonical,
                envelope_path=envelope_path,
                manifest_path=prerequisites.context.manifest_path,
                coordinate=coordinate,
                inputs=inputs,
                launch_nonce=launch_nonce,
                gpu_lease_binding=gpu_binding,
            )
            with _exclusive_matrix_lock(
                layout.lock_path,
                matrix_summary=layout.matrix_summary,
                expected_binding=lock_binding,
            ):
                disk_payload = _load_json_nofollow(
                    layout.matrix_summary, label="controller matrix ledger"
                )
                disk_completed = validate_matrix_summary(
                    disk_payload,
                    output_root=layout.output_root,
                    prerequisites=prerequisites,
                    evaluator_script=canonical,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    verify_bundles=False,
                    expected_gpu_worker_leases={0: gpu_binding},
                )
                _require(
                    disk_completed == completed,
                    "Single-worker matrix advanced during cell preparation.",
                )
                _preflight_output_tree(
                    output_root=layout.output_root,
                    matrix_summary=layout.matrix_summary,
                    completed_shards=len(completed),
                )
                admission.assert_quality_context_unchanged(prerequisites.context)
                resume_payload = _matrix_payload(
                    completed,
                    output_root=layout.output_root,
                    prerequisites=prerequisites,
                    evaluator_binding=evaluator_binding,
                    matrix_lock_binding=lock_binding,
                    gpu_worker_leases={0: gpu_binding},
                )
                disk_payload = _refresh_matrix_session_projection(
                    disk_payload=disk_payload,
                    current_resume_payload=resume_payload,
                    matrix_summary=layout.matrix_summary,
                    trust_root=prerequisites.trust_root,
                )
                _headroom_preflight_with_attested_pause(
                    output_root=layout.output_root,
                    matrix_summary=layout.matrix_summary,
                    storage_records=completed,
                    coordinate=coordinate,
                    current_payload=disk_payload,
                    resume_payload=resume_payload,
                    worker_index=0,
                    trust_root=prerequisites.trust_root,
                )
                _assert_empty_bundle(layout.output_root, coordinate)
                claim_manager = _exclusive_cell_claim(
                    shard_output_dir(layout.output_root, coordinate),
                    coordinate=coordinate,
                    launch_nonce=launch_nonce,
                )
                claim_binding = cast(Mapping[str, Any], claim_manager.__enter__())
                _register_persistent_preparation_claim(gpu_lease, claim_manager)
                _assert_cell_claim_binding(claim_binding)
                claim_active = True

            try:
                _clear_persistent_preparation_claim(gpu_lease)
                _require(claim_binding is not None, "Single-worker cell claim binding is missing.")
                _assert_cell_claim_binding(claim_binding)
                gpu_lease.assert_held()
                if (
                    persistent_evaluator is None
                    or persistent_evaluator.closed
                    or persistent_evaluator.cohort
                    != (coordinate.scale, coordinate.training_seed)
                    or len(persistent_evaluator.work_orders)
                    == cast(int, persistent_evaluator.plan["coordinate_count"])
                ):
                    if persistent_evaluator is not None and not persistent_evaluator.closed:
                        persistent_evaluator.close()
                    persistent_evaluator = _start_persistent_evaluator(
                        canonical=canonical,
                        expected=evaluator_snapshot,
                        manifest_path=prerequisites.context.manifest_path,
                        inputs=inputs,
                        first_coordinate=coordinate,
                        plan_coordinates=plan_coordinates,
                        max_new_cells_stop_limit=remaining_limit,
                        session_role=persistent_session.QUALITY_SESSION_ROLE,
                        launch_authority_nonce=launch_authority_nonce,
                        worker_index=0,
                        worker_count=1,
                        evaluator_binding=evaluator_binding,
                        prerequisites=prerequisites,
                        gpu_lease_binding=gpu_binding,
                        gpu_lease=gpu_lease,
                        device_guard_lease=device_guard_lease,
                        output_root=layout.output_root,
                    )
                active_session = persistent_evaluator
                _require(active_session is not None, "Persistent single-worker session is missing.")
                sequence_index = len(active_session.work_orders)
                planned = cast(list[Mapping[str, Any]], active_session.plan["coordinates"])
                _require(
                    sequence_index < len(planned)
                    and planned[sequence_index] == coordinate.payload,
                    "Persistent single-worker session deviated from its sealed plan.",
                )
                projected_shards = EXPECTED_SHARDS - len(completed)
                projected_token_rows = projected_decode_token_rows(
                    coordinates()[len(completed) :]
                )
                work_order = persistent_session.build_work_order(
                    active_session.plan,
                    sequence_index=sequence_index,
                    launch_nonce=launch_nonce,
                    envelope_path=envelope_path,
                    projected_remaining_shards=projected_shards,
                    projected_remaining_token_rows=projected_token_rows,
                    trust_root=prerequisites.trust_root,
                )
                work_result = active_session.execute(work_order)
                gpu_lease.assert_held()
                device_guard_lease.assert_held()
                admission.assert_quality_context_unchanged(prerequisites.context)
                _assert_cell_claim_binding(claim_binding)
                with _exclusive_matrix_lock(
                    layout.lock_path,
                    matrix_summary=layout.matrix_summary,
                    expected_binding=lock_binding,
                ):
                    execution_disk_payload = _load_json_nofollow(
                        layout.matrix_summary, label="controller matrix ledger"
                    )
                    disk_completed = validate_matrix_summary(
                        execution_disk_payload,
                        output_root=layout.output_root,
                        prerequisites=prerequisites,
                        evaluator_script=canonical,
                        evaluator_binding=evaluator_binding,
                        matrix_lock_binding=lock_binding,
                        verify_bundles=False,
                        expected_gpu_worker_leases={0: gpu_binding},
                        allow_stale_session_ledger_watermark=True,
                    )
                    _require(
                        disk_completed == completed,
                        "Single-worker matrix advanced during cell execution.",
                    )
                    execution_resume_payload = _matrix_payload(
                        completed,
                        output_root=layout.output_root,
                        prerequisites=prerequisites,
                        evaluator_binding=evaluator_binding,
                        matrix_lock_binding=lock_binding,
                        gpu_worker_leases={0: gpu_binding},
                    )
                    execution_disk_payload = _refresh_matrix_session_projection(
                        disk_payload=execution_disk_payload,
                        current_resume_payload=execution_resume_payload,
                        matrix_summary=layout.matrix_summary,
                        trust_root=prerequisites.trust_root,
                    )
                    _require(
                        validate_matrix_summary(
                            execution_disk_payload,
                            output_root=layout.output_root,
                            prerequisites=prerequisites,
                            evaluator_script=canonical,
                            evaluator_binding=evaluator_binding,
                            matrix_lock_binding=lock_binding,
                            verify_bundles=False,
                            expected_gpu_worker_leases={0: gpu_binding},
                        )
                        == completed,
                        "Single-worker session projection refresh changed records.",
                    )
                    _assert_cell_claim_binding(claim_binding)
                    if not envelope_path.is_file():
                        if work_result is None:
                            active_session.finalize_eof(
                                published_bundle_reingested=False
                            )
                            persistent_evaluator = None
                        raise ValueError(
                            f"Evaluator did not publish its terminal envelope: {coordinate.key}."
                        )
                    payload = load_and_validate_shard_bundle(
                        envelope_path,
                        coordinate=coordinate,
                        inputs=inputs,
                        launch_nonce=launch_nonce,
                        trust_root=prerequisites.trust_root,
                        gpu_lease_binding=gpu_binding,
                        execution_environment_projection=cast(
                            Mapping[str, Any],
                            prerequisites.public_binding["execution_environment_projection"],
                        ),
                    )
                    decision = cast(str, payload["terminal_decision"])
                    if work_result is not None:
                        _require(
                            work_result.get("terminal_decision") == decision,
                            "Persistent child result differs from its shard envelope.",
                        )
                        _require(
                            work_result.get("envelope_binding")
                            == _file_binding(envelope_path, payload=payload),
                            "Persistent child envelope binding differs from the parent-opened envelope.",
                        )
                    persistent_execution = _persistent_execution_payload(
                        plan=active_session.plan,
                        session_command=active_session.command,
                        work_order=work_order,
                        work_result=work_result,
                        published_bundle_reingested_after_child_eof=(
                            work_result is None
                        ),
                    )
                    record = _run_record(
                        payload,
                        coordinate=coordinate,
                        envelope_path=envelope_path,
                        inputs=inputs,
                        launch_nonce=launch_nonce,
                        command=command,
                        persistent_execution=persistent_execution,
                    )
                    if work_result is not None:
                        _require(
                            cast(Mapping[str, Any], record["artifact_bundle"])["envelope"]
                            == work_result["envelope_binding"],
                            "Persistent envelope changed while constructing its matrix record.",
                        )
                    gpu_lease.assert_held()
                    device_guard_lease.assert_held()
                    _assert_cell_claim_binding(claim_binding)
                    claim_active = False
                    cast(Any, claim_manager).__exit__(None, None, None)
                    claim_path = Path(cast(str, claim_binding["path"]))
                    _require(
                        not os.path.lexists(claim_path),
                        "Single-worker cell claim survived validated release before commit.",
                    )
                    promoted = [*completed, record]
                    promoted_payload = _matrix_payload(
                        promoted,
                        output_root=layout.output_root,
                        prerequisites=prerequisites,
                        evaluator_binding=evaluator_binding,
                        matrix_lock_binding=lock_binding,
                        gpu_worker_leases={0: gpu_binding},
                    )
                    prior_payload = _matrix_payload(
                        completed,
                        output_root=layout.output_root,
                        prerequisites=prerequisites,
                        evaluator_binding=evaluator_binding,
                        matrix_lock_binding=lock_binding,
                        gpu_worker_leases={0: gpu_binding},
                    )
                    try:
                        _atomic_write_json(layout.matrix_summary, promoted_payload)
                        _require(
                            not os.path.lexists(claim_path),
                            "Single-worker cell claim reappeared during authoritative commit.",
                        )
                        _preflight_output_tree(
                            output_root=layout.output_root,
                            matrix_summary=layout.matrix_summary,
                            completed_shards=len(promoted),
                        )
                        validate_matrix_summary(
                            promoted_payload,
                            output_root=layout.output_root,
                            prerequisites=prerequisites,
                            evaluator_script=canonical,
                            evaluator_binding=evaluator_binding,
                            matrix_lock_binding=lock_binding,
                            verify_bundles=False,
                            expected_gpu_worker_leases={0: gpu_binding},
                        )
                        gpu_lease.assert_held()
                        device_guard_lease.assert_held()
                    except BaseException:
                        _atomic_write_json(layout.matrix_summary, prior_payload)
                        raise
                    completed = promoted
                    if work_result is None:
                        active_session.finalize_eof(
                            published_bundle_reingested=True
                        )
                        persistent_evaluator = None
                    else:
                        active_session.mark_committed(
                            work_order=work_order, work_result=work_result
                        )
                new_cells += 1
            except BaseException as error:
                if claim_active:
                    with _exclusive_matrix_lock(
                        layout.lock_path,
                        matrix_summary=layout.matrix_summary,
                        expected_binding=lock_binding,
                    ):
                        claim_active = False
                        cast(Any, claim_manager).__exit__(type(error), error, error.__traceback__)
                raise

        if persistent_evaluator is not None:
            if not persistent_evaluator.closed:
                persistent_evaluator.close()
            elif not persistent_evaluator.terminal_published:
                persistent_evaluator.finalize_eof(
                    published_bundle_reingested=False
                )

        with _exclusive_matrix_lock(
            layout.lock_path,
            matrix_summary=layout.matrix_summary,
            expected_binding=lock_binding,
        ):
            terminal_or_prefix = _matrix_payload(
                completed,
                output_root=layout.output_root,
                prerequisites=prerequisites,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                gpu_worker_leases={0: gpu_binding},
            )
            disk_payload = _load_json_nofollow(
                layout.matrix_summary, label="controller matrix ledger"
            )
            disk_completed = validate_matrix_summary(
                disk_payload,
                output_root=layout.output_root,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                verify_bundles=False,
                expected_gpu_worker_leases={0: gpu_binding},
                allow_stale_session_ledger_watermark=True,
            )
            _require(
                disk_completed == completed,
                "Single-worker matrix changed before session-ledger refresh.",
            )
            disk_payload = _refresh_matrix_session_projection(
                disk_payload=disk_payload,
                current_resume_payload=terminal_or_prefix,
                matrix_summary=layout.matrix_summary,
                trust_root=prerequisites.trust_root,
            )
            _require(
                disk_payload == terminal_or_prefix,
                "Single-worker terminal ledger differs from its authenticated prefix.",
            )
            validate_matrix_summary(
                terminal_or_prefix,
                output_root=layout.output_root,
                prerequisites=prerequisites,
                evaluator_script=canonical,
                evaluator_binding=evaluator_binding,
                matrix_lock_binding=lock_binding,
                verify_bundles=False,
                expected_gpu_worker_leases={0: gpu_binding},
            )
            _preflight_output_tree(
                output_root=layout.output_root,
                matrix_summary=layout.matrix_summary,
                completed_shards=len(completed),
            )
        gpu_lease.assert_held()
        device_guard_lease.assert_held()
        return terminal_or_prefix


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Resume-safe frozen 9,000-shard direct-controller quality matrix."
    )
    parser.add_argument("--manifest", type=Path, default=contract.V1_3_5_MANIFEST_PATH)
    parser.add_argument("--training-output-root", type=Path, default=TRAINING_OUTPUT_ROOT)
    parser.add_argument("--calibration-output-root", type=Path, default=CALIBRATION_OUTPUT_ROOT)
    parser.add_argument("--reuse-admission", type=Path, default=REUSE_ADMISSION_PATH)
    parser.add_argument(
        "--preheldout-genesis", type=Path, default=PREHELDOUT_GENESIS_PATH
    )
    parser.add_argument("--attestation-key-path", type=Path)
    parser.add_argument("--start-mode", choices=QUALITY_START_MODES, required=True)
    parser.add_argument("--output-root", type=Path, default=OUTPUT_ROOT)
    parser.add_argument("--matrix-summary", type=Path)
    parser.add_argument("--max-new-cells", type=int)
    parser.add_argument(
        "--gpu-lock-path",
        type=Path,
        default=DEFAULT_GPU_LOCK_PATH,
        help="Frozen canonical v1.3.5 scheduler lock path; custom paths are rejected.",
    )
    parser.add_argument(
        "--worker-index",
        type=int,
        default=0,
        help="Same-GPU supervisor index; external launches must remain 0.",
    )
    parser.add_argument(
        "--worker-count",
        type=int,
        default=1,
        help=(
            "Manifest-selected same-GPU worker count from 1 through 4."
        ),
    )
    parser.add_argument(
        "--coordinator-only",
        action="store_true",
        help="Internal coordinator mode; external supervisor launches must leave this unset.",
    )
    args = parser.parse_args()
    if args.attestation_key_path is None and not os.environ.get(
        attestation.KEY_PATH_ENV
    ):
        parser.error(
            "--attestation-key-path is required when the external "
            f"{attestation.KEY_PATH_ENV} transport is unavailable."
        )
    try:
        result = run_matrix(
            manifest_path=args.manifest,
            training_output_root=args.training_output_root,
            calibration_output_root=args.calibration_output_root,
            reuse_admission_path=args.reuse_admission,
            preheldout_genesis_path=args.preheldout_genesis,
            output_root=args.output_root,
            matrix_summary=args.matrix_summary,
            evaluator_script=EVALUATOR_SCRIPT,
            attestation_key_path=args.attestation_key_path,
            start_mode=args.start_mode,
            max_new_cells=args.max_new_cells,
            worker_index=args.worker_index,
            worker_count=args.worker_count,
            coordinator_only=args.coordinator_only,
            gpu_lock_path=args.gpu_lock_path,
        )
    except InfrastructurePauseSignal as signal:
        print(
            json.dumps(
                {
                    "status": (
                        "draining_infrastructure"
                        if signal.payload.get("drain_rule") == INFRASTRUCTURE_DRAIN_RULE
                        else "paused_infrastructure"
                    ),
                    "retryable": signal.payload.get("retryable"),
                    "sufficient": signal.payload.get("sufficient"),
                    "required_headroom_bytes": signal.payload.get("required_headroom_bytes"),
                    "filesystem_available_bytes": signal.payload.get("filesystem_available_bytes"),
                },
                sort_keys=True,
            )
        )
        return 3
    if result["status"] == "prerequisites_validated":
        print(
            json.dumps(
                {
                    "experiment_id": result["experiment_id"],
                    "status": result["status"],
                    "expected_shards": result["expected_shards"],
                },
                sort_keys=True,
            )
        )
        return 0
    print(
        json.dumps(
            {
                "experiment_id": result["experiment_id"],
                "status": result["status"],
                "integrity_status": result.get("integrity_status"),
                "completed_shards": result["completed_shards"],
                "canonical_prefix_shards": result["canonical_prefix_shards"],
                "globally_committed_shards": result["globally_committed_shards"],
                "payload_sha256": result["payload_sha256"],
            },
            sort_keys=True,
        )
    )
    if result["status"] in {"paused_infrastructure", "draining_infrastructure"}:
        return 3
    if result["status"] == "terminal" and result["integrity_status"] == "INTEGRITY-FAIL":
        return 2
    return 0


_require(EXPECTED_SHARDS == 9_000, "Frozen direct-controller matrix cardinality drifted.")
_require(EXAMPLES_PER_SHARD == 20, "Frozen direct-controller shard size drifted.")
_require(
    sum(expected_decode_token_rows(item) for item in coordinates())
    == contract.EXPECTED_RAW_TOKEN_ROWS_WITHOUT_FAILURES,
    "Frozen direct-controller decode-token projection weight drifted.",
)
_require(
    ARM_NAMES == tuple(contract.ALL_ARM_NAMES) and len(ARM_NAMES) == 17,
    "Frozen direct-controller exact-fill arm inventory drifted.",
)


if __name__ == "__main__":
    raise SystemExit(main())
